def extract_israeli_address_from_text(text: str) -> str:
    """
    Extracts an Israeli street + house number + city or settlement address from a customer message.
    Returns '' if the message is a device/product/filter/troubleshooting reply rather than an address.
    """
    raw = (text or "").strip()
    if not raw or len(raw) > 120:
        return ""

    # Never treat pure option numbers ("1", "2", "3"), phone numbers, or device/package selection phrases as addresses
    if re.match(r"^(?:[123]\.?|אחת|אחד|שתיים|שלוש|רגיל|כשר|מכשיר רגיל|מכשיר כשר|תפרט|תרחיב|כל ההצעות|הכל|כן|לא)$", raw.strip(), re.IGNORECASE):
        return ""
    if re.search(r"05\d[-\s]?\d{7}", raw):
        return ""

    raw_low = raw.lower()
    non_addr_keywords = [
        "f21", "f22", "f25", "q8", "qlyx", "אייפון", "איפון", "iphone", "גלקסי", "galaxy", "סמסונג",
        "שיאומי", "נוקיה", "אסקולס", "החלפת מסך", "סוללה", "שקע טעינה", "כשר פליי", "נטספרק",
        "מכשיר רגיל", "מכשיר כשר", "לפי מחיר", "הזול ביותר", "גלישה מהירה", "כל ההצעות", "שעות פעילות",
        "קוראים לי", "שמי ", "תחזור אלי", "תחזרו אלי", "תתקשר אלי"
    ]
    if any(nk in raw_low for nk in non_addr_keywords) and not any(
        ap in raw_low for ap in ["ברחוב ", "בכתובת ", "אני גר ב", "אני גרה ב", "לבדוק קליטה ב", "בדיקת קליטה ב"]
    ):
        return ""

    # Strip conversational prefixes
    clean = re.sub(
        r"^.*?(?:לבדוק קליטה וחבילות סלולר ב-?|לבדוק קליטה ב-?|בדיקת קליטה ב-?|בדיקת אנטנות\s*:?\s*|תבדוק לי קליטה ב-?|תבדוק קליטה ב-?|תבדוק לי ב-?|תבדוק ב-?|בעיות קליטה ב-?|אין קליטה ב-?|קליטה חלשה ב-?|הכתובת שלי היא|הכתובת שלי|הכתובת היא|אני גר ב-?|אני גרה ב-?|בכתובת|כתובת\s*:?)\s*",
        "",
        raw,
        flags=re.IGNORECASE,
    ).strip()
    clean = re.sub(
        r"^(?:שלום|היי|הי|אהלן|בוקר טוב|ערב טוב|אני\s+מ-?)\s*,?\s*",
        "",
        clean,
        flags=re.IGNORECASE,
    ).strip()

    matched_city = ""
    for city in ISRAEL_SETTLEMENTS_LIST:
        if re.search(rf"(?:^|[\s,\-ב]){re.escape(city)}(?:$|[\s,.\?!])", clean):
            matched_city = city
            break

    has_street_and_num = bool(
        re.search(r"(?:רחוב|רח['׳]|שדרות|שד['׳]|סמטת|דרך|כיכר)\s+[א-ת]+|[א-ת]{2,}(?:\s+[א-ת]{2,})?\s+\d{1,3}(?:\b|$)", clean)
    )

    question_only_words = [
        "בעיות קליטה", "אין קליטה", "איזה חברה", "איזו חברה", "אינטרנט איטי",
        "כמה עולה חבילה", "לעבור חברה", "להחליף חברה", "בעיות גלישה", "לא מבסוט", "משלם יקר"
    ]
    if any(qw in clean.lower() for qw in question_only_words):
        if matched_city:
            m_addr = re.search(
                rf"(?:ב-?|ברחוב\s+|בכתובת\s+)?([א-ת\s'\"״׳]+\d{{1,3}}\s*,?\s*{re.escape(matched_city)}|{re.escape(matched_city)}\s*,?\s*[א-ת\s'\"״׳]+\d{{1,3}}|{re.escape(matched_city)})",
                clean,
            )
            if m_addr:
                return m_addr.group(1).strip(" .,?!")
        return ""

    if matched_city and (has_street_and_num or len(clean.split()) <= 5):
        return clean.strip(" .,?!")
    if has_street_and_num and len(clean.split()) <= 6:
        return clean.strip(" .,?!")
    return ""


def detect_cellular_device_type_choice(text: str) -> str:
    """
    Detects whether the customer wants a cellular package for a Kosher phone ('kosher')
    or a Regular smartphone ('regular').
    """
    clean = auto_fix_common_hebrew_typos((text or "").strip().lower())
    if not clean:
        return ""
    if any(k in clean for k in ["לא כשר", "מכשיר רגיל", "טלפון רגיל", "פלאפון רגיל", "סמארטפון", "אייפון", "גלקסי"]):
        return "regular"
    if re.search(r"(?:^|\s)(?:רגיל|רגילה)(?:$|\s|[,.!?])", clean):
        return "regular"
    if any(k in clean for k in ["כשר", "כשרה", "למכשיר כשר", "קו כשר", "שיחות בלבד"]):
        return "kosher"
    # If customer directly specified a regular browsing filter (e.g. "גלישה מהירה", "דור 5", "הכי זול עם אינטרנט")
    if any(k in clean for k in ["גלישה", "אינטרנט", "דור 5", "5g", " ג'יגה", " גיגה", "gb"]):
        return "regular"
    return ""


def detect_cellular_regular_filter_choice(text: str) -> str:
    """
    For a regular device, detects how the customer wants to filter packages:
    - 'cheapest': לפי מחיר זול ביותר
    - 'fastest': לפי חבילת הגלישה המהירה ביותר (דור 5 / נפח גבוה)
    - 'all': לראות את כל ההצעות
    """
    clean = auto_fix_common_hebrew_typos((text or "").strip().lower())
    if not clean:
        return ""
    if any(k in clean for k in [
        "כל ההצעות", "את כל ההצעות", "לראות הכל", "תראה הכל", "הכל", "כל החבילות",
        "את כל החבילות", "תרחיב", "תפרט", "פירוט מלא"
    ]) or clean in ("3", "3.", "שלוש", "אפשרות 3"):
        return "all"
    if any(k in clean for k in [
        "מהיר", "מהירה", "המהירה ביותר", "הכי מהיר", "הכי מהירה", "גלישה מהירה",
        "חבילת גלישה", "דור 5", "דור חמש", "5g", "נפח גבוה", "הרבה גיגה"
    ]) or clean in ("2", "2.", "שתיים", "אפשרות 2"):
        return "fastest"
    if any(k in clean for k in [
        "זול", "זולה", "הזול ביותר", "הזולה ביותר", "הכי זול", "הכי זולה",
        "מחיר זול", "לפי מחיר", "משתלם", "משתלמת", "הכי משתלם"
    ]) or clean in ("1", "1.", "אחת", "אחד", "אפשרות 1"):
        return "cheapest"
    return ""


def is_cellular_expand_request(text: str) -> bool:
    """
    Detects when the customer asks the bot to expand and show full details on antennas or packages.
    """
    clean = auto_fix_common_hebrew_typos((text or "").strip().lower())
    if not clean:
        return False
    expand_terms = [
        "תרחיב", "תפרט", "אשמח לפירוט", "פירוט מלא", "תן פירוט", "כל ההצעות",
        "לראות את כל ההצעות", "תראה את כל ההצעות", "תראה הכל", "לראות הכל",
        "כל החבילות", "עוד הצעות", "עוד חבילות", "כל האנטנות", "פירוט אנטנות", "מה עוד יש"
    ]
    return any(t in clean for t in expand_terms)


def format_regular_filter_question(address: str, top_network_name: str = "") -> str:
    """
    Builds the concise question asking a regular-device customer whether they want to filter by
    cheapest price, fastest browsing package, or see all offers.
    """
    net_hint = f" (מותאם לרשת *{top_network_name}* החזקה באזורך)" if top_network_name else ""
    return (
        f"מעולה! איך תרצה שנסנן עבורך את החבילות למכשיר רגיל{net_hint}? 👇\n"
        f"1️⃣ *לפי המחיר הזול ביותר* 💰\n"
        f"2️⃣ *לפי חבילת הגלישה המהירה ביותר (דור 5 / 5G)* 🚀\n"
        f"3️⃣ *לראות את כל ההצעות* 📋"
    )


