def get_dynamic_template(template_key: str, default_val: str = "") -> str:
    """Fetches an editable system template (such as WARRANTY_FULL_EXPLANATION or STORE_HOURS_DETAILS) from SQLite."""
    try:
        conn = sqlite3.connect(DB_PATH)
        row = conn.execute("SELECT content FROM dynamic_templates WHERE template_key = ? LIMIT 1", (template_key,)).fetchone()
        conn.close()
        if row and row[0] and str(row[0]).strip():
            return str(row[0])
    except Exception:
        pass
    return default_val

def set_dynamic_template(template_key: str, content: str):
    """Permanently updates an editable system template in SQLite and syncs to JSON cache."""
    try:
        conn = sqlite3.connect(DB_PATH)
        conn.execute(
            "INSERT OR REPLACE INTO dynamic_templates (template_key, content, updated_at) VALUES (?, ?, ?)",
            (template_key, content, datetime.now().isoformat())
        )
        conn.commit()
        conn.close()
        sync_dynamic_templates_to_json()
    except Exception as e:
        print(f"[Set Dynamic Template Notice]: {e}")

def _remove_phrase_cleanly(text: str, phrase: str) -> str:
    """Removes a phrase or word from text while cleaning up adjacent slashes, conjunctions (ו...), parentheses, and punctuation."""
    if not text or not phrase:
        return text or ""
    p_clean = phrase.strip()
    if not p_clean:
        return text
    out = text
    # Build both exact phrase and base phrase without leading conjunction 'ו' (e.g. 'ונזק לקוח' -> 'נזק לקוח')
    forms = [p_clean]
    if p_clean.startswith("ו") and len(p_clean) >= 3:
        no_vav = re.sub(r"^ו-?", "", p_clean).strip()
        if no_vav and no_vav not in forms:
            forms.append(no_vav)

    for pf in forms:
        # 1. Remove slash-separated occurrences: " / קורוזיה" or "קורוזיה / "
        out = re.sub(rf"\s*/\s*(?:תיקון\s+)?{re.escape(pf)}(?=\s*[/\)\],.!]|$)", "", out, flags=re.IGNORECASE)
        out = re.sub(rf"(?<=[\(\[/\s])(?:תיקון\s+)?{re.escape(pf)}\s*/\s*", "", out, flags=re.IGNORECASE)
        # 2. Remove comma-separated or conjunction occurrences: ", קורוזיה" or " וקורוזיה" or " ו-קורוזיה"
        out = re.sub(rf"\s*,\s*(?:תיקון\s+)?{re.escape(pf)}(?=\s*[,\)\].!]|$)", "", out, flags=re.IGNORECASE)
        out = re.sub(rf"\s+ו-?(?:תיקון\s+)?{re.escape(pf)}(?=[\s,!.)\]*]|$)", "", out, flags=re.IGNORECASE)
        out = re.sub(rf"\b{re.escape(pf)}\s+ו-?", "", out, flags=re.IGNORECASE)
        # 3. Direct substring removal if still present
        if pf in out:
            out = out.replace(pf, "")

    # 4. Clean up parenthetical leftovers like "תיקון (שבר / נפילה)" -> "תיקון שבר / נפילה"
    out = re.sub(r"(תיקון)\s+\(([^)\n]+)\)", r"\1 \2", out)
    # 5. Clean up artifacts like "/ /", "( / ", " / )", double spaces, space before '!' or ')'
    out = re.sub(r"\(\s*/\s*", "(", out)
    out = re.sub(r"\s*/\s*\)", ")", out)
    out = re.sub(r"/\s*/", "/", out)
    out = re.sub(r"\(\s*\)", "", out)
    out = re.sub(r"\s+([!?,.)])", r"\1", out)
    out = re.sub(r"[ \t]{2,}", " ", out)
    # Remove bullet lines that became empty
    cleaned_lines = []
    for ln in out.splitlines():
        if re.match(r"^\s*[•\-\*]\s*[:.!]*\s*$", ln):
            continue
        cleaned_lines.append(ln.rstrip())
    return "\n".join(cleaned_lines)

def sync_style_rules_to_json():
    """Exports learned_style_rules to local JSON cache for durability across restarts."""
    try:
        conn = sqlite3.connect(DB_PATH)
        rows = conn.execute(
            "SELECT pattern_from, replacement_to, rule_instruction, created_at FROM learned_style_rules ORDER BY id ASC"
        ).fetchall()
        conn.close()
        data = [
            {"pattern_from": r[0], "replacement_to": r[1], "rule_instruction": r[2], "created_at": r[3]}
            for r in rows
        ]
        with open(BACKUP_STYLE_JSON_PATH, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
    except Exception:
        pass

def apply_learned_style_rules(text: str) -> str:
    """
    Applies all permanent phrasing & style replacements AND deletions taught by Eran
    (via '22015743:', 'תיקון:', or style instructions) to any outgoing customer text or KB answer.
    """
    if not text:
        return ""
    out = text
    # Always enforce core default phrasing replacement first
    out = re.sub(
        r"האם\s+תרצה\s+(?:שנזמין|שאזמין|להזמין)(?:\s+עבורך|\s+לך)?\s+את\s+החלק\s*\??",
        "מה תרצה להזמין?",
        out
    )
    # Enforce current dynamic short track descriptions on device price quotes for ALL 3 tracks (גלות, ימות המשיח, גאולה)
    try:
        curr_galut_desc = get_track_short_desc("galut")
        if curr_galut_desc:
            out = re.sub(
                r"(•\s*\*?מסלול\s+גלות\*?\s*)\([^\)\n]+\)",
                lambda m: f"{m.group(1)}({curr_galut_desc})",
                out
            )
        curr_yemot_desc = get_track_short_desc("yemot")
        if curr_yemot_desc:
            out = re.sub(
                r"(•\s*(?:⭐\s*)?\*?מסלול\s+ימות\s+המשיח\*?\s*)\([^\)\n]+\)",
                lambda m: f"{m.group(1)}({curr_yemot_desc})",
                out
            )
        curr_geula_desc = get_track_short_desc("geula")
        if curr_geula_desc:
            out = re.sub(
                r"(•\s*(?:🛡️\s*)?\*?מסלול\s+גאולה\*?\s*)\([^\)\n]+\)",
                lambda m: f"{m.group(1)}({curr_geula_desc})",
                out
            )
    except Exception:
        pass
    try:
        conn = sqlite3.connect(DB_PATH)
        rows = conn.execute("SELECT pattern_from, replacement_to FROM learned_style_rules ORDER BY id ASC").fetchall()
        conn.close()
        for pat_from, repl_to in rows:
            if not pat_from:
                continue
            r_to = repl_to if repl_to is not None else ""
            if r_to == "" or r_to == "[DELETE]":
                # Deletion rule!
                out = _remove_phrase_cleanly(out, pat_from)
            else:
                if pat_from in out:
                    out = out.replace(pat_from, r_to)
                else:
                    pat_no_q = pat_from.rstrip("?.! ").strip()
                    if len(pat_no_q) >= 3 and pat_no_q in out:
                        out = re.sub(rf"{re.escape(pat_no_q)}\s*\??", r_to, out)
    except Exception:
        pass
    return out

def get_learned_style_instructions() -> str:
    """Returns formatted permanent style instructions for Gemini AI system prompt."""
    try:
        conn = sqlite3.connect(DB_PATH)
        rows = conn.execute("SELECT DISTINCT rule_instruction FROM learned_style_rules WHERE rule_instruction != ''").fetchall()
        conn.close()
        if not rows:
            return "- בסיום פירוט אפשרויות או מחיר לחלק/אביזר, שאל תמיד: 'מה תרצה להזמין? 😃' (לעולם אל תשאל 'האם תרצה שאזמין עבורך את החלק?')."
        return "\n".join([f"- {r[0]}" for r in rows])
    except Exception:
        return "- בסיום פירוט אפשרויות או מחיר לחלק/אביזר, שאל תמיד: 'מה תרצה להזמין? 😃'."

def save_permanent_style_rule(pattern_from: str, replacement_to: str, rule_instruction: str):
    """Saves a permanent style rule (replacement OR deletion) to SQLite + JSON and rewrites learned_kb & dynamic_templates."""
    try:
        pf = (pattern_from or "").strip()
        rt = (replacement_to or "").strip()
        ri = (rule_instruction or "").strip()
        conn = sqlite3.connect(DB_PATH)
        conn.execute(
            "INSERT INTO learned_style_rules (pattern_from, replacement_to, rule_instruction, created_at) VALUES (?, ?, ?, ?)",
            (pf, rt, ri, datetime.now().isoformat())
        )
        conn.commit()
        conn.close()

        # Immediately rewrite any existing learned_kb entries & dynamic_templates that contain pattern_from!
        if pf:
            conn = sqlite3.connect(DB_PATH)
            kb_rows = conn.execute("SELECT id, answer FROM learned_kb").fetchall()
            for r_id, r_ans in kb_rows:
                if not r_ans:
                    continue
                new_ans = apply_learned_style_rules(r_ans)
                if new_ans != r_ans:
                    conn.execute("UPDATE learned_kb SET answer = ? WHERE id = ?", (new_ans, r_id))
            tmpl_rows = conn.execute("SELECT template_key, content FROM dynamic_templates").fetchall()
            for t_key, t_content in tmpl_rows:
                if not t_content:
                    continue
                new_tc = apply_learned_style_rules(t_content)
                if new_tc != t_content:
                    conn.execute("UPDATE dynamic_templates SET content = ?, updated_at = ? WHERE template_key = ?", (new_tc, datetime.now().isoformat(), t_key))
            conn.commit()
            conn.close()
        sync_style_rules_to_json()
        sync_learned_kb_to_json()
        sync_dynamic_templates_to_json()
    except Exception as e:
        print(f"[Save Style Rule Notice]: {e}")


