def save_contact_name(phone: str, name: str):
    clean_name = name.strip()
    norm_phone = normalize_phone(phone)
    if not clean_name or not norm_phone or clean_name in COMMON_NON_NAMES:
        return
    # Guard: never overwrite permanent admin/owner contacts
    if norm_phone in PERMANENT_CONTACTS:
        return
    try:
        conn = sqlite3.connect(DB_PATH)
        conn.execute("""
            INSERT INTO contacts (phone, name, created_at, updated_at)
            VALUES (?, ?, ?, ?)
            ON CONFLICT(phone) DO UPDATE SET name=excluded.name, updated_at=excluded.updated_at
        """, (norm_phone, clean_name, datetime.now().isoformat(), datetime.now().isoformat()))
        conn.commit()
        conn.close()
        sync_contacts_to_json()
    except Exception as exc:
        print(f"[Save Contact Notice]: {exc}")

def extract_name_from_text(text: str) -> str:
    cleaned = re.sub(r"[^\w\sא-ת]", " ", text or "").strip()
    if not cleaned:
        return ""

    # 1. Explicit self-identification patterns only
    explicit_patterns = [
        r"(?:שמי(?:\s+הוא)?|קוראים\s+לי|השם\s+שלי(?:\s+הוא)?)\s+([א-ת]{2,15})",
        r"^(?:שלום\s*,?\s*)?(?:מדבר|מדברת)\s+([א-ת]{2,15})",
        r"^(?:אני|זה)\s+([א-ת]{2,15})\s*$",
        r"^([א-ת]{2,15})\s+כאן\s*$"
    ]
    for pattern in explicit_patterns:
        match = re.search(pattern, cleaned)
        if match:
            candidate = match.group(1).strip()
            if candidate not in COMMON_NON_NAMES:
                return candidate

    # 2. Strict 1-2 words name ONLY if all words are valid Hebrew letters and NOT in COMMON_NON_NAMES
    words = cleaned.split()
    if 1 <= len(words) <= 2:
        if all(re.fullmatch(r"[א-ת]{2,15}", w) and w not in COMMON_NON_NAMES for w in words):
            return words[0]

    return ""

def get_contact_name(phone: str) -> str:
    norm = normalize_phone(phone)
    if not norm:
        return ""
    if norm in PERMANENT_CONTACTS:
        return PERMANENT_CONTACTS[norm].split()[0]
    for p, n in PERMANENT_CONTACTS.items():
        clean_p = normalize_phone(p)
        if clean_p and len(clean_p) >= 9 and len(norm) >= 9:
            if clean_p[-9:] == norm[-9:]:
                return n.split()[0]

    try:
        conn = sqlite3.connect(DB_PATH)
        row = conn.execute(
            "SELECT name FROM contacts WHERE phone = ? OR phone LIKE ? LIMIT 1",
            (norm, f"%{norm[-9:]}%" if len(norm) >= 9 else f"%{norm}%")
        ).fetchone()
        conn.close()
        if row and row[0] and row[0].strip() not in COMMON_NON_NAMES:
            return row[0].strip().split()[0]
    except Exception:
        pass

    return ""

def save_chat_message(phone: str, role: str, text: str):
    norm_phone = normalize_phone(phone)
    clean_text = text.strip()
    if not norm_phone or not clean_text:
        return
    try:
        conn = sqlite3.connect(DB_PATH)
        conn.execute("""
            INSERT INTO conversation_history (phone, role, message, created_at)
            VALUES (?, ?, ?, ?)
        """, (norm_phone, role, clean_text, datetime.now().isoformat()))
        conn.commit()
        conn.close()
    except Exception:
        pass

def get_recent_chat_history(phone: str, limit: int = 6) -> str:
    norm_phone = normalize_phone(phone)
    if not norm_phone:
        return ""
    try:
        conn = sqlite3.connect(DB_PATH)
        rows = conn.execute("""
            SELECT role, message FROM conversation_history
            WHERE phone = ? OR phone LIKE ?
            ORDER BY id DESC LIMIT ?
        """, (norm_phone, f"%{norm_phone[-9:]}%" if len(norm_phone) >= 9 else f"%{norm_phone}%", limit)).fetchall()
        conn.close()
        if not rows:
            return ""
        rows.reverse()
        lines = []
        for r, msg in rows:
            sender = "לקוח" if r == "customer" else "סוכן"
            lines.append(f"[{sender}]: {msg}")
        return "\n".join(lines)
    except Exception:
        return ""

def has_already_greeted_customer(phone: str) -> bool:
    norm_phone = normalize_phone(phone)
    if not norm_phone:
        return False
    try:
        conn = sqlite3.connect(DB_PATH)
        count = conn.execute("""
            SELECT COUNT(*) FROM conversation_history
            WHERE (phone = ? OR phone LIKE ?) AND role = 'agent'
        """, (norm_phone, f"%{norm_phone[-9:]}%" if len(norm_phone) >= 9 else f"%{norm_phone}%")).fetchone()[0]
        conn.close()
        return count > 0
    except Exception:
        return False


def get_conversation_message_count(phone: str) -> int:
    norm_phone = normalize_phone(phone)
    if not norm_phone:
        return 0
    try:
        conn = sqlite3.connect(DB_PATH)
        count = conn.execute("""
            SELECT COUNT(*) FROM conversation_history
            WHERE phone = ? OR phone LIKE ?
        """, (norm_phone, f"%{norm_phone[-9:]}%" if len(norm_phone) >= 9 else f"%{norm_phone}%")).fetchone()[0]
        conn.close()
        return count
    except Exception:
        return 0

def strip_customer_name(text: str, name: str) -> str:
    if not name or name in COMMON_NON_NAMES:
        return text
    cleaned = text
    # Strip from start: e.g. "ערן, ", "היי ערן, ", "שלום ערן: "
    cleaned = re.sub(rf"^(?:שלום|היי|הי|אהלן)?[\s,]*{re.escape(name)}[\s,:-]*", "", cleaned, flags=re.IGNORECASE).strip()
    # Strip vocative in middle: e.g. "אני מבין ערן ש..." -> "אני מבין ש..."
    cleaned = re.sub(rf"[\s,]+{re.escape(name)}[\s,]+", " ", cleaned).strip()
    # Strip from end: e.g. "... ערן." -> "..."
    cleaned = re.sub(rf"[\s,]+{re.escape(name)}[?!.]*$", "", cleaned).strip()
    return cleaned

def purge_unwanted_phrases(text: str) -> str:
    cleaned = text
    cleaned = re.sub(r"בודק(?:\s+זאת|\s+כעת)?\s+מול\s+המעבדה(?:\s+שלנו)?", "בודק כעת את המחיר העדכני", cleaned)
    cleaned = re.sub(r"מול\s+המעבדה(?:\s+שלנו)?", "את המחיר העדכני", cleaned)
    cleaned = re.sub(r"[ \t]{2,}", " ", cleaned).strip()
    return cleaned

def apply_customer_name_guard(reply_text: str, customer_name: str, already_greeted: bool, msg_count: int = 2, is_closing: bool = False) -> str:
    cleaned = reply_text.strip()

    # Strip unwanted prompts asking for customer's name
    cleaned = re.sub(
        r"(?:ו?איך\s+קוראים\s+לך(?:\s+כדי\s+שאדע\s+למי\s+לפנות)?[\s?!.,]*|ו?מה\s+שמך(?:\s+בבקשה)?[\s?!.,]*|תגיד\s+מה\s+השם\s+שלך[\s?!.,]*|למי\s+לפנות[\s?!.,]*)",
        "",
        cleaned,
        flags=re.IGNORECASE
    ).strip()

    cleaned = purge_unwanted_phrases(cleaned)

    if not customer_name or customer_name in COMMON_NON_NAMES:
        return cleaned

    is_start = (msg_count <= 1 and not already_greeted)
    is_middle = (msg_count in [4, 5])

    # 1. End of conversation (סוף): Name is warmly allowed
    if is_closing:
        return cleaned

    # 2. Beginning of conversation (התחלה): Name is used with greeting
    if is_start:
        has_name = customer_name in cleaned
        has_how_are_you = any(p in cleaned for p in ["מה שלומך", "מה נשמע"])
        if not has_name or not has_how_are_you:
            salutation = f"שלום {customer_name}, מה שלומך?"
            greeting_pattern = r"^(?:שלום|היי|הי|בוקר טוב|ערב טוב|אהלן)(?:\s+[א-ת]+)?(?:[\s,]+(?:מה\s+שלומך|מה\s+נשמע))?[\s!.,]*"
            if re.match(greeting_pattern, cleaned):
                cleaned = re.sub(greeting_pattern, f"{salutation} ", cleaned, count=1)
            else:
                cleaned = f"{salutation} {cleaned}"
        return cleaned.strip()

    # 3. Middle of conversation (אמצע, turns 4-5): Allow name once, but strip opening greetings
    if is_middle:
        pattern_with_name_simple = rf"^(?:שלום|היי|הי|אהלן|בוקר טוב|ערב טוב|צהריים טובים)[\s,]+(?:{re.escape(customer_name)})[\s?!.,-]*"
        cleaned = re.sub(pattern_with_name_simple, "", cleaned, flags=re.IGNORECASE).strip()
        return cleaned

    # 4. All other intermediate turns: Strictly strip customer name so the bot is not tiresome or repetitive!
    cleaned = strip_customer_name(cleaned, customer_name)
    return cleaned.strip()

