def is_customer_style_new_inquiry(text: str) -> bool:
    """
    Returns True if the incoming text clearly looks like a customer initiating a new inquiry
    (e.g., asking store hours, asking who the owner is, asking device prices, reporting a broken device,
    or asking to schedule a new appointment). Used so that when an Admin replies naturally without
    writing 'תשובה:', the server distinguishes Admin replies from customer test inquiries.
    """
    clean = (text or "").strip().lower()
    if not clean:
        return False
    # Explicit admin prefix, style/tikun command, or 3rd-person instruction to bot is NEVER a customer inquiry
    if is_admin_style_or_tikun_command(clean) or is_admin_bit_payment_directive(clean):
        return False
    if re.match(r"^(?:תשובה|תיקון|כלל|שישאל|תשאל|תגיד\s+לו|תמסור\s+לו|תכתוב\s+לו|תעדכן\s+אותו|שיכנס|שילחץ|שיבצע|צריך\s+לשלוח|תשלח\s+ללקוח)", clean):
        return False
    if is_pure_greeting(clean) or is_store_info_question(clean) or is_store_owner_question(clean):
        return True
    cust_sched_initiators = [
        "אפשר לקבוע", "אפשר לתאם", "רוצה לקבוע", "רוצה לתאם", "אשמח לקבוע", "אשמח לתאם",
        "מתי אפשר לקבוע", "מתי אפשר לתאם", "לקבוע תור", "לתאם תור", "לקבוע מחר",
        "תור לתיקון", "חור לתיקון", "תור למעבדה", "תור לרכוש", "תור לקנות", "תור לרכישת",
        "שלא יצטרך להמתין", "שלא אצטרך להמתין"
    ]
    if any(k in clean for k in cust_sched_initiators):
        return True
    cust_inquiry_phrases = [
        "כמה עולה", "מה המחיר", "יש לכם", "יש לי בעיה", "נשבר לי", "המכשיר שלי",
        "הטלפון שלי", "הפלאפון שלי", "אני צריך", "אני רוצה לרכוש", "אני רוצה לקנות",
        "האם אתם מתקנים", "אתם מתקנים", "מה ההבדל בין"
    ]
    if any(k in clean for k in cust_inquiry_phrases):
        return True
    return False

def is_master_override_code_command(text: str) -> bool:
    """
    Detects if an incoming WhatsApp message starts with the universal Master Override Code:
    Supports BOTH '22015743:' and '22015473:' (and any 2201xxxx code with ':', '-', or space).
    Works from ANY chat or phone number!
    """
    clean = (text or "").strip()
    if not clean:
        return False
    return bool(
        re.match(r"^(?:22015743|22015473|2201\d{4})\s*(?:[:\-]\s*|\s+).+$", clean, flags=re.DOTALL)
    )


def _edit_warranty_track_section(full_warranty_text: str, track_name: str, edit_fn) -> str:
    """
    Applies `edit_fn(section_text)` ONLY to the specified warranty track section
    ('גלות', 'ימות המשיח', or 'גאולה') inside WARRANTY_FULL_EXPLANATION,
    or across the whole text if the section header is not found.
    """
    headers = [
        ("גלות", r"(🔴\s*\*?1\.\s*מסלול\s+גלות.*?)(?=\n\s*🟡|\Z)"),
        ("ימות המשיח", r"(🟡\s*\*?2\.\s*מסלול\s+ימות\s+המשיח.*?)(?=\n\s*🟢|\Z)"),
        ("גאולה", r"(🟢\s*\*?3\.\s*מסלול\s+גאולה.*?)\Z"),
    ]
    for t_key, pat in headers:
        if t_key == track_name:
            m = re.search(pat, full_warranty_text, flags=re.DOTALL)
            if m:
                old_sec = m.group(1)
                new_sec = edit_fn(old_sec)
                return full_warranty_text[:m.start(1)] + new_sec + full_warranty_text[m.end(1):]
    return edit_fn(full_warranty_text)


def _extract_track_section_preview(full_warranty_text: str, track_name: str) -> str:
    headers = [
        ("גלות", r"(🔴\s*\*?1\.\s*מסלול\s+גלות.*?)(?=\n\s*🟡|\Z)"),
        ("ימות המשיח", r"(🟡\s*\*?2\.\s*מסלול\s+ימות\s+המשיח.*?)(?=\n\s*🟢|\Z)"),
        ("גאולה", r"(🟢\s*\*?3\.\s*מסלול\s+גאולה.*?)\Z"),
    ]
    for t_key, pat in headers:
        if t_key == track_name:
            m = re.search(pat, full_warranty_text, flags=re.DOTALL)
            if m:
                return m.group(1).strip()
    return full_warranty_text.strip()


def _apply_verbatim_track_replacement(tr_name: str, verbatim_text: str, used_code: str, is_append_only: bool = False) -> tuple[str, str]:
    """
    Updates a specific warranty track ('גלות', 'ימות המשיח', or 'גאולה') across BOTH:
    1. TRACK_SHORT_<TRACK> (used in device price quotes)
    2. WARRANTY_FULL_EXPLANATION (the 3-track comparison template)
    Supports single-line parentheticals, single-line full descriptions, and multi-line bulleted sections!
    Returns (new_full_warranty_text, updated_short_desc).
    """
    tpl_key_map = {
        "גלות": "TRACK_SHORT_GALUT",
        "ימות המשיח": "TRACK_SHORT_YEMOT",
        "גאולה": "TRACK_SHORT_GEULA",
    }
    default_header_map = {
        "גלות": "🔴 *1. מסלול גלות (אחריות יבואן ארצית - טיפול עד 21 ימי עסקים):*",
        "ימות המשיח": "🟡 *2. מסלול ימות המשיח (האחריות המומלצת שלנו ⭐):*",
        "גאולה": "🟢 *3. מסלול גאולה (VIP פרימיום — שקט מושלם 🛡️):*",
    }
    tpl_key = tpl_key_map.get(tr_name, "TRACK_SHORT_GALUT")
    old_short_desc = get_track_short_desc(tr_name)

    raw_clean = (verbatim_text or "").strip()
    lines = [ln.strip() for ln in raw_clean.splitlines() if ln.strip()]
    is_multiline = len(lines) >= 2 or any(ln.startswith(("•", "-", "*")) for ln in lines[1:])

    # Determine the short inline description for device quotes
    short_desc_candidate = ""
    if not is_multiline:
        # Single-line replacement
        s_clean = re.sub(rf"^(?:🔴|🟡|🟢)?\s*\*?(?:[123]\.\s*)?מסלול\s+{re.escape(tr_name)}\*?\s*[:\-–—]?\s*", "", raw_clean, flags=re.IGNORECASE).strip()
        s_clean = s_clean.strip(" ()\t\n\"'").rstrip(".")
        if s_clean:
            short_desc_candidate = s_clean
    else:
        # Multi-line replacement: check if line 0 has parenthetical header e.g. "מסלול גאולה (...):"
        m_hdr_paren = re.search(rf"מסלול\s+{re.escape(tr_name)}\s*\(([^)\n]+)\)", lines[0])
        if m_hdr_paren:
            short_desc_candidate = m_hdr_paren.group(1).strip()
        else:
            # Summarize bullet lines into a clean inline short description
            bullet_summaries = []
            for bl in lines:
                if re.search(rf"מסלול\s+{re.escape(tr_name)}", bl) and not bl.startswith(("•", "-")):
                    continue
                b_txt = re.sub(r"^[•\-\*]+\s*", "", bl).replace("*", "").strip().rstrip(".")
                if b_txt:
                    bullet_summaries.append(b_txt)
            if bullet_summaries:
                short_desc_candidate = " | ".join(bullet_summaries[:2])

    if not is_append_only and short_desc_candidate:
        set_dynamic_template(tpl_key, short_desc_candidate)
        # Update all learned_kb entries that mention this track
        try:
            conn = sqlite3.connect(DB_PATH)
            kb_rows = conn.execute("SELECT id, answer FROM learned_kb").fetchall()
            for k_id, k_ans in kb_rows:
                if not k_ans:
                    continue
                new_k_ans = re.sub(
                    rf"(•\s*\*?(?:⭐\s*|🛡️\s*)?\*?מסלול\s+{re.escape(tr_name)}\*?\s*)\([^\)\n]+\)",
                    lambda m: f"{m.group(1)}({short_desc_candidate})",
                    k_ans
                )
                if new_k_ans != k_ans:
                    conn.execute("UPDATE learned_kb SET answer = ? WHERE id = ?", (new_k_ans, k_id))
            conn.commit()
            conn.close()
            sync_learned_kb_to_json()
        except Exception:
            pass
        if old_short_desc and old_short_desc != short_desc_candidate:
            save_permanent_style_rule(
                f"מסלול {tr_name} ({old_short_desc})",
                f"מסלול {tr_name} ({short_desc_candidate})",
                f"הנחיית קוד מאסטר ({used_code}) למסלול {tr_name}: ({short_desc_candidate})"
            )

    curr_warranty = get_dynamic_template("WARRANTY_FULL_EXPLANATION", WARRANTY_FULL_EXPLANATION)

    def _replace_or_append_track_sec(sec_txt: str) -> str:
        sec_lines = [ln for ln in sec_txt.splitlines() if ln.strip()]
        existing_header = sec_lines[0] if sec_lines else default_header_map.get(tr_name, f"*מסלול {tr_name}:*")

        if is_append_only:
            add_clean = raw_clean.strip(" ()\t\n.,!\"'").strip()
            bullet_line = f"• {add_clean}." if not add_clean.endswith((".", "!")) else f"• {add_clean}"
            if add_clean in sec_txt:
                return sec_txt
            return sec_txt.rstrip() + "\n" + bullet_line

        if is_multiline:
            # Check if the user's first line already includes the track header ("מסלול גאולה...")
            first_ln = lines[0]
            if re.search(rf"מסלול\s+{re.escape(tr_name)}", first_ln):
                # Ensure it has the emoji/number prefix if user omitted it
                if not any(em in first_ln for em in ("🔴", "🟡", "🟢")):
                    em_prefix = {"גלות": "🔴 *1. ", "ימות המשיח": "🟡 *2. ", "גאולה": "🟢 *3. "}.get(tr_name, "")
                    first_ln_clean = first_ln.lstrip("* ").rstrip("*:")
                    new_hdr = f"{em_prefix}{first_ln_clean}:*"
                else:
                    new_hdr = first_ln
                rem_lines = lines[1:]
            else:
                new_hdr = existing_header
                rem_lines = lines

            formatted_bullets = []
            for r_ln in rem_lines:
                r_s = r_ln.strip()
                if not r_s:
                    continue
                if not r_s.startswith(("•", "-", "*")):
                    r_s = f"• {r_s}"
                elif r_s.startswith("- "):
                    r_s = "• " + r_s[2:]
                formatted_bullets.append(r_s)
            if formatted_bullets:
                return new_hdr + "\n" + "\n".join(formatted_bullets)
            return new_hdr

        # Single-line replacement (not append-only):
        was_paren = bool(re.match(r"^\(.+\)$", raw_clean))
        clean_single = short_desc_candidate or raw_clean.strip(" ()\t\n.,!\"'").strip()

        # If the user wrote a short parenthetical or header-style description for Galut, update header + bullet 1
        if tr_name == "גלות" and (was_paren or len(clean_single) <= 65):
            new_hdr = re.sub(
                rf"(מסלול\s+{re.escape(tr_name)}\s*)\([^\)\n]+\)",
                lambda m: f"{m.group(1)}({clean_single})",
                existing_header,
                count=1
            )
            b1 = f"• {clean_single}." if not clean_single.endswith((".", "!")) else f"• {clean_single}"
            if len(sec_lines) >= 2:
                sec_lines[0] = new_hdr
                sec_lines[1] = b1
                return "\n".join(sec_lines)
            return f"{new_hdr}\n{b1}"

        if was_paren:
            new_hdr = re.sub(
                rf"(מסלול\s+{re.escape(tr_name)}\s*)\([^\)\n]+\)",
                lambda m: f"{m.group(1)}({clean_single})",
                existing_header,
                count=1
            )
            sec_lines[0] = new_hdr
            return "\n".join(sec_lines)

        # User provided the exact text they want for this track on a single line (word-for-word replacement)
        sub_bullets = [p.strip() for p in re.split(r"(?:•|\n|;\s*)", clean_single) if p.strip()]
        if len(sub_bullets) >= 2:
            b_lines = [f"• {sb}" if not sb.startswith("•") else sb for sb in sub_bullets]
            return existing_header + "\n" + "\n".join(b_lines)
        else:
            b_line = f"• {clean_single}." if not clean_single.endswith((".", "!")) else f"• {clean_single}"
            return f"{existing_header}\n{b_line}"

    new_warranty = _edit_warranty_track_section(curr_warranty, tr_name, _replace_or_append_track_sec)
    set_dynamic_template("WARRANTY_FULL_EXPLANATION", new_warranty)
    save_permanent_style_rule("", short_desc_candidate or raw_clean, f"הנחיית קוד מאסטר ({used_code}) למסלול {tr_name}: {raw_clean}")
    return new_warranty, get_track_short_desc(tr_name)


def handle_master_override_code_command(message_text: str, sender_phone: str, raw_chat_id: str, quoted_text: str = "") -> dict:
    """
    Universal Master Override Handler triggered by `22015743: [הנחיה]` or `22015473: [הנחיה]` from ANY chat or phone number!
    """
    m_code = re.match(r"^\s*(22015743|22015473|2201\d{4})\s*(?:[:\-]\s*|\s+)(.+)$", (message_text or "").strip(), flags=re.DOTALL)
    used_code = m_code.group(1) if m_code else "22015743"
    raw_body = (m_code.group(2) if m_code else (message_text or "")).strip()
    body = auto_fix_common_hebrew_typos(raw_body)

    # Clean up any open customer/test session on sender_phone so sending a master override command never triggers a device order!
    try:
        _c_clean = sqlite3.connect(DB_PATH)
        _c_clean.execute(
            "UPDATE customer_requests SET status='handled' WHERE (phone = ? OR phone LIKE ?) AND status IN ('awaiting_customer_reply', 'pending', 'awaiting_customer_time')",
            (sender_phone, f"%{sender_phone[-9:]}%")
        )
        _c_clean.commit()
        _c_clean.close()
    except Exception:
        pass

    # Identify if a specific warranty track is targeted ('גאולה', 'ימות המשיח', 'גלות')
    target_track = ""
    if "גאולה" in body:
        target_track = "גאולה"
    elif "ימות המשיח" in body or "ימות משיח" in body:
        target_track = "ימות המשיח"
    elif "גלות" in body:
        target_track = "גלות"

    # Strip conversational rationale at the end of single-line commands (e.g. "כי זה לא נכון", "זה לא נכון", "מעכשיו ואילך")
    body_no_reason = re.sub(
        r"\s+(?:כי\s+זה\s+לא\s+נכון|כי\s+אין\s+דבר\s+כזה|כי\s+זה\s+טעות|כי\s+זה\s+שגוי|זה\s+לא\s+נכון|מעכשיו\s+ואילך|מהנוסח\s+הקבוע|מההודעה\s+הקבועה)[^\n]*$",
        "",
        body,
        flags=re.IGNORECASE
    ).strip(" .,!")

    # =========================================================================
    # CASE 0: FULL MULTI-TRACK WARRANTY TEMPLATE PASTED WORD-FOR-WORD
    # =========================================================================
    tracks_mentioned_count = sum(1 for tk in ("מסלול גלות", "מסלול ימות המשיח", "מסלול גאולה") if tk in body)
    if (tracks_mentioned_count >= 2 or "השוואת מסלולי האחריות" in body) and not re.search(r"המחיר\s+של|עולה\s+\d", body):
        cleaned_full_tpl = re.sub(
            r"^(?:תרשום|תכתוב|תעדכן|תשנה|זה\s+הנוסח|הנוסח\s+החדש)\s*[:\-]?\s*",
            "",
            body.strip(),
            flags=re.IGNORECASE
        ).strip()
        set_dynamic_template("WARRANTY_FULL_EXPLANATION", cleaned_full_tpl)
        for _tr_he, _tpl_k in [("גלות", "TRACK_SHORT_GALUT"), ("ימות המשיח", "TRACK_SHORT_YEMOT"), ("גאולה", "TRACK_SHORT_GEULA")]:
            m_p = re.search(rf"מסלול\s+{re.escape(_tr_he)}\s*\(([^)\n]+)\)", cleaned_full_tpl)
            if m_p:
                set_dynamic_template(_tpl_k, m_p.group(1).strip())
        confirm_msg = (
            f"✅ *פקודת מאסטר ({used_code}) בוצעה — נוסח השוואת מסלולי האחריות כולו הוחלף מילה במילה!* 🛠️📋\n\n"
            f"📋 *הנוסח הקבוע החדש מעכשיו ואילך:*\n{cleaned_full_tpl}"
        )
        send_whatsapp_message(sender_phone, confirm_msg, raw_chat_id)
        return {
            "ok": True,
            "master_code_action": "full_warranty_template_replaced_verbatim",
            "updated_preview": cleaned_full_tpl,
        }

    # =========================================================================
    # CASE 1: REMOVAL / DELETION ("תוריד...", "להסיר...", "תמחק...", "אל תכתוב...", "בלי...")
    # =========================================================================
    m_remove = (
        re.match(
            r"^(?:(?:במסלול|ממסלול|למסלול)\s+(?:גאולה|ימות\s+המשיח|ימות\s+משיח|גלות)\s+)?(?:תוריד|להוריד|תמחק|למחוק|תסיר|להסיר|תבטל|לבטל|אל\s+תכתוב|אל\s+תרשום|אל\s+תציין|בלי)\s+(.+)$",
            body_no_reason,
            flags=re.IGNORECASE | re.DOTALL
        )
        or re.search(
            r"^(?:במסלול|ממסלול|למסלול)\s+(?:גאולה|ימות\s+המשיח|ימות\s+משיח|גלות)\s+.*?\b(?:תוריד|להוריד|תמחק|למחוק|תסיר|להסיר|תבטל|לבטל|בלי)\s+(.+)$",
            body_no_reason,
            flags=re.IGNORECASE | re.DOTALL
        )
    )
    if m_remove and not re.search(r"\b(?:אלא|במקום\s+זה)\b", body_no_reason):
        phrase_raw = m_remove.group(1).strip()
        # 1. Strip track locator phrase ("במסלול גאולה" / "ממסלול גאולה") wherever it appears WITHOUT wiping out text after it!
        phrase_clean = re.sub(
            r"(?:^|\s+)(?:במסלול|ממסלול|למסלול|ב-?מסלול|מ-?מסלול)\s+(?:גאולה|ימות\s+המשיח|ימות\s+משיח|גלות)(?=\s|$|[.,!:])",
            " ",
            phrase_raw,
            flags=re.IGNORECASE
        ).strip()
        # 2. Strip location descriptors ("בהודעת האחריות", "במסלולי האחריות", etc.)
        phrase_clean = re.sub(
            r"(?:^|\s+)(?:בהודעת\s+האחריות|במסלולי\s+האחריות|בשעות\s+הפעילות|בהודעה)(?=\s|$)",
            " ",
            phrase_clean,
            flags=re.IGNORECASE
        ).strip()
        # 3. Strip meta-words ("את המילים", "המילים", "את המילה", "המילה", "את המשפט", "את") from the start
        phrase_clean = re.sub(
            r"^(?:את\s+)?(?:המילים|המילה|המשפט|הביטוי|הסעיף|הכיתוב|התוכן)\s*[:\"'\-–]?\s*",
            "",
            phrase_clean,
            flags=re.IGNORECASE
        ).strip()
        phrase_clean = re.sub(r"^את\s+", "", phrase_clean, flags=re.IGNORECASE).strip(" .,!\"'")

        candidates = []
        def _add_cand(c_str: str):
            c_s = (c_str or "").strip(" .,!\"'")
            if c_s and c_s not in candidates:
                candidates.append(c_s)

        if phrase_clean:
            _add_cand(phrase_clean)
            if phrase_clean.startswith("ו") and len(phrase_clean) >= 3:
                _add_cand(re.sub(r"^ו-?", "", phrase_clean).strip())
            _add_cand(re.sub(r"^ה", "", phrase_clean).strip())
            core_noun = re.sub(
                r"^(?:ה?תיקון\s+(?:של\s+)?|ה?אחריות\s+(?:על\s+)?|ה?כיסוי\s+(?:של\s+|על\s+)?|ה?סעיף\s+(?:של\s+)?|ה?מילים\s+|ה?מילה\s+)",
                "",
                phrase_clean
            ).strip()
            if core_noun:
                _add_cand(core_noun)
                if core_noun.startswith("ו") and len(core_noun) >= 3:
                    _add_cand(re.sub(r"^ו-?", "", core_noun).strip())
                _add_cand(re.sub(r"^ה", "", core_noun).strip())

        def _remove_candidates_from_sec(sec_txt: str) -> str:
            res_txt = sec_txt
            for cand in candidates:
                if cand:
                    res_txt = _remove_phrase_cleanly(res_txt, cand)
            return res_txt

        # 1. Update WARRANTY_FULL_EXPLANATION dynamic template
        curr_warranty = get_dynamic_template("WARRANTY_FULL_EXPLANATION", WARRANTY_FULL_EXPLANATION)
        new_warranty = _edit_warranty_track_section(curr_warranty, target_track, _remove_candidates_from_sec)
        set_dynamic_template("WARRANTY_FULL_EXPLANATION", new_warranty)

        # 2. Also remove from TRACK_SHORT_GALUT / TRACK_SHORT_YEMOT / TRACK_SHORT_GEULA (used in device quotes!)
        track_keys_to_clean = (
            [{"גלות": "TRACK_SHORT_GALUT", "ימות המשיח": "TRACK_SHORT_YEMOT", "גאולה": "TRACK_SHORT_GEULA"}[target_track]]
            if target_track in ("גלות", "ימות המשיח", "גאולה")
            else ["TRACK_SHORT_GALUT", "TRACK_SHORT_YEMOT", "TRACK_SHORT_GEULA"]
        )
        for tk_clean in track_keys_to_clean:
            curr_short = get_dynamic_template(tk_clean, "")
            if curr_short:
                new_short = _remove_candidates_from_sec(curr_short)
                if new_short != curr_short:
                    set_dynamic_template(tk_clean, new_short)

        # 3. Also update STORE_HOURS_DETAILS if relevant
        curr_hours = get_dynamic_template("STORE_HOURS_DETAILS", STORE_HOURS_DETAILS)
        new_hours = _remove_candidates_from_sec(curr_hours)
        if new_hours != curr_hours:
            set_dynamic_template("STORE_HOURS_DETAILS", new_hours)

        # 4. Save permanent deletion rule in learned_style_rules so it is stripped everywhere!
        primary_removed = candidates[0] if candidates else phrase_clean
        rule_inst = f"הנחיית קוד מאסטר ({used_code}): {raw_body} (אין לכלול את '{primary_removed}')"
        for cand in candidates:
            if len(cand) >= 2:
                save_permanent_style_rule(cand, "[DELETE]", rule_inst)

        preview_block = _extract_track_section_preview(new_warranty, target_track) if target_track else new_warranty
        track_label = f" (במסלול {target_track})" if target_track else ""
        short_line_info = f"\n✨ *נוסח קצר בהצעות מחיר למכשירים:* • מסלול {target_track} ({get_track_short_desc(target_track)})" if target_track else ""
        confirm_msg = (
            f"✅ *פקודת מאסטר ({used_code}) בוצעה — הנוסח הקבוע עודכן לתמיד{track_label}!* 🛠️\n"
            f"🗑️ *הוסר מהנוסח הקבוע:* \"{phrase_clean}\"{short_line_info}\n\n"
            f"📋 *הנוסח המעודכן מעכשיו ואילך:*\n{preview_block}"
        )
        send_whatsapp_message(sender_phone, confirm_msg, raw_chat_id)
        return {
            "ok": True,
            "master_code_action": "phrase_removed_permanently",
            "removed_candidates": candidates,
            "target_track": target_track,
            "updated_preview": preview_block,
        }

    # =========================================================================
    # CASE 2: REPLACEMENT ("במקום X תכתוב Y", "תשנה את X ל-Y", "תחליף את X ב-Y", "אל תכתוב X אלא Y")
    # =========================================================================
    m_replace = (
        re.search(
            r"במקום\s+(?:לכתוב\s+|לרשום\s+|להגיד\s+|לשאול\s+)?[:\"']?(.+?)[\"']?\s+(?:תכתוב|תרשום|תגיד|תשאל|תשים|צריך\s+להיות)\s*[:\"']?(.+?)[\"']?$",
            body_no_reason,
            flags=re.IGNORECASE | re.DOTALL
        )
        or re.search(
            r"(?:תשנה|לשנות|תחליף|להחליף)\s+(?:את\s+)?[:\"']?(.+?)[\"']?\s+(?:ל-|ל|ב-|ב)\s*[:\"']?(.+?)[\"']?$",
            body_no_reason,
            flags=re.IGNORECASE | re.DOTALL
        )
        or re.search(
            r"(?:אל|לא)\s+(?:תשאל|תכתוב|תרשום|תגיד)\s+[:\"']?(.+?)[\"']?\s+(?:אלא|אלה)\s+(?:תכתוב|תרשום|תשאל|תגיד)?\s*[:\"']?(.+?)[\"']?$",
            body_no_reason,
            flags=re.IGNORECASE | re.DOTALL
        )
    )
    if m_replace and not re.search(r"המחיר\s+של", body_no_reason):
        old_val = m_replace.group(1).strip(" .,!\"'")
        new_val = m_replace.group(2).strip(" .,!\"'")
        old_val = re.sub(r"^(?:במסלול|ממסלול)\s+(?:גאולה|ימות\s+המשיח|גלות)\s+", "", old_val).strip()
        old_val = re.sub(r"\s+(?:במסלול|ממסלול)\s+(?:גאולה|ימות\s+המשיח|גלות)$", "", old_val).strip()

        curr_warranty = get_dynamic_template("WARRANTY_FULL_EXPLANATION", WARRANTY_FULL_EXPLANATION)
        new_warranty = _edit_warranty_track_section(
            curr_warranty,
            target_track,
            lambda sec: sec.replace(old_val, new_val)
        )
        if new_warranty != curr_warranty:
            set_dynamic_template("WARRANTY_FULL_EXPLANATION", new_warranty)

        for _tk in ("TRACK_SHORT_GALUT", "TRACK_SHORT_YEMOT", "TRACK_SHORT_GEULA"):
            _c_sh = get_dynamic_template(_tk, "")
            if old_val and old_val in _c_sh:
                set_dynamic_template(_tk, _c_sh.replace(old_val, new_val))

        curr_hours = get_dynamic_template("STORE_HOURS_DETAILS", STORE_HOURS_DETAILS)
        if old_val in curr_hours:
            set_dynamic_template("STORE_HOURS_DETAILS", curr_hours.replace(old_val, new_val))

        rule_inst = f"הנחיית קוד מאסטר ({used_code}): במקום '{old_val}' חובה לכתוב תמיד '{new_val}'"
        save_permanent_style_rule(old_val, new_val, rule_inst)

        confirm_msg = (
            f"✅ *פקודת מאסטר ({used_code}) בוצעה — הנוסח הוחלף באופן קבוע!* 🛠️\n"
            f"🔄 *נוסח קודם:* \"{old_val}\"\n"
            f"✨ *נוסח קבוע חדש:* \"{new_val}\""
        )
        send_whatsapp_message(sender_phone, confirm_msg, raw_chat_id)
        return {
            "ok": True,
            "master_code_action": "phrase_replaced_permanently",
            "from": old_val,
            "to": new_val,
        }

    # =========================================================================
    # CASE 3: UPDATING, REWRITING (WORD-FOR-WORD), OR ADDING A WARRANTY TRACK DESCRIPTION
    # =========================================================================
    m_track_add = (
        re.match(
            r"^(?:במסלול|למסלול)\s+(גאולה|ימות\s+המשיח|ימות\s+משיח|גלות)\s+(תוסיף|להוסיף|תכתוב|לכתוב|תרשום|לרשום|עדכן|תעדכן|תשנה|לשנות|יהיה|צריך\s+להיות)\s*(?:ש-|ש|:)?\s*(.+)$",
            body_no_reason,
            flags=re.IGNORECASE | re.DOTALL
        )
        or re.match(
            r"^(תוסיף|להוסיף|תכתוב|לכתוב|תרשום|לרשום|עדכן|תעדכן|תשנה|לשנות)?\s*(?:במסלול|למסלול)\s+(גאולה|ימות\s+המשיח|ימות\s+משיח|גלות)\s*(?:ש-|ש|:|את\s+הנוסח\s+הבא|את\s+הנוסח|את)?\s*(.+)$",
            body_no_reason,
            flags=re.IGNORECASE | re.DOTALL
        )
        or re.match(
            r"^()\s*(?:🔴|🟡|🟢)?\s*\*?(?:[123]\.\s*)?מסלול\s+(גאולה|ימות\s+המשיח|ימות\s+משיח|גלות)\*?\s*(?:[:\-–—]|\n)\s*(.+)$",
            body.strip(),
            flags=re.IGNORECASE | re.DOTALL
        )
    )
    if m_track_add and not re.search(r"^(?:המחיר\s+של|כמה\s+עולה)", body_no_reason):
        g1 = (m_track_add.group(1) or "").strip()
        g2 = (m_track_add.group(2) or "").strip()
        if g1 in ("גאולה", "גלות") or "ימות" in g1:
            tr_name = g1
            verb_used = g2
        else:
            verb_used = g1
            tr_name = g2
        if "ימות" in tr_name:
            tr_name = "ימות המשיח"

        raw_addition = m_track_add.group(3).strip()
        raw_addition = re.sub(
            r"^(?:את\s+הנוסח\s+הבא|את\s+הנוסח|הנוסח\s+הבא|ככה|כך|מילה\s+במילה)\s*[:\-]?\s*",
            "",
            raw_addition,
            flags=re.IGNORECASE
        ).strip()
        was_parenthesized = bool(re.match(r"^\(.+\)$", raw_addition))
        is_pure_add_bullet = verb_used in ("תוסיף", "להוסיף") and not was_parenthesized and "\n" not in raw_addition

        verbatim_payload = body.strip() if re.match(r"^(?:🔴|🟡|🟢)\s*\*?[123]\.\s*מסלול", body.strip()) else raw_addition
        new_warranty, updated_short = _apply_verbatim_track_replacement(
            tr_name=tr_name,
            verbatim_text=verbatim_payload,
            used_code=used_code,
            is_append_only=is_pure_add_bullet,
        )

        preview_block = _extract_track_section_preview(new_warranty, tr_name)
        quote_line_preview = f"• מסלול {tr_name} ({updated_short})"
        confirm_msg = (
            f"✅ *פקודת מאסטר ({used_code}) בוצעה — מסלול {tr_name} עודכן לתמיד בכל המערכת!* 🛠️\n"
            f"✨ *נוסח מסלול {tr_name} בהצעות מחיר למכשירים מעכשיו:*\n{quote_line_preview}\n\n"
            f"📋 *הנוסח המעודכן בהסבר מסלולי האחריות:*\n{preview_block}"
        )
        send_whatsapp_message(sender_phone, confirm_msg, raw_chat_id)
        return {
            "ok": True,
            "master_code_action": "warranty_track_updated",
            "track": tr_name,
            "added": raw_addition,
            "quote_line_preview": quote_line_preview,
            "updated_preview": preview_block,
        }

    # =========================================================================
    # CASE 4: PRODUCT / DEVICE PRICE UPDATE ("המחיר של X הוא ...", "תשנה את המחיר של X ל-...")
    # =========================================================================
    tracks_in_cmd = extract_multi_track_prices_from_text(body)
    has_tracks_in_cmd = sum(1 for v in (tracks_in_cmd.get("galut"), tracks_in_cmd.get("yemot"), tracks_in_cmd.get("geula")) if v and int(v) > 0) >= 1
    m_price_cmd = re.search(
        r"(?:תשנה\s+את\s+המחיר\s+של|המחיר\s+של|תעדכן\s+מחיר\s+ל-?|מחיר)\s+(.+?)\s+(?:הוא|ל-|ל|עולה|במחיר)\s*(.+)$",
        body_no_reason,
        flags=re.IGNORECASE
    )
    if m_price_cmd or (has_tracks_in_cmd and any(ch.isdigit() for ch in body_no_reason) and not target_track):
        if m_price_cmd:
            prod_raw = m_price_cmd.group(1).strip(" .,!:-")
            price_part = m_price_cmd.group(2).strip()
        else:
            prod_raw = re.split(r"\b(?:ב?מסלול|ב?גלות|ב?ימות\s+המשיח|ב?גאולה)\b", body_no_reason)[0].strip(" .,!:-")
            price_part = body_no_reason

        clean_prod = clean_pos_product_display_name(prod_raw) or prod_raw
        single_p = extract_price_nis(price_part)
        if clean_prod and (has_tracks_in_cmd or single_p):
            save_learned_pos_product_prices(
                product_name=clean_prod,
                single_price=int(single_p) if single_p else None,
                galut_price=tracks_in_cmd.get("galut"),
                yemot_price=tracks_in_cmd.get("yemot"),
                geula_price=tracks_in_cmd.get("geula"),
            )
            p_summary = []
            if tracks_in_cmd.get("galut"):
                p_summary.append(f"גלות: {tracks_in_cmd['galut']} ₪")
            if tracks_in_cmd.get("yemot"):
                p_summary.append(f"ימות המשיח: {tracks_in_cmd['yemot']} ₪")
            if tracks_in_cmd.get("geula"):
                p_summary.append(f"גאולה: {tracks_in_cmd['geula']} ₪")
            if not p_summary and single_p:
                p_summary.append(f"{single_p} ₪")
            p_str = " | ".join(p_summary)
            confirm_msg = (
                f"✅ *פקודת מאסטר ({used_code}) בוצעה — המחיר של '{clean_prod}' עודכן לתמיד במלאי ובזיכרון הסוכן!* 💰📦\n"
                f"• *מוצר:* {clean_prod}\n"
                f"• *מחיר קבוע מעודכן:* {p_str}"
            )
            send_whatsapp_message(sender_phone, confirm_msg, raw_chat_id)
            return {
                "ok": True,
                "master_code_action": "product_price_updated",
                "product": clean_prod,
                "prices": p_str,
            }

    # =========================================================================
    # CASE 5: GENERAL PERMANENT RULE / Q&A OVERRIDE ("כששואלים על X תענה Y")
    # =========================================================================
    m_qa = re.search(
        r"(?:כששואלים\s+על|כאשר\s+שואלים\s+על|לגבי|בנושא)\s+(.+?)\s+(?:תענה|תכתוב|תרשום|תגיד)\s*[:\"']?(.+?)[\"']?$",
        body_no_reason,
        flags=re.IGNORECASE | re.DOTALL
    )
    if m_qa:
        kw_topic = m_qa.group(1).strip(" .,!\"'")
        ans_topic = m_qa.group(2).strip(" .,!\"'")
        try:
            conn = sqlite3.connect(DB_PATH)
            conn.execute(
                "INSERT OR REPLACE INTO learned_kb (keywords, answer, created_at) VALUES (?, ?, ?)",
                (kw_topic, ans_topic, datetime.now().isoformat())
            )
            conn.commit()
            conn.close()
            sync_learned_kb_to_json()
        except Exception:
            pass
        save_permanent_style_rule("", ans_topic, f"הנחיית קוד מאסטר ({used_code}) בנושא '{kw_topic}': {ans_topic}")
        confirm_msg = (
            f"✅ *פקודת מאסטר ({used_code}) בוצעה — הכלל נשמר לתמיד!* 🧠\n"
            f"🔑 *נושא / מילות מפתח:* {kw_topic}\n"
            f"💬 *תשובה קבועה מעכשיו:* \"{ans_topic}\""
        )
        send_whatsapp_message(sender_phone, confirm_msg, raw_chat_id)
        return {
            "ok": True,
            "master_code_action": "qa_rule_saved",
            "keywords": kw_topic,
            "answer": ans_topic,
        }

    # =========================================================================
    # CASE 6: VERBATIM FALLBACK WHEN A TRACK IS MENTIONED
    # =========================================================================
    if target_track:
        cleaned_verbatim = re.sub(
            rf"^(?:במסלול|למסלול|עבור\s+מסלול)?\s*{re.escape(target_track)}\s*[:\-–—]?\s*",
            "",
            body.strip(),
            flags=re.IGNORECASE
        ).strip()
        if cleaned_verbatim:
            new_warranty, updated_short = _apply_verbatim_track_replacement(
                tr_name=target_track,
                verbatim_text=cleaned_verbatim,
                used_code=used_code,
                is_append_only=False,
            )
            preview_block = _extract_track_section_preview(new_warranty, target_track)
            quote_line_preview = f"• מסלול {target_track} ({updated_short})"
            confirm_msg = (
                f"✅ *פקודת מאסטר ({used_code}) בוצעה — מסלול {target_track} הוחלף מילה במילה בכל המערכת!* 🛠️\n"
                f"✨ *נוסח מסלול {target_track} בהצעות מחיר למכשירים מעכשיו:*\n{quote_line_preview}\n\n"
                f"📋 *הנוסח המעודכן בהסבר מסלולי האחריות:*\n{preview_block}"
            )
            send_whatsapp_message(sender_phone, confirm_msg, raw_chat_id)
            return {
                "ok": True,
                "master_code_action": "warranty_track_replaced_verbatim",
                "track": target_track,
                "quote_line_preview": quote_line_preview,
                "updated_preview": preview_block,
            }

    # General fallback
    save_permanent_style_rule("", body_no_reason, f"הנחיית קוד מאסטר קבועה ({used_code}): {raw_body}")
    if quoted_text and len(quoted_text.strip()) >= 4:
        save_permanent_style_rule(quoted_text.strip(), body_no_reason, f"החלפת הודעה מצוטטת ({used_code}): {body_no_reason}")

    confirm_msg = (
        f"✅ *פקודת מאסטר ({used_code}) נקלטה ונשמרה ככלל ברזל קבוע במערכת!* 🛡️\n"
        f"📌 *הנחיה קבועה שנשמרה:* \"{raw_body}\""
    )
    send_whatsapp_message(sender_phone, confirm_msg, raw_chat_id)
    return {
        "ok": True,
        "master_code_action": "general_permanent_rule_saved",
        "rule": raw_body,
    }


def handle_admin_tikun_or_style_command(message_text: str, sender_phone: str, raw_chat_id: str) -> dict:
    """
    Permanently learns a phrasing or style correction when Admin writes 'תיקון: ...'
    or instructs 'מעכשיו אל תשאל X אלא תכתוב Y' / 'במקום X תכתוב Y' / 'במסלול גלות תרשום ...'.
    Updates learned_style_rules + rewrites learned_kb + updates active customer request if applicable.
    """
    clean_msg = auto_fix_common_hebrew_typos((message_text or "").strip())
    if re.match(
        r"^(?:(?:במסלול|למסלול)\s+(?:גלות|ימות\s+המשיח|גאולה)\s+(?:תרשום|תכתוב|תעדכן|תוסיף|תוריד|תמחק|תשנה)|(?:תרשום|תכתוב|תעדכן|תוסיף|תוריד|תמחק|תשנה)\s+(?:במסלול|למסלול|ממסלול)\s+(?:גלות|ימות\s+המשיח|גאולה))",
        clean_msg,
        flags=re.IGNORECASE
    ):
        return handle_master_override_code_command(f"22015473: {clean_msg}", sender_phone, raw_chat_id)
    body = re.sub(r"^(?:תיקון|כלל\s+חדש|כלל\s+קבוע|שינוי\s+נוסח|נוסח\s+קבוע)\s*[:\-]\s*", "", clean_msg, flags=re.IGNORECASE).strip()

    # Check if Admin is specifying a "Instead of X write Y" / "From now on don't ask X rather write Y" rule
    m_instead = (
        re.search(
            r"(?:מעכשיו\s+)?(?:אל|לא)\s+(?:תשאל|ישאל|תכתוב|יכתוב|תרשום|ירשום|תגיד|יגיד)(?:\s+את\s+הלקוח|\s+לו)?\s+(.+?)\s+(?:אלא|אלה)\s+(?:תכתוב|יכתוב|תרשום|ירשום|תשאל|ישאל|תגיד|יגיד)?(?:\s+לו|\s+ללקוח)?\s*[:\x22\x27]?(.+?)[\x22\x27]?$",
            body,
            flags=re.IGNORECASE
        )
        or re.search(
            r"במקום\s+(?:לשאול|לכתוב|לרשום|להגיד)(?:\s+ללקוח|\s+לו)?\s+(.+?)\s+(?:תכתוב|יכתוב|תרשום|ירשום|תשאל|ישאל|תגיד|יגיד)(?:\s+לו|\s+ללקוח)?\s*[:\x22\x27]?(.+?)[\x22\x27]?$",
            body,
            flags=re.IGNORECASE
        )
    )

    if m_instead:
        raw_from = m_instead.group(1).strip(" .,!\x22'")
        raw_to = m_instead.group(2).strip(" .,!\x22'")
        if not raw_to.endswith("?") and any(q in raw_to for q in ["מה ", "איזה ", "איזו ", "האם ", "מתי ", "איך "]):
            raw_to += "?"

        # Map 3rd-person description of old phrase (e.g. "אם הוא רוצה להזמין את החלק") to actual 2nd-person bot phrases
        patterns_to_replace = [raw_from]
        if "להזמין את החלק" in raw_from or "להזמין עבורך את החלק" in raw_from:
            patterns_to_replace.extend([
                "האם תרצה שנזמין עבורך את החלק?",
                "האם תרצה שאזמין עבורך את החלק?",
                "האם תרצה שאזמין את החלק?",
                "האם תרצה להזמין את החלק?",
                "האם תרצה שנזמין את החלק?",
            ])
        else:
            adapted_from, _ = adapt_admin_answer(raw_from)
            if adapted_from and adapted_from not in patterns_to_replace:
                patterns_to_replace.append(adapted_from.rstrip(" 😃").strip())

        instruction_summary = f"במקום '{raw_from}' חובה לכתוב תמיד: '{raw_to}'"
        for pf in patterns_to_replace:
            save_permanent_style_rule(pf, raw_to, instruction_summary)

        confirm_reply = (
            f"✅ *הכלל והנוסח עודכנו באופן קבוע במערכת ובמאגר הזיכרון!*\n"
            f"🔄 *נוסח שהוחלף:* \x22{patterns_to_replace[-1]}\x22\n"
            f"✨ *הנוסח הקבוע החדש:* \x22{raw_to}\x22\n"
            f"(כל התשובות השמורות במאגר הידע עודכנו אוטומטית לנוסח החדש)."
        )
        send_whatsapp_message(sender_phone, confirm_reply, raw_chat_id)
        return {"ok": True, "admin_action": "permanent_style_rule_saved", "from": patterns_to_replace, "to": raw_to}

    # Otherwise, Admin wrote "תיקון: [הנוסח החדש]" directly
    adapted_new, is_in_prog = adapt_admin_answer(body)
    # Preserve Admin's exact wording if Admin wrote a direct 2nd-person sentence
    final_new_phrasing = adapted_new if adapted_new else body
    save_permanent_style_rule("", final_new_phrasing, f"הנחיית ניסוח קבועה מערן: {body}")

    # Also update the most recent learned_kb entry (and active customer request if one is pending)
    updated_kb_kw = ""
    try:
        conn = sqlite3.connect(DB_PATH)
        last_kb = conn.execute("SELECT id, keywords FROM learned_kb ORDER BY id DESC LIMIT 1").fetchone()
        if last_kb:
            conn.execute("UPDATE learned_kb SET answer = ? WHERE id = ?", (final_new_phrasing, last_kb[0]))
            updated_kb_kw = last_kb[1]
        # Check if there is a pending customer request waiting for an answer right now
        pend_req = conn.execute(
            "SELECT id, phone, request_text FROM customer_requests WHERE status = 'pending' AND phone != ? ORDER BY id DESC LIMIT 1",
            (sender_phone,)
        ).fetchone()
        if pend_req:
            target_cust = pend_req[1]
            send_whatsapp_message(target_cust, final_new_phrasing)
            save_chat_message(target_cust, "agent", final_new_phrasing)
            opts = extract_options_and_prices_from_text(final_new_phrasing)
            act_str = final_new_phrasing
            if opts:
                act_str += f" [OPTIONS_JSON:{json.dumps(opts, ensure_ascii=False)}]"
            conn.execute("UPDATE customer_requests SET status='awaiting_customer_reply', action_taken=? WHERE id=?", (act_str, pend_req[0]))
        conn.commit()
        conn.close()
        sync_learned_kb_to_json()
    except Exception as e:
        print(f"[Tikun Update Notice]: {e}")

    kb_note = f" (כולל עדכון התשובה הקבועה עבור '{updated_kb_kw}')" if updated_kb_kw else ""
    confirm_reply = (
        f"✅ *התיקון נשמר באופן קבוע במערכת{kb_note}!*\n"
        f"✨ *הנוסח המעודכן:* \x22{final_new_phrasing}\x22"
    )
    send_whatsapp_message(sender_phone, confirm_reply, raw_chat_id)
    return {"ok": True, "admin_action": "permanent_tikun_applied", "new_phrasing": final_new_phrasing}


def handle_admin_bit_payment_directive(admin_answer: str, target_pending, sender_phone: str, raw_chat_id: str) -> dict:
    """
    Handles when Admin hints or instructs the bot to send a Bit payment request to the customer
    (e.g. 'אתה צריך לשלוח ללקוח בקשה לשלוח ביט', 'תשלח לו בקשה להעביר ביט').
    Extracts the item name (e.g. 'מגן סיליקון') and price X from the conversation history (or Admin's message)
    and sends a formal Bit payment request to the customer without parroting Admin's words!
    """
    conn = sqlite3.connect(DB_PATH)
    if not target_pending:
        target_pending = conn.execute(
            "SELECT id, phone, request_text FROM customer_requests WHERE phone != ? ORDER BY id DESC LIMIT 1",
            (sender_phone,)
        ).fetchone()

    if not target_pending:
        conn.close()
        send_whatsapp_message(sender_phone, "⚠️ לא נמצאה פניית לקוח פתוחה לשליחת בקשת תשלום בביט.", raw_chat_id)
        return {"ok": False, "error": "no_active_customer_for_bit"}

    req_id, target_cust_phone, req_text = target_pending[0], target_pending[1], target_pending[2] or ""
    prev_act_row = conn.execute("SELECT action_taken FROM customer_requests WHERE id=?", (req_id,)).fetchone()
    prev_act_str = (prev_act_row[0] if prev_act_row else "") or ""
    full_hist = get_recent_chat_history(target_cust_phone, limit=16)

    # 1. Check if Admin explicitly mentioned a price in this directive (excluding the Bit phone number)
    admin_clean_no_phone = admin_answer.replace("052-4043644", "").replace("0524043644", "")
    explicit_adm_price = extract_price_nis(admin_clean_no_phone)

    # 2. Look up the selected option & its price from the customer's request and conversation history
    latest_cust_q = extract_latest_customer_question(req_text)
    sel_info = find_selected_option_and_price(latest_cust_q or req_text, prev_act_str, full_hist, req_text)
    if not sel_info.get("matched"):
        # Also scan customer lines in full_hist from newest to oldest
        cust_lines = [l.replace("[לקוח]:", "").strip() for l in full_hist.split("\n") if l.strip().startswith("[לקוח]:")]
        for cl in reversed(cust_lines):
            cand = find_selected_option_and_price(cl, prev_act_str, full_hist, req_text)
            if cand.get("matched"):
                sel_info = cand
                break

    item_name = sel_info.get("name") if sel_info.get("matched") else ""
    item_price = explicit_adm_price or (sel_info.get("price") if sel_info.get("matched") else "")

    if not item_price:
        m_saved_p = re.search(r"\[PRICE:(\d{2,4})\]", prev_act_str + " " + req_text)
        item_price = m_saved_p.group(1) if m_saved_p else (extract_price_nis(prev_act_str) or extract_price_nis(full_hist))

    if not item_name:
        if "סיליקון" in auto_fix_common_hebrew_typos(req_text + " " + full_hist):
            item_name = "מגן סיליקון"
        elif "זכוכית" in (req_text + " " + full_hist):
            item_name = "מגן זכוכית"
        else:
            item_name = "הפריט המבוקש"

    if item_price:
        cust_bit_msg = (
            f"לצורך הזמנת *{item_name}* שמחירו *{item_price} ₪*, אנא העבר כעת *{item_price} ₪* בביט (Bit) למספר:\n"
            f"📱 *{BIT_PAYMENT_PHONE}* (ערן נקר - נעם שיח)\n\n"
            f"לאחר ההעברה, שלח לנו כאן עדכון או צילום מסך ונדאג להזמין ולשמור עבורך מיד! 😃"
        )
        act_update = f"נשלחו פרטי תשלום בביט עבור {item_name} ({item_price} ₪ ל-{BIT_PAYMENT_PHONE}) [PRICE:{item_price}]"
    else:
        cust_bit_msg = (
            f"לצורך הזמנת *{item_name}*, ניתן להעביר תשלום בביט (Bit) למספר:\n"
            f"📱 *{BIT_PAYMENT_PHONE}* (ערן נקר - נעם שיח)\n\n"
            f"לאחר ההעברה, שלח לנו כאן עדכון או צילום מסך ונדאג להזמין עבורך מיד! 😃"
        )
        act_update = f"נשלחו פרטי תשלום בביט עבור {item_name} (ל-{BIT_PAYMENT_PHONE})"

    conn.execute("UPDATE customer_requests SET status='awaiting_bit_payment', action_taken=? WHERE id=?", (act_update, req_id))
    conn.commit()
    conn.close()

    send_whatsapp_message(target_cust_phone, cust_bit_msg)
    save_chat_message(target_cust_phone, "agent", cust_bit_msg)

    price_str_adm = f" על סך *{item_price} ₪*" if item_price else ""
    confirm_adm = (
        f"✅ נשלחה ללקוח ({target_cust_phone}) בקשת תשלום מסודרת בביט{price_str_adm} עבור *{item_name}* למספר {BIT_PAYMENT_PHONE}!"
    )
    send_whatsapp_message(sender_phone, confirm_adm, raw_chat_id)
    return {
        "ok": True,
        "admin_action": "bit_payment_request_sent_from_directive",
        "customer": target_cust_phone,
        "item": item_name,
        "price": item_price,
    }






# ============================================================================
# KOSHERPLAY & NETSPARK FILTERING MANAGEMENT, SECURITY & RENEWAL ENGINE (v1)
# ============================================================================
# Principles implemented per Eran's architecture:
# 0. Protection System Lookup Order:
#    - Search KosherPlay CRM first (https://crm.kosherplay.com/modules/1?filter=...&pageIndex=0&archive=false&sortBy=&direction=asc&pageSize=12)
#    - If not found in KosherPlay -> Search NetSpark CRM
#    - If not found in either -> Ask customer which protection they have and under what name/phone.
# A. Strict Own-Subscription & Phone Ownership OTP Verification:
#    - Customer may ONLY modify their own subscription.
#    - Sends a 6-digit verification code (WhatsApp / SMS) to the subscription phone number
#      and requires entering the code before any service action.
# B. One-Time Adult & Authorization Verification with Admin (Eran):
#    - After OTP verification, asks Eran ONCE if the customer is an authorized adult.
#    - Saved permanently in SQLite (`filtering_subscribers`) + JSON backup + WhatsApp cloud snapshot.
# C. One-Time Free-Service Expiry Date Check + Annual Renewal via POS Price Table:
#    - Together with the one-time adult check, asks Eran until what date the customer has free service
#      (end of their paid year) and saves `service_expiry_date` permanently.
#    - Once `service_expiry_date` passes, notifies customer to renew with Eran at the price loaded
#      in `pos_inventory` (the store price table). Once Eran confirms payment, extends by +1 year.
#    - Modular `FilteringBillingAdapter` ready to switch from `admin_approval` to an external payment website.
# ============================================================================

