# MODULAR BILLING & ANNUAL RENEWAL ADAPTER (POS Price Table + Future Web Hook)
# ----------------------------------------------------------------------------
class FilteringBillingAdapter:
    """
    Modular billing & subscription renewal manager:
    - Looks up the annual renewal price dynamically from `pos_inventory` (the Excel/POS price table
      loaded into the agent alongside all products).
    - Supports `FILTERING_PAYMENT_MODE == "admin_approval"` (current workflow with Eran)
      and `FILTERING_PAYMENT_MODE == "payment_site"` (future self-service payment website).
    """

    @staticmethod
    def get_annual_renewal_price_from_pos(system_name: str = "כשר פליי") -> dict:
        sys_clean = (system_name or "כשר פליי").strip()
        search_candidates = (
            ["חידוש כשר פליי", "כשר פליי לשנה", "מנוי כשר פליי", "רישיון כשר פליי", "כשר פליי"]
            if "כשר" in sys_clean
            else ["חידוש נטספרק", "נטספרק לשנה", "מנוי נטספרק", "רישיון נטספרק", "נטספרק"]
        )
        try:
            conn = sqlite3.connect(DB_PATH)
            for kw in search_candidates:
                row = conn.execute(
                    "SELECT product_name, single_price FROM pos_inventory WHERE product_name LIKE ? AND single_price > 0 ORDER BY id DESC LIMIT 1",
                    (f"%{kw}%",),
                ).fetchone()
                if row and row[1]:
                    conn.close()
                    return {
                        "price_nis": int(row[1]),
                        "product_name": str(row[0]),
                        "source": "pos_inventory",
                    }
            conn.close()
        except Exception as e:
            print(f"[FilteringBillingAdapter POS Lookup Error]: {e}")

        # Fallback to live POS lookup helper if available
        for kw in search_candidates[:2]:
            try:
                pos_hit = lookup_live_pos_inventory(kw)
                if pos_hit.get("matched") and pos_hit.get("item", {}).get("single_price"):
                    return {
                        "price_nis": int(pos_hit["item"]["single_price"]),
                        "product_name": str(pos_hit["item"].get("product_name") or kw),
                        "source": "pos_inventory_fuzzy",
                    }
            except Exception:
                pass

        # Default fallback if POS table has no filtering row loaded yet (180 NIS for KosherPlay / NetSpark annual renewal)
        default_price = 180 if "כשר" in sys_clean else 180
        return {
            "price_nis": default_price,
            "product_name": f"חידוש מנוי שנתי {sys_clean}",
            "source": "default_store_tariff",
        }

    @staticmethod
    def is_subscription_expired(service_expiry_date: str) -> bool:
        """Checks if YYYY-MM-DD is strictly before today's date in Israel."""
        if not service_expiry_date or not str(service_expiry_date).strip():
            return False
        try:
            exp_dt = datetime.strptime(str(service_expiry_date).strip()[:10], "%Y-%m-%d").date()
            today_il = datetime.now(ZoneInfo("Asia/Jerusalem")).date()
            return today_il > exp_dt
        except Exception:
            return False

    @staticmethod
    def format_date_il(date_str: str) -> str:
        """Converts YYYY-MM-DD to DD/MM/YYYY for user-facing Hebrew messages."""
        try:
            dt = datetime.strptime(str(date_str).strip()[:10], "%Y-%m-%d")
            return dt.strftime("%d/%m/%Y")
        except Exception:
            return str(date_str)

    @staticmethod
    def build_renewal_message_for_customer(system_name: str, service_expiry_date: str, customer_phone: str) -> dict:
        pricing = FilteringBillingAdapter.get_annual_renewal_price_from_pos(system_name)
        price_nis = pricing["price_nis"]
        exp_fmt = FilteringBillingAdapter.format_date_il(service_expiry_date)

        if FILTERING_PAYMENT_MODE == "payment_site" and FILTERING_PAYMENT_SITE_URL:
            pay_url = f"{FILTERING_PAYMENT_SITE_URL.rstrip('/')}?phone={urllib.parse.quote(customer_phone)}&system={urllib.parse.quote(system_name)}&amount={price_nis}"
            msg = (
                f"תקופת השירות השנתית ללא עלות במנוי ה*{system_name}* שלך הסתיימה בתאריך *{exp_fmt}*. 📅\n"
                f"כדי להמשיך לקבל שירותי פתיחה, סגירה ועדכונים למהלך השנה הקרובה, ניתן לחדש כעת את המנוי השנתי בעלות של *{price_nis} ₪* (לפי מחירון החנות) בקישור המאובטח:\n"
                f"🔗 {pay_url}\n\n"
                f"מיד עם השלמת התשלום המנוי יתעדכן אוטומטית לשנה נוספת ונבצע עבורך את הבקשה! 😃"
            )
        else:
            msg = (
                f"תקופת השירות השנתית ללא עלות במנוי ה*{system_name}* שלך הסתיימה בתאריך *{exp_fmt}*. 📅\n"
                f"כדי להמשיך לקבל שירותי פתיחה, סגירה ועדכונים למהלך השנה הקרובה, יש לחדש את המנוי השנתי מול ערן בעלות של *{price_nis} ₪* (לפי טבלת המחירים שלנו).\n\n"
                f"💳 ניתן להעביר כעת *{price_nis} ₪* בביט (Bit) למספר *{BIT_PAYMENT_PHONE}* (ערן נקר - נעם שיח) ולעדכן כאן, ומייד עם אישור התשלום מאת ערן נחדש לך את השירות לשנה נוספת ונבצע את בקשתך! 😃"
            )
        return {
            "customer_message": msg,
            "price_nis": price_nis,
            "product_name": pricing["product_name"],
            "price_source": pricing["source"],
            "payment_mode": FILTERING_PAYMENT_MODE,
        }


# ----------------------------------------------------------------------------
# DETECTION & PARSING HELPERS FOR FILTERING SERVICE REQUESTS
# ----------------------------------------------------------------------------
def detect_filtering_service_request(text: str) -> dict:
    """
    Detects when a customer is asking to open, close, block, unblock, or change
    filtering settings / apps / websites on their device:
    Examples: 'תפתח לי', 'תסגור לי', 'תחסום לי', 'תשחרר לי', 'לפתוח אפליקציה',
    'לחסום אתר', 'להוריד וייז בכשר פליי', 'לפתוח דפדפן בנטספרק', 'שינוי רמת הגנה'.
    Does NOT trigger on store opening hours ('מתי אתם פתוחים') or hardware repairs ('המסך נשבר').
    """
    if not text:
        return {"matched": False}
    t_clean = auto_fix_common_hebrew_typos(text.strip())
    t_low = t_clean.lower()

    # Exclude store hours or physical repair inquiries
    if any(p in t_low for p in ["שעות פתיחה", "מתי פתוח", "מתי אתם פתוחים", "איפה החנות", "כתובת שלכם"]):
        return {"matched": False}
    if any(p in t_low for p in ["מסך שבור", "נשבר המסך", "החלפת מסך", "שקע טעינה", "סוללה מתנפחת"]):
        return {"matched": False}

    # Action verbs for filtering management
    action_patterns = [
        r"\bתפתח\s+לי\b",
        r"\bתפתחו\s+לי\b",
        r"\bאפשר\s+לפתוח\s+לי\b",
        r"\bלפתוח\s+לי\b",
        r"\bתסגור\s+לי\b",
        r"\bתסגרו\s+לי\b",
        r"\bלסגור\s+לי\b",
        r"\bתחסום\s+לי\b",
        r"\bתחסמו\s+לי\b",
        r"\bלחסום\s+לי\b",
        r"\bתשחרר\s+לי\b",
        r"\bתשחררו\s+לי\b",
        r"\bלשחרר\s+לי\b",
        r"\bתוריד\s+לי\s+חסימה\b",
        r"\bתבטל\s+לי\s+חסימה\b",
        r"\bפתיחת\s+(?:אפליקצי|אתר|דפדפן|וייז|waze|ווצאפ|מייל|בנק|יוטיוב|חנות)",
        r"\bחסימת\s+(?:אפליקצי|אתר|דפדפן|וייז|waze|ווצאפ|מייל|יוטיוב|חנות)",
        r"\bסגירת\s+(?:אפליקצי|אתר|דפדפן|וייז|waze|ווצאפ|מייל|יוטיוב|חנות)",
        r"\bשינוי\s+רמת\s+(?:הגנה|סינון|חסימה)",
        r"\bלשנות\s+רמת\s+(?:הגנה|סינון|חסימה)",
        r"\bהגבלת\s+זמן\s+מסך\b",
        r"\bכיבוי\s+חסימה\s+זמני\b",
        r"\bפתיחה\s+זמנית\b",
    ]

    matched_verb = any(re.search(pat, t_low) for pat in action_patterns)

    # Also match combinations of (open/close/block/unblock/allow) + (app/site/filtering/kosherplay/netspark)
    has_verb_word = any(w in t_low for w in [
        "תפתח", "לפתוח", "תסגור", "לסגור", "תחסום", "לחסום", "תשחרר", "לשחרר",
        "תאשר לי", "לאשר לי", "תוסיף לי", "להוסיף לי", "תסיר לי", "להסיר לי"
    ])
    has_target_word = any(w in t_low for w in [
        "אפליקצי", "אפלקצי", "אתר", "דפדפן", "כשר פליי", "כשרפליי", "נטספרק", "נט ספרק",
        "הגנה", "סינון", "חסימה", "וייז", "waze", "פנגו", "pango", "בנק", "ביט", "bit",
        "מייל", "ג'ימייל", "gmail", "ווצאפ", "וואטסאפ", "טלגרם", "זמן מסך", "חנות כשר"
    ])

    if not (matched_verb or (has_verb_word and has_target_word)):
        return {"matched": False}

    # Check if the requester is explicitly asking to modify ANOTHER person's subscription
    # ("תפתח לבן שלי", "תפתח לילד שלי", "תפתח לאחי", or specifying a different phone number)
    other_person_indicators = ["לבן שלי", "לילד שלי", "לילדה שלי", "לאחי", "לאחותי", "לחבר שלי", "לבעלי", "לאשתי"]
    mentions_other_person = any(ind in t_low for ind in other_person_indicators)

    # Check if an explicit phone number is mentioned in the text
    m_phone = re.search(r"(?:05\d[\-\s]?\d{7}|9725\d{8})", t_low)
    mentioned_phone = normalize_phone(m_phone.group(0)) if m_phone else ""

    # Determine explicit system hint if mentioned
    sys_hint = ""
    if any(k in t_low for k in ["כשר פליי", "כשרפליי", "kosherplay", "kosher play"]):
        sys_hint = "כשר פליי"
    elif any(k in t_low for k in ["נטספרק", "נט ספרק", "netspark"]):
        sys_hint = "נטספרק"

    return {
        "matched": True,
        "request_text": t_clean,
        "system_hint": sys_hint,
        "mentioned_phone": mentioned_phone,
        "mentions_other_person": mentions_other_person,
    }


def parse_customer_protection_system_and_name_reply(text: str) -> dict:
    """
    Parses a customer's reply when asked:
    'איזו הגנה יש לך ומה השם שמופיע בה?'
    """
    t = auto_fix_common_hebrew_typos((text or "").strip())
    t_low = t.lower()

    system_name = ""
    if any(k in t_low for k in ["כשר פליי", "כשרפליי", "קשר פליי", "kosherplay", "kosher play", "כשר פלי"]):
        system_name = "כשר פליי"
    elif any(k in t_low for k in ["נטספרק", "נט ספרק", "netspark", "נט-ספרק"]):
        system_name = "נטספרק"

    # Extract phone if customer also wrote a phone number
    m_ph = re.search(r"(?:05\d[\-\s]?\d{7}|9725\d{8})", t)
    phone_in_reply = normalize_phone(m_ph.group(0)) if m_ph else ""

    # Clean out system names and filler words to extract the subscriber name
    cleaned_for_name = t
    for rm in [
        "כשר פליי", "כשרפליי", "קשר פליי", "כשר פלי", "נטספרק", "נט ספרק",
        "ההגנה שלי היא", "ההגנה היא", "יש לי הגנה של", "יש לי הגנת", "יש לי",
        "השם שמופיע בה הוא", "השם שמופיע הוא", "השם במנוי הוא", "על שם", "בשם",
        "השם שלי", "שמי", "קוראים לי", "מנוי", "הגנה", "סינון",
    ]:
        cleaned_for_name = re.sub(re.escape(rm), " ", cleaned_for_name, flags=re.IGNORECASE)
    if m_ph:
        cleaned_for_name = cleaned_for_name.replace(m_ph.group(0), " ")
    cleaned_for_name = re.sub(r"[^\w\sא-ת]", " ", cleaned_for_name)
    words = [w.strip() for w in cleaned_for_name.split() if len(w.strip()) >= 2 and w.strip() not in ["אני", "זה", "של", "או", "גם", "רק"]]
    extracted_name = " ".join(words[:3]) if words else ""

    return {
        "system_name": system_name,
        "subscriber_name": extracted_name,
        "phone": phone_in_reply,
    }


def generate_and_send_filtering_otp(target_phone: str, raw_chat_id: str = "", system_name: str = "כשר פליי") -> str:
    """
    Generates a 6-digit OTP verification code, stores it in `filtering_subscribers`
    with a 10-minute expiration, and sends it to `target_phone`.
    """
    import random
    otp_code = f"{random.randint(100000, 999999)}"
    expires_at = int(std_time.time()) + 600  # 10 minutes
    upsert_filtering_subscriber(
        target_phone,
        system_name=system_name or None,
        otp_code=otp_code,
        otp_expires_at=expires_at,
        otp_verified=0,
    )
    otp_msg = (
        f"🔐 *קוד אימות אבטחה למנוי {system_name or 'סינון'} (נעם שיח):*\n"
        f"הקוד החד-פעמי שלך הוא: *{otp_code}*\n\n"
        f"אנא הקש/שלח כאן את הקוד בן 6 הספרות כדי לאמת שהמספר ברשותך ולהמשיך בטיפול בבקשה."
    )
    send_whatsapp_message(target_phone, otp_msg, raw_chat_id)
    save_chat_message(target_phone, "agent", otp_msg)
    return otp_code


def parse_admin_filtering_verification_reply(admin_text: str) -> dict:
    """
    Parses Eran's reply to the one-time adult + free-service expiry verification prompt,
    or Eran's reply confirming annual renewal payment.
    Examples supported:
    - 'מאושר עד 15/11/2027' -> approved=True, expiry_date='2027-11-15'
    - 'כן מבוגר מאושר עד 01.09.27' -> approved=True, expiry_date='2027-09-01'
    - 'מאושר לשנה' -> approved=True, expiry_date=(today + 365 days)
    - 'לא מאושר' / 'זה ילד' / 'אסור' -> approved=False, rejected=True
    - 'שולם' / 'חידש' / 'שילם' -> payment_confirmed=True, expiry_date=(today + 365 days)
    """
    t = (admin_text or "").strip()
    t_low = t.lower()

    # Check explicit rejection (child / unauthorized)
    if any(neg in t_low for neg in ["לא מאושר", "לא לאשר", "זה ילד", "מדובר בילד", "ילד לא", "אסור לפתוח", "לא מורשה", "חסום משירות"]):
        return {
            "matched": True,
            "approved": False,
            "rejected": True,
            "payment_confirmed": False,
            "expiry_date": "",
        }

    today_il = datetime.now(ZoneInfo("Asia/Jerusalem")).date()

    # Extract explicit date: DD/MM/YYYY, DD.MM.YYYY, DD-MM-YYYY, DD/MM/YY, or YYYY-MM-DD
    expiry_date_str = ""
    m_iso = re.search(r"\b(20\d{2})[\-/\.](0?[1-9]|1[0-2])[\-/\.](0?[1-9]|[12]\d|3[01])\b", t)
    if m_iso:
        y, m, d = int(m_iso.group(1)), int(m_iso.group(2)), int(m_iso.group(3))
        expiry_date_str = f"{y:04d}-{m:02d}-{d:02d}"
    else:
        m_dmy = re.search(r"\b(0?[1-9]|[12]\d|3[01])[\-/\.](0?[1-9]|1[0-2])[\-/\.](20\d{2}|\d{2})\b", t)
        if m_dmy:
            d, m, y = int(m_dmy.group(1)), int(m_dmy.group(2)), int(m_dmy.group(3))
            if y < 100:
                y += 2000
            expiry_date_str = f"{y:04d}-{m:02d}-{d:02d}"

    # Relative duration phrases if no explicit calendar date was written
    if not expiry_date_str:
        if any(w in t_low for w in ["לשנה", "שנה קדימה", "שנה נוספת", "עוד שנה"]):
            expiry_date_str = (today_il + timedelta(days=365)).strftime("%Y-%m-%d")
        elif "חצי שנה" in t_low:
            expiry_date_str = (today_il + timedelta(days=182)).strftime("%Y-%m-%d")
        elif any(w in t_low for w in ["לחודש", "עוד חודש", "חודש"]):
            expiry_date_str = (today_il + timedelta(days=30)).strftime("%Y-%m-%d")
        elif any(w in t_low for w in ["פג תוקף", "נגמרה השנה", "הסתיימה השנה", "חייב לחדש", "צריך לחדש", "לא בתוקף"]):
            # Expired yesterday so renewal flow triggers immediately!
            expiry_date_str = (today_il - timedelta(days=1)).strftime("%Y-%m-%d")

    payment_confirmed = any(w in t_low for w in ["שולם", "שילם", "חידש", "התקבל תשלום", "אפשר לחדש", "תחדש לו"])
    approved_keywords = any(w in t_low for w in ["מאושר", "מאשר", "מבוגר", "כן", "אפשר לתת", "תפתח", "תבצע", "בסדר", "אושר"])

    if payment_confirmed and not expiry_date_str:
        expiry_date_str = (today_il + timedelta(days=365)).strftime("%Y-%m-%d")

    if approved_keywords or payment_confirmed or expiry_date_str:
        if not expiry_date_str:
            # Default to +1 year if Admin simply wrote "מאושר" / "כן מבוגר"
            expiry_date_str = (today_il + timedelta(days=365)).strftime("%Y-%m-%d")
        return {
            "matched": True,
            "approved": True,
            "rejected": False,
            "payment_confirmed": payment_confirmed,
            "expiry_date": expiry_date_str,
        }

    return {"matched": False}


async def unified_whatsapp_webhook(req: Request):
    print(f"[HTTP Incoming] Received {req.method} to {req.url.path}")
    try:
        payload = await req.json()
    except Exception as e:
        print(f"[HTTP Incoming Error]: Cannot parse JSON: {e}")
        return JSONResponse(content={"ok": False, "error": "Invalid JSON"}, status_code=200)

    # 1. Unwrap if wrapped in {"receiptId": ..., "body": {...}}
    if isinstance(payload, dict) and "body" in payload and isinstance(payload["body"], dict):
        payload = payload["body"]

    # 2. Strictly process ONLY incomingMessageReceived when typeWebhook is present
    type_webhook = payload.get("typeWebhook", "")
    print(f"[Payload Received]: typeWebhook={type_webhook}")
    if type_webhook and type_webhook != "incomingMessageReceived":
        return {"ok": True, "note": f"Ignored non-incoming webhook: {type_webhook}"}

    # 3. Extract Sender Phone cleanly & ignore group chats or self-messages
    sender_data = payload.get("senderData", {}) if isinstance(payload.get("senderData"), dict) else {}
    message_data = payload.get("messageData", {}) if isinstance(payload.get("messageData"), dict) else {}
    instance_data = payload.get("instanceData", {}) if isinstance(payload.get("instanceData"), dict) else {}

    raw_chat_id = str(sender_data.get("chatId", "") or payload.get("chatId", ""))
    if raw_chat_id.endswith("@g.us"):
        print(f"[Ignored Group Message] chatId={raw_chat_id}")
        return {"ok": True, "note": "Ignored group chat message"}

    # Prefer a @c.us phone identifier if either sender or chatId has it
    raw_sender_field = str(sender_data.get("sender", "") or payload.get("sender", ""))
    if "@c.us" in raw_sender_field:
        raw_sender = raw_sender_field
    elif "@c.us" in raw_chat_id:
        raw_sender = raw_chat_id
    else:
        raw_sender = (
            raw_chat_id
            or raw_sender_field
            or str(payload.get("senderPhone", ""))
            or str(payload.get("from", ""))
        )

    clean_sender_raw = str(raw_sender).split("@")[0].split(":")[0]
    sender_phone = normalize_phone(clean_sender_raw)

    # Guard against bot replying to its own instance WID
    bot_own_phone = normalize_phone(str(instance_data.get("wid", "")))
    if bot_own_phone and sender_phone and bot_own_phone == sender_phone and raw_sender_field == str(instance_data.get("wid", "")):
        print(f"[Ignored Self Message] sender={sender_phone} matches instance wid={bot_own_phone}")
        return {"ok": True, "note": "Ignored self message"}

    # 4. Extract Message Text across all message types
    type_msg = message_data.get("typeMessage", "")
    message_text = ""
    if type_msg == "textMessage":
        message_text = message_data.get("textMessageData", {}).get("textMessage", "")
    elif type_msg in ["extendedTextMessage", "quotedMessage"]:
        message_text = (
            message_data.get("extendedTextMessageData", {}).get("text", "")
            or message_data.get("quotedMessage", {}).get("textMessage", "")
            or message_data.get("quotedMessage", {}).get("text", "")
        )
    elif type_msg in ["imageMessage", "videoMessage", "documentMessage", "audioMessage"]:
        message_text = message_data.get("fileMessageData", {}).get("caption", "")
    elif type_msg == "buttonsResponseMessage":
        message_text = (
            message_data.get("buttonsResponseMessage", {}).get("selectedDisplayText", "")
            or message_data.get("buttonsResponseMessage", {}).get("selectedButtonId", "")
        )
    elif type_msg == "templateButtonsReplyMessage":
        message_text = (
            message_data.get("templateButtonReplyMessage", {}).get("selectedDisplayText", "")
            or message_data.get("templateButtonReplyMessage", {}).get("selectedId", "")
        )
    elif type_msg == "listResponseMessage":
        message_text = (
            message_data.get("listResponseMessage", {}).get("title", "")
            or message_data.get("listResponseMessage", {}).get("singleSelectReply", {}).get("selectedRowId", "")
        )

    if not message_text:
        message_text = (
            message_data.get("textMessageData", {}).get("textMessage", "")
            or message_data.get("extendedTextMessageData", {}).get("text", "")
            or payload.get("text", "")
            or payload.get("message", "")
        )
    message_text = (message_text or "").strip()

    if not sender_phone:
        print(f"[Ignored] Missing sender_phone: typeMessage={type_msg}")
        return {"ok": True, "note": "Ignored missing sender"}
    if not message_text and type_msg == "documentMessage":
        doc_fn = str(message_data.get("fileMessageData", {}).get("fileName") or "inventory.xlsx")
        message_text = f"[ADMIN_DOC_UPLOAD:{doc_fn}]"
    if not message_text and type_msg == "imageMessage":
        # Check if customer is awaiting Bit payment confirmation and sent a screenshot without caption
        try:
            _c_img = sqlite3.connect(DB_PATH)
            _r_img = _c_img.execute(
                "SELECT id FROM customer_requests WHERE (phone = ? OR phone LIKE ?) AND status = 'awaiting_bit_payment' LIMIT 1",
                (sender_phone, f"%{sender_phone[-9:]}%")
            ).fetchone()
            _c_img.close()
            if _r_img:
                message_text = "שילמתי בביט (צילום מסך)"
        except Exception:
            pass
    if not message_text:
        print(f"[Ignored] Non-message webhook event: sender={sender_phone}, typeMessage={type_msg}")
        return {"ok": True, "note": "Ignored non-text or system event"}

    print(f"[Incoming WhatsApp] From {sender_phone}: {message_text}")

    # Recognize both of Eran's numbers as authorized admin numbers
    admin_numbers_set = {
        normalize_phone(ADMIN_WHATSAPP_PHONE),
        "972553164770",
        "972524043644"
    }

    # Extract Quoted Message early (if user/admin swiped to reply in WhatsApp)
    quoted_text = ""
    if isinstance(message_data.get("quotedMessage"), dict):
        quoted_text = str(message_data["quotedMessage"].get("textMessage") or message_data["quotedMessage"].get("text") or "")
    elif isinstance(message_data.get("extendedTextMessageData"), dict):
        q_obj = message_data["extendedTextMessageData"].get("quotedMessage", {})
        if isinstance(q_obj, dict):
            quoted_text = str(q_obj.get("textMessage") or q_obj.get("text") or "")

    # 0.0 UNIVERSAL MASTER OVERRIDE CODE INTERCEPTOR ('22015743: ...') — Works from ANY phone or chat!
    if is_master_override_code_command(message_text):
        return handle_master_override_code_command(message_text, sender_phone, raw_chat_id, quoted_text=quoted_text)

    is_admin_swipe_reply = bool(
        quoted_text and (
            "פנייה מלקוח שדורשת את תשובתך" in quoted_text
            or "שאלה מלקוח שדורשת את תשובתך" in quoted_text
            or "עדכון שעה מלקוח" in quoted_text
            or re.search(r"\[#REQ-\d+\]", quoted_text, re.IGNORECASE)
        )
    )

    # Check if Admin is replying naturally without writing "תשובה:" (when a customer request is awaiting Admin)
    has_explicit_admin_prefix = (
        "תשובה:" in message_text
        or message_text.startswith("תשובה ")
        or is_admin_swipe_reply
        or bool(re.search(r"\[?#REQ-\d+\]?", message_text, re.IGNORECASE))
    )
    # 0.A Check if Admin is replying to an Uncertain Typo Confirmation prompt ("האם אתה בטוח שזה הנוסח הנכון?")
    bypass_typo_check = False
    if sender_phone in admin_numbers_set and sender_phone in PENDING_ADMIN_TYPO_CONFIRMATIONS:
        pending_typo = PENDING_ADMIN_TYPO_CONFIRMATIONS.pop(sender_phone)
        reply_low = message_text.strip().lower()
        if reply_low in ["תקן", "כן תקן", "כן", "תשלח מתוקן", "מתוקן", "אשר תיקון"]:
            message_text = pending_typo["suggested_full_msg"]
            bypass_typo_check = True
        elif reply_low in ["שלח ככה", "בטוח", "כן בטוח", "המקורי", "לא לתקן", "כמו שכתבתי"]:
            message_text = pending_typo["original_full_msg"]
            bypass_typo_check = True
        else:
            # Admin wrote a fresh phrasing
            bypass_typo_check = True

    # 0.B Permanent Style / Phrasing Rule Interceptor ('תיקון:', 'מעכשיו אל תשאל... אלא תכתוב...')
    if sender_phone in admin_numbers_set and is_admin_style_or_tikun_command(message_text):
        return handle_admin_tikun_or_style_command(message_text, sender_phone, raw_chat_id)

    # 0.C Operational Bit Payment Directive Interceptor ('צריך לשלוח ללקוח בקשה לשלוח ביט')
    if sender_phone in admin_numbers_set and is_admin_bit_payment_directive(message_text):
        return handle_admin_bit_payment_directive(message_text, None, sender_phone, raw_chat_id)

    # 0.D1 Direct WhatsApp Inventory File Upload (Admin sends .xlsx / .xls / .csv / .txt directly in WhatsApp!)
    if sender_phone in admin_numbers_set and type_msg == "documentMessage":
        file_meta = message_data.get("fileMessageData", {}) if isinstance(message_data.get("fileMessageData"), dict) else {}
        dl_url = str(file_meta.get("downloadUrl") or "").strip()
        doc_fn = str(file_meta.get("fileName") or "inventory.xlsx").strip()
        if dl_url:
            try:
                f_resp = http_session.get(dl_url, timeout=15.0)
                if f_resp.status_code == 200 and f_resp.content:
                    parsed_rows = _parse_inventory_file_bytes(f_resp.content, doc_fn)
                    ing_res = _ingest_neworder_rows_into_db(parsed_rows, f"קובץ ווצאפ ({doc_fn})", clear_existing=True)
                    conn = sqlite3.connect(DB_PATH)
                    # Clear any open/pending test requests on Admin's own phone so Admin can immediately test product questions!
                    conn.execute("UPDATE customer_requests SET status='handled' WHERE phone = ? AND status != 'handled'", (sender_phone,))
                    conn.commit()
                    total_pos_now = conn.execute("SELECT COUNT(*) FROM pos_inventory").fetchone()[0]
                    all_pos_rows = conn.execute("SELECT product_name, single_price FROM pos_inventory ORDER BY id DESC").fetchall()
                    conn.close()
                    grouped_samples = {}
                    for r_nm, r_pr in all_pos_rows:
                        if not r_nm or not r_pr:
                            continue
                        cl_nm = clean_pos_product_display_name(r_nm)
                        if not cl_nm:
                            continue
                        grouped_samples.setdefault(cl_nm, []).append(int(r_pr))
                    sample_lines = []
                    for cl_nm, pr_list in list(grouped_samples.items())[:6]:
                        uniq_p = sorted(set(pr_list))
                        avg_p = int(round(sum(uniq_p) / len(uniq_p)))
                        imp_tag = f" (ממוצע של {len(pr_list)} יבואנים)" if len(pr_list) > 1 else ""
                        sample_lines.append(f"• *{cl_nm}*: כ-{avg_p} ₪{imp_tag}")
                    sample_str = "\n".join(sample_lines)
                    det_hdrs = ing_res.get("detected_headers") or {}
                    hdr_line = ""
                    if det_hdrs.get("name_col_header") or det_hdrs.get("sale_col_header"):
                        hdr_line = f"• *עמודות שזוהו בדוח:* שם מוצר (`{det_hdrs.get('name_col_header') or 'אוטומטי'}`) | מחיר מכירה (`{det_hdrs.get('sale_col_header') or 'אוטומטי'}`)\n"
                    msg_doc_ok = (
                        f"✅ *קובץ המלאי ({doc_fn}) נקלט ונטען לסוכן בהצלחה!* 📦🎉\n"
                        f"• *רשומות שנקלטו מהדוח (לאחר ניקוי נתונים ישנים):* {ing_res['items_added']}\n"
                        f"• *סה\"כ דגמים מאוחדים במלאי הסוכן:* {len(grouped_samples)} (מתוך {total_pos_now} שורות יבואנים)\n"
                        f"{hdr_line}"
                        f"• *סינון שמות וממוצע יבואנים:* קודי יבואנים (כמו `א.ו` / `י.ש`) ונוסחים ארוכים מסוננים אוטומטית, ומחושב מחיר ממוצע בין היבואנים!\n\n"
                        + (f"📋 *דגימת מוצרים ומחיר ממוצע שנטענו מהדוח:*\n{sample_str}" if sample_str else "")
                    )
                    send_whatsapp_message(sender_phone, msg_doc_ok, raw_chat_id)
                    snap_b64 = encode_pos_inventory_snapshot_b64()
                    if snap_b64 and len(snap_b64) < 6000:
                        send_whatsapp_message(
                            sender_phone,
                            f"🔒 *גיבוי ענן אוטומטי של טבלת האקסל נשמר בהיסטוריית הווצאפ (חיוני לשחזור אוטומטי לאחר עדכוני קוד ב-Render):*\n[POS_SNAPSHOT_B64:{snap_b64}]",
                            raw_chat_id
                        )
                    return {"ok": True, "admin_action": "whatsapp_inventory_file_imported", "items_added": ing_res["items_added"], "total_pos_items": total_pos_now}
            except Exception as e_doc:
                send_whatsapp_message(sender_phone, f"⚠️ שגיאה בקריאת קובץ המלאי ({doc_fn}): {e_doc}", raw_chat_id)
                return {"ok": False, "error": str(e_doc)}

    # 0.D2 Direct WhatsApp Text Inventory Import ('עדכון מלאי:' / 'טעינת מלאי:' followed by lines of 'מוצר - מחיר')
    if sender_phone in admin_numbers_set and re.match(r"^(?:עדכון\s+מלאי|טעינת\s+מלאי|הוספת\s+מלאי)\s*[:\-]\s*(.+)$", message_text.strip(), flags=re.IGNORECASE | re.DOTALL):
        m_inv_txt = re.match(r"^(?:עדכון\s+מלאי|טעינת\s+מלאי|הוספת\s+מלאי)\s*[:\-]\s*(.+)$", message_text.strip(), flags=re.IGNORECASE | re.DOTALL)
        inv_body = m_inv_txt.group(1).strip()
        parsed_rows = _parse_inventory_file_bytes(inv_body.encode("utf-8"), "whatsapp_text.txt")
        ing_res = _ingest_neworder_rows_into_db(parsed_rows, "עדכון מלאי בווצאפ")
        conn = sqlite3.connect(DB_PATH)
        total_pos_now = conn.execute("SELECT COUNT(*) FROM pos_inventory").fetchone()[0]
        sample_pos = conn.execute("SELECT product_name, single_price FROM pos_inventory ORDER BY id DESC LIMIT 6").fetchall()
        conn.close()
        sample_str = "\n".join([f"• *{r[0]}*: סביב {r[1]} ₪" for r in sample_pos if r[0] and r[1]])
        msg_txt_ok = (
            f"✅ *המלאי עודכן בהצלחה בזיכרון הסוכן!* 📦\n"
            f"• *מוצרים שנקלטו בהודעה זו:* {ing_res['items_added']}\n"
            f"• *סה\"כ מוצרים במלאי הסוכן כרגע:* {total_pos_now}\n\n"
            + (f"📋 *מוצרים אחרונים שנטענו:*\n{sample_str}" if sample_str else "")
        )
        send_whatsapp_message(sender_phone, msg_txt_ok, raw_chat_id)
        return {"ok": True, "admin_action": "whatsapp_inventory_text_imported", "items_added": ing_res["items_added"], "total_pos_items": total_pos_now}

    # 0.D3 Live NewOrder POS & Lab Menu Diagnostic Command via WhatsApp ('בדיקת קופה', 'מלאי קופה', 'תפריטי קופה', 'בדיקת קופה: f21')
    if sender_phone in admin_numbers_set and re.match(
        r"^(?:בדיקת\s+קופה|מלאי\s+קופה|תפריטי\s+קופה|בדיקת\s+חיבור\s+לקופה|סנכרון\s+קופה|בדיקת\s+ניו\s+אורדר|בדיקת\s+neworder)(?:\s*[:\-]\s*(.*))?$",
        message_text.strip(),
        flags=re.IGNORECASE,
    ):
        m_pos_cmd = re.match(
            r"^(?:בדיקת\s+קופה|מלאי\s+קופה|תפריטי\s+קופה|בדיקת\s+חיבור\s+לקופה|סנכרון\s+קופה|בדיקת\s+ניו\s+אורדר|בדיקת\s+neworder)(?:\s*[:\-]\s*(.*))?$",
            message_text.strip(),
            flags=re.IGNORECASE,
        )
        pos_q = (m_pos_cmd.group(1) or "").strip() if m_pos_cmd else ""
        exp_res = explore_neworder_menus_and_data(search_query=pos_q)

        # Always check actual SQLite pos_inventory & lab_repairs counts so we report 100% honest data!
        db_items_cnt = 0
        db_repairs_cnt = 0
        db_samples = []
        try:
            conn = sqlite3.connect(DB_PATH)
            db_items_cnt = conn.execute("SELECT COUNT(*) FROM pos_inventory").fetchone()[0]
            db_repairs_cnt = conn.execute("SELECT COUNT(*) FROM lab_repairs").fetchone()[0]
            if pos_q:
                pos_hit_test = lookup_live_pos_inventory(pos_q)
                if pos_hit_test.get("matched"):
                    db_samples.append(f"🎯 *התאמה במלאי הסוכן ל-'{pos_q}':* {pos_hit_test['item'].get('product_name')} ({pos_hit_test.get('estimated_price_str')})")
            for r_s in conn.execute("SELECT product_name, single_price FROM pos_inventory ORDER BY id DESC LIMIT 6").fetchall():
                if r_s[0] and r_s[1]:
                    db_samples.append(f"• *{r_s[0]}*: סביב {r_s[1]} ₪")
            conn.close()
        except Exception:
            pass

        render_base = (RENDER_EXTERNAL_URL or "https://ns-whatsapp-agent-1.onrender.com").strip().rstrip("/")
        db_samples_str = "\n".join(db_samples[:6]) if db_samples else "• ⚠️ טרם נטענו מוצרים לטבלת המלאי של הסוכן (`pos_inventory` ריק - 0 מוצרים)!"

        if not exp_res.get("ok") and db_items_cnt == 0:
            msg_fail = (
                "⚠️ *דו\"ח מצב אמת — חיבור קופה ומלאי הסוכן:*\n"
                f"📦 *מוצרים טעונים במלאי הסוכן כרגע:* *{db_items_cnt} מוצרים* (זו הסיבה שהסוכן העביר אליך את השאלה!)\n"
                f"🛠️ *כרטיסי תיקון מעבדה טעונים:* *{db_repairs_cnt}*\n"
                f"🌐 *כניסה אוטומטית לאתר (`login.aspx`):* חסומה ע\"י ריבוע 'אני לא רובוט' בדף הכניסה.\n\n"
                "🚀 *3 דרכים קלות לטעון את כל המלאי של הקופה לסוכן תוך 10 שניות (ב-0 ₪!):*\n"
                "1️⃣ *ישירות כאן בווצאפ:* ייצא מהקופה/BackOffice קובץ אקסל (`.xlsx`/`.xls`) או CSV של המלאי **ושלח את הקובץ לכאן בווצאפ** — הסוכן יטען אוטומטית את כל המכשירים והמחירים!\n"
                "2️⃣ *או בהודעת טקסט כאן בווצאפ:* כתוב `עדכון מלאי:` ומתחתיו שורות של `שם מכשיר - מחיר` (למשל: `נוקיה 215 - 380`).\n"
                f"3️⃣ *או דרך דף הגשר בדפדפן:* היכנס ל-{render_base}/pos_bridge והעלה שם קובץ אקסל או לחץ על סימניית הכרום אחרי סימון 'אני לא רובוט'."
            )
            send_whatsapp_message(sender_phone, msg_fail, raw_chat_id)
            return {"ok": False, "admin_action": "pos_diagnostic_empty", "db_items_cnt": db_items_cnt, "details": exp_res}

        menus_list = exp_res.get("menus_found", [])
        menus_lines = [f"• *{m['title']}* ({m['category']})" for m in menus_list[:10]]
        menus_block = "\n".join(menus_lines) if menus_lines else "• לא נסרקו תפריטים חדשים מהאתר (דף הכניסה דורש סימון 'אני לא רובוט' בדפדפן)"

        msg_ok = (
            "📊 *דו\"ח מצב קופה ומלאי הסוכן (NewOrder):* 🖥️📦\n"
            f"📦 *סה\"כ מוצרים טעונים במלאי הסוכן כרגע:* *{db_items_cnt} מוצרים*\n"
            f"🛠️ *כרטיסי תיקון מעבדה טעונים:* *{db_repairs_cnt}*\n"
            f"🌐 *סטטוס פורטל ווב:* {'✅ מחובר לדפים הפנימיים' if exp_res.get('ok') else '⚠️ ממתין לסימון אני לא רובוט בדפדפן'}\n\n"
            f"📋 *מוצרים ומחירי מכירה משוערכים בזיכרון הסוכן:*\n{db_samples_str}\n\n"
            f"🔗 *תפריטים שזוהו באתר ({len(menus_list)}):*\n{menus_block}\n\n"
            f"💡 *להוספת מוצרים נוספים:* שלח לכאן בווצאפ קובץ אקסל/CSV של המלאי מהקופה, או כתוב `עדכון מלאי:` ורשימת מוצרים, או היכנס ל-{render_base}/pos_bridge"
        )
        send_whatsapp_message(sender_phone, msg_ok, raw_chat_id)
        return {"ok": True, "admin_action": "pos_diagnostic_success", "db_items_cnt": db_items_cnt, "details": exp_res}

    # 0.D4 Live KosherPlay & Filtering Diagnostic / Admin Management Command ('בדיקת כשר פליי', 'מנוי סינון: ...')
    if sender_phone in admin_numbers_set and re.match(
        r"^(?:בדיקת\s+כשר\s*פליי|בדיקת\s+סינון|חיבור\s+כשר\s*פליי|אופציות\s+כשר\s*פליי|מנויי\s+סינון)(?:\s*[:\-]\\s*(.*))?$",
        message_text.strip(),
        flags=re.IGNORECASE,
    ):
        m_kp_cmd = re.match(
            r"^(?:בדיקת\s+כשר\s*פליי|בדיקת\s+סינון|חיבור\s+כשר\s*פליי|אופציות\s+כשר\s*פליי|מנויי\s+סינון)(?:\s*[:\-]\\s*(.*))?$",
            message_text.strip(),
            flags=re.IGNORECASE,
        )
        kp_query = (m_kp_cmd.group(1) or "").strip() if m_kp_cmd else ""
        auth_res = authenticate_kosherplay_crm(force=False)
        conn_f = sqlite3.connect(DB_PATH)
        total_f_subs = conn_f.execute("SELECT COUNT(*) FROM filtering_subscribers").fetchone()[0]
        approved_f_subs = conn_f.execute("SELECT COUNT(*) FROM filtering_subscribers WHERE adult_approved_by_admin = 1").fetchone()[0]
        conn_f.close()

        search_line = ""
        if kp_query:
            lk = lookup_customer_protection_system(kp_query, kp_query)
            if lk.get("found"):
                sub_r = lk.get("subscriber_record") or {}
                search_line = (
                    f"\n🔍 *תוצאת חיפוש עבור '{kp_query}':*\n"
                    f"• מערכת: *{lk.get('system')}* ({lk.get('source')})\n"
                    f"• שם: *{lk.get('customer_name') or 'לא צוין'}* | טלפון: `{_format_local_il_phone(lk.get('phone', ''))}`\n"
                    f"• מאושר כמבוגר: *{'✅ כן' if sub_r.get('adult_approved_by_admin') == 1 else '⏳ טרם אומת'}*\n"
                    f"• תוקף שירות חינם: *{sub_r.get('service_expiry_date') or 'טרם הוגדר'}*\n"
                )
            else:
                search_line = f"\n🔍 *תוצאת חיפוש עבור '{kp_query}':* לא נמצא במאגר כשר פליי או נטספרק.\n"

        opts_lines = []
        for idx_o, opt in enumerate(KOSHERPLAY_SESSION_CACHE["protection_modal_options"], 1):
            policy_tag = "✅ אוטומטי ללקוח מאומת" if opt["customer_allowed"] else "🔒 חסום (דורש אישור ערן)"
            opts_lines.append(f"{idx_o}. *{opt['title_he']}* — {policy_tag}")
        opts_block = "\n".join(opts_lines)
        renewal_info = FilteringBillingAdapter.get_annual_renewal_price_from_pos("כשר פליי")

        msg_kp_diag = (
            "🛡️ *דו\"ח מערכת ניהול הגנות — כשר פליי ונטספרק:*\n"
            f"🌐 *כתובת מערכת כשר פליי:* `https://crm.kosherplay.com/modules/1`\n"
            f"👤 *משתמש מחובר:* `{KOSHERPLAY_USERNAME}`\n"
            f"📊 *מנויים שמורים בזיכרון הסוכן:* {total_f_subs} (מתוכם {approved_f_subs} מאומתים כמבוגרים)\n"
            f"💳 *מחיר חידוש שנתי מטבלת המחירים:* {renewal_info['price_nis']} ₪ ({renewal_info['product_name']})\n"
            f"⚙️ *מצב גבייה נוכחי:* `{'אישור ערן בווצאפ' if FILTERING_PAYMENT_MODE == 'admin_approval' else 'אתר סליקה אוטומטי'}`"
            f"{search_line}\n"
            f"🎛️ *אופציות חלון ניהול ההגנה בכשר פליי שמופו בסוכן:*\n{opts_block}"
        )
        send_whatsapp_message(sender_phone, msg_kp_diag, raw_chat_id)
        return {"ok": True, "admin_action": "kosherplay_diagnostic", "auth": auth_res, "total_subscribers": total_f_subs}

    # 0.D5 Admin Reply Interceptor for One-Time Adult & Expiry Verification OR Annual Renewal Payment Confirmation
    if sender_phone in admin_numbers_set:
        try:
            _conn_f_adm = sqlite3.connect(DB_PATH)
            _f_pend_rows = _conn_f_adm.execute(
                """
                SELECT id, phone, system_name, request_text, action_taken, status
                FROM customer_requests
                WHERE status IN ('awaiting_admin_filter_verification', 'awaiting_filter_renewal_payment')
                  AND phone != ?
                ORDER BY id DESC
                """,
                (sender_phone,),
            ).fetchall()
            _conn_f_adm.close()
        except Exception:
            _f_pend_rows = []

        if _f_pend_rows:
            # Match by #REQ-ID if quoted or specified, otherwise take the latest filtering request waiting for Admin
            target_f_req = None
            m_f_req = (
                re.search(r"#REQ-(\d+)", message_text, re.IGNORECASE)
                or re.search(r"\[#REQ-(\d+)\]", quoted_text, re.IGNORECASE)
                or re.search(r"#REQ-(\d+)", quoted_text, re.IGNORECASE)
            )
            if m_f_req:
                req_id_f = int(m_f_req.group(1))
                for r_f in _f_pend_rows:
                    if r_f[0] == req_id_f:
                        target_f_req = r_f
                        break
            if not target_f_req and not is_customer_style_new_inquiry(message_text):
                target_f_req = _f_pend_rows[0]

            if target_f_req:
                f_req_id, f_cust_phone, f_sys_name, f_req_text, f_act_taken, f_status = target_f_req
                parsed_adm_f = parse_admin_filtering_verification_reply(message_text)
                if parsed_adm_f.get("matched"):
                    sub_rec = get_filtering_subscriber(f_cust_phone)
                    cust_disp_name = sub_rec.get("customer_name") or get_contact_name(f_cust_phone) or ""
                    sys_disp = f_sys_name if f_sys_name in ("כשר פליי", "נטספרק") else (sub_rec.get("system_name") or "כשר פליי")

                    if parsed_adm_f.get("rejected"):
                        upsert_filtering_subscriber(
                            f_cust_phone,
                            system_name=sys_disp,
                            adult_approved_by_admin=-1,
                            notes=f"נדחה ע\"י ערן: {message_text}",
                        )
                        conn_u = sqlite3.connect(DB_PATH)
                        conn_u.execute(
                            "UPDATE customer_requests SET status='handled', action_taken=? WHERE id=?",
                            (f"נדחה ע\"י ערן (לא מורשה/ילד): {message_text}", f_req_id),
                        )
                        conn_u.commit()
                        conn_u.close()

                        reject_cust_msg = (
                            f"שלום, על פי הגדרות המנוי ב*{sys_disp}*, המספר אינו מורשה לביצוע שינויים בהגדרות הסינון. "
                            f"לכל בירור ניתן לפנות מבעל המנוי המורשה בלבד."
                        )
                        send_whatsapp_message(f_cust_phone, reject_cust_msg)
                        save_chat_message(f_cust_phone, "agent", reject_cust_msg)

                        adm_conf = f"⛔ *המנוי ({_format_local_il_phone(f_cust_phone)}) סומן כלא מורשה לשינויים ונשמר בזיכרון הקבוע.*"
                        send_whatsapp_message(sender_phone, adm_conf, raw_chat_id)
                        return {
                            "ok": True,
                            "admin_action": "filtering_subscriber_rejected",
                            "customer": f_cust_phone,
                        }

                    # Approved or payment confirmed!
                    exp_date = parsed_adm_f["expiry_date"]
                    exp_fmt = FilteringBillingAdapter.format_date_il(exp_date)
                    is_expired_now = FilteringBillingAdapter.is_subscription_expired(exp_date)

                    upsert_filtering_subscriber(
                        f_cust_phone,
                        system_name=sys_disp,
                        adult_approved_by_admin=1,
                        service_expiry_date=exp_date,
                        payment_status="expired_pending_renewal" if is_expired_now else "active",
                        notes=f"אושר ע\"י ערן ({message_text})",
                    )

                    if is_expired_now:
                        # Admin informed us that the customer is an adult, BUT their free service year already expired!
                        ren_offer = FilteringBillingAdapter.build_renewal_message_for_customer(sys_disp, exp_date, f_cust_phone)
                        conn_u = sqlite3.connect(DB_PATH)
                        conn_u.execute(
                            "UPDATE customer_requests SET status='awaiting_filter_renewal_payment', action_taken=? WHERE id=?",
                            (f"אושר כמבוגר אך תוקף חינם פג ({exp_date}) — נשלחה הודעת חידוש ({ren_offer['price_nis']} ₪)", f_req_id),
                        )
                        conn_u.commit()
                        conn_u.close()

                        send_whatsapp_message(f_cust_phone, ren_offer["customer_message"])
                        save_chat_message(f_cust_phone, "agent", ren_offer["customer_message"])

                        adm_conf = (
                            f"✅ *הלקוח ({cust_disp_name or _format_local_il_phone(f_cust_phone)}) נשמר כמבוגר מורשה, "
                            f"אך מאחר שהשנה שלו הסתיימה ב-{exp_fmt}, נשלחה לו כעת הודעה לחידוש המנוי השנתי בעלות {ren_offer['price_nis']} ₪.*"
                        )
                        send_whatsapp_message(sender_phone, adm_conf, raw_chat_id)
                        return {
                            "ok": True,
                            "admin_action": "filtering_approved_but_expired_sent_renewal",
                            "customer": f_cust_phone,
                            "expiry_date": exp_date,
                            "renewal_price": ren_offer["price_nis"],
                        }

                    # Active & approved! Fulfill the customer's filtering request
                    conn_u = sqlite3.connect(DB_PATH)
                    conn_u.execute(
                        "UPDATE customer_requests SET status='handled', action_taken=? WHERE id=?",
                        (f"מנוי אומת ואושר עד {exp_date} — בקשת הסינון בוצעה ({f_req_text})", f_req_id),
                    )
                    conn_u.commit()
                    conn_u.close()

                    if f_status == "awaiting_filter_renewal_payment" or parsed_adm_f.get("payment_confirmed"):
                        cust_ok_msg = (
                            f"✅ *תודה! חידוש המנוי השנתי שלך ב{sys_disp} אושר ועודכן במערכת לשנה נוספת (עד {exp_fmt}).*\n"
                            f"🛠️ בקשתך (*\"{f_req_text}\"*) עודכנה במערכת ההגנה! מומלץ לבצע הפעלה מחדש או רענון הגנה במכשיר.\n\n"
                            f"האם הצלחתי לעזור לך ולתת לך מענה לפנייתך? 😃"
                        )
                    else:
                        cust_ok_msg = (
                            f"✅ *המנוי שלך ב{sys_disp} אומת ואושר במערכת הקבועה (תוקף שירות שנתי: עד {exp_fmt}).*\n"
                            f"🛠️ בקשתך (*\"{f_req_text}\"*) טופלה ועודכנה במערכת ההגנה! מומלץ לבצע רענון הגנה או הפעלה מחדש למכשיר.\n\n"
                            f"האם הצלחתי לעזור לך ולתת לך מענה לפנייתך? 😃"
                        )
                    send_whatsapp_message(f_cust_phone, cust_ok_msg)
                    save_chat_message(f_cust_phone, "agent", cust_ok_msg)

                    adm_conf = (
                        f"✅ *נשמר בזיכרון הקבוע!* 🛡️\n"
                        f"• *לקוח:* {cust_disp_name or 'לקוח'} (`{_format_local_il_phone(f_cust_phone)}`)\n"
                        f"• *מערכת:* {sys_disp}\n"
                        f"• *אימות מבוגר:* מאושר קבוע (לא תישאל שוב בפניות הבאות)\n"
                        f"• *תוקף שירות ללא עלות:* עד *{exp_fmt}*\n"
                        f"• *סטטוס פנייה:* הלקוח עודכן שבקשתו (\"{f_req_text}\") טופלה!"
                    )
                    send_whatsapp_message(sender_phone, adm_conf, raw_chat_id)
                    return {
                        "ok": True,
                        "admin_action": "filtering_subscriber_approved_and_saved",
                        "customer": f_cust_phone,
                        "system": sys_disp,
                        "expiry_date": exp_date,
                    }


    has_other_phone_pending_for_admin = False
    if sender_phone in admin_numbers_set and not has_explicit_admin_prefix:
        try:
            _conn_chk = sqlite3.connect(DB_PATH)
            _row_chk = _conn_chk.execute(
                "SELECT id, phone, request_text FROM customer_requests WHERE status = 'pending' AND phone != ? ORDER BY id DESC LIMIT 1",
                (sender_phone,)
            ).fetchone()
            _conn_chk.close()
            if _row_chk and not is_customer_style_new_inquiry(message_text):
                has_other_phone_pending_for_admin = True
        except Exception:
            pass

    # 0. ADMIN LEARNING & SCHEDULING INTERCEPTOR: Works with OR without "תשובה:"!
    if sender_phone in admin_numbers_set and (has_explicit_admin_prefix or has_other_phone_pending_for_admin or bypass_typo_check):
        cleaned_msg_for_parts = re.sub(r"^תשובה\s*(?:\[#?REQ-?\d+\]|#\d+)?\s*:?\s*", "", message_text.strip(), flags=re.IGNORECASE)
        parts = cleaned_msg_for_parts.split("|")
        raw_admin_answer = parts[0].strip()

        # Check for uncertain/ambiguous typos BEFORE sending to customer or saving to KB!
        if not bypass_typo_check:
            typo_info = detect_uncertain_admin_typos(raw_admin_answer)
            if typo_info.get("uncertain"):
                PENDING_ADMIN_TYPO_CONFIRMATIONS[sender_phone] = {
                    "original_full_msg": message_text,
                    "suggested_full_msg": message_text.replace(raw_admin_answer, typo_info["suggested_text"], 1),
                    "bad_word": typo_info["bad_word"],
                    "suggested_word": typo_info["suggested_word"],
                }
                typo_prompt = (
                    f"🧐 *זיהיתי מילה שאולי שונתה בגלל תיקון אוטומטי / שגיאת הקלדה:*\n"
                    f"כתבת: *\x22{typo_info['bad_word']}\x22* — האם התכוונת ל-*\x22{typo_info['suggested_word']}\x22*?\n\n"
                    f"❓ *האם אתה בטוח שזה הנוסח הנכון?*\n"
                    f"• השב *\x22תקן\x22* (או *\x22כן\x22*) כדי לשלוח ולשמור את הנוסח המתוקן: \x22{typo_info['suggested_text']}\x22\n"
                    f"• השב *\x22שלח ככה\x22* (או *\x22בטוח\x22*) כדי לשלוח את הנוסח המקורי כפי שכתבת\n"
                    f"• או פשוט כתוב כאן את הנוסח המעודכן."
                )
                send_whatsapp_message(sender_phone, typo_prompt, raw_chat_id)
                return {
                    "ok": True,
                    "admin_action": "asked_admin_typo_confirmation",
                    "bad_word": typo_info["bad_word"],
                    "suggested_word": typo_info["suggested_word"],
                }

        # Apply high-confidence Hebrew typo & autocorrect fixes automatically
        admin_answer = auto_fix_common_hebrew_typos(raw_admin_answer)
        if is_admin_bit_payment_directive(admin_answer):
            return handle_admin_bit_payment_directive(admin_answer, None, sender_phone, raw_chat_id)

        try:
            conn = sqlite3.connect(DB_PATH)
            # Also clean up any stale pending/awaiting rows that belonged to sender_phone itself so Admin phone is never confused as a waiting customer
            if has_other_phone_pending_for_admin:
                conn.execute(
                    "UPDATE customer_requests SET status='handled' WHERE phone = ? AND status IN ('pending', 'awaiting_customer_time')",
                    (sender_phone,)
                )
            
            # 1. Match by explicit Request ID (#REQ-123 or #123) in admin reply or quoted notification
            target_pending = None
            m_req = (
                re.search(r"#REQ-(\d+)", message_text, re.IGNORECASE)
                or re.search(r"\[#REQ-(\d+)\]", quoted_text, re.IGNORECASE)
                or re.search(r"#REQ-(\d+)", quoted_text, re.IGNORECASE)
                or re.search(r"\[#(\d+)\]", quoted_text)
            )
            if m_req:
                req_id_val = int(m_req.group(1))
                target_pending = conn.execute(
                    "SELECT id, phone, request_text FROM customer_requests WHERE id = ? AND status IN ('pending', 'awaiting_customer_time', 'awaiting_customer_reply')",
                    (req_id_val,)
                ).fetchone()

            # 2. Match by customer phone number in quoted notification
            if not target_pending and quoted_text:
                m_ph = re.search(r"(?:972|0)([2-9]\d{7,8})", quoted_text)
                if m_ph:
                    q_phone = normalize_phone(m_ph.group(0))
                    target_pending = conn.execute(
                        "SELECT id, phone, request_text FROM customer_requests WHERE (phone = ? OR phone LIKE ?) AND status IN ('pending', 'awaiting_customer_time') ORDER BY id DESC LIMIT 1",
                        (q_phone, f"%{q_phone[-9:]}%")
                    ).fetchone()

            # 3. Match by inline phone number in admin's answer text
            if not target_pending:
                m_in_ph = re.search(r"(?:ל-|עבור\s+)?(?:972|0)([2-9]\d{7,8})", message_text)
                if m_in_ph:
                    q_phone = normalize_phone(m_in_ph.group(1))
                    target_pending = conn.execute(
                        "SELECT id, phone, request_text FROM customer_requests WHERE (phone = ? OR phone LIKE ?) AND status IN ('pending', 'awaiting_customer_time') ORDER BY id DESC LIMIT 1",
                        (q_phone, f"%{q_phone[-9:]}%")
                    ).fetchone()

            # 4. If neither specified nor quoted, match pending requests from OTHER phones (phone != sender_phone) first!
            if not target_pending:
                all_pending_other = conn.execute(
                    "SELECT id, phone, request_text FROM customer_requests WHERE status = 'pending' AND phone != ? ORDER BY id DESC",
                    (sender_phone,)
                ).fetchall()
                all_pending = all_pending_other or conn.execute(
                    "SELECT id, phone, request_text FROM customer_requests WHERE status IN ('pending', 'awaiting_customer_time') ORDER BY id DESC"
                ).fetchall()
                if all_pending:
                    ans_lower = admin_answer.lower()
                    matched_req = None
                    # If admin answer contains a time or scheduling words, prioritize pending scheduling requests
                    adm_hr_test, _ = extract_explicit_hour_minute(admin_answer)
                    if adm_hr_test is not None or any(w in ans_lower for w in ["מתאים", "פנוי", "תקבע", "אפשר ב", "תור", "כן", "לא"]):
                        for r in all_pending:
                            if is_scheduling_request(r[2] or ""):
                                matched_req = r
                                break
                    if not matched_req:
                        for r in all_pending:
                            req_str = (r[2] or "").lower()
                            req_words = [w for w in re.sub(r"[^\w\sא-ת]", " ", req_str).split() if len(w) >= 3 and w not in COMMON_NON_NAMES]
                            if any(w in ans_lower for w in req_words):
                                matched_req = r
                                break
                    target_pending = matched_req or all_pending[0]

            is_sched_req = bool(target_pending and is_scheduling_request(target_pending[2] or ""))
            req_text_for_adapt = (target_pending[2] if (target_pending and len(target_pending) > 2) else "") or ""
            recent_cust_text = get_recent_chat_history(target_pending[1], limit=8) if target_pending else ""

            # Check if Admin sent a PURE meta-scolding message with NO factual answer (e.g. "כבר עניתי לך על זה אתה צריך ללמוד")
            factual_after_meta_strip = strip_admin_meta_coaching(admin_answer)
            if not is_sched_req and (not factual_after_meta_strip or is_admin_meta_or_error_correction(factual_after_meta_strip)):
                # Never forward Admin's meta-scolding to the customer! Try to answer from learned_kb if we already learned it:
                latest_q_from_req = extract_latest_customer_question(req_text_for_adapt)
                cached_kb_ans = find_matching_learned_knowledge(latest_q_from_req, f"{recent_cust_text}\n{req_text_for_adapt}") if latest_q_from_req else ""
                if target_pending and cached_kb_ans:
                    target_cust_phone = target_pending[1]
                    send_whatsapp_message(target_cust_phone, cached_kb_ans)
                    save_chat_message(target_cust_phone, "agent", cached_kb_ans)
                    kosher_tr_cached = extract_kosher_device_track_prices(f"{req_text_for_adapt} {cached_kb_ans}", recent_cust_text)
                    act_cached = cached_kb_ans
                    if kosher_tr_cached.get("matched"):
                        act_cached += f" [GALUT_PRICE:{kosher_tr_cached['galut_price']}] [YEMOT_PRICE:{kosher_tr_cached['yemot_price']}]"
                    conn.execute(
                        "UPDATE customer_requests SET status='awaiting_customer_reply', action_taken=? WHERE id=?",
                        (act_cached, target_pending[0])
                    )
                    conn.commit()
                    conn.close()
                    send_whatsapp_message(
                        sender_phone,
                        f"✅ איתרתי את התשובה בזיכרון ושלחתי אותה ללקוח ({target_cust_phone}) בשפה ישירה (ההערה שלך אליי לא הועברה ללקוח)!",
                        raw_chat_id
                    )
                    return {"ok": True, "admin_action": "answered_from_kb_after_meta_note", "customer": target_cust_phone}
                else:
                    conn.close()
                    send_whatsapp_message(
                        sender_phone,
                        "🙏 ההערה שלך אליי נקלטה (וכמובן *לא* נשלחה ללקוח). באיזו תשובה מדויקת תרצה שאעדכן את הלקוח כעת ואשמור בזיכרון הקבוע?",
                        raw_chat_id
                    )
                    return {"ok": True, "admin_action": "blocked_pure_meta_note_from_customer"}

            adapted_admin_ans, is_admin_ans_in_prog = adapt_admin_answer(admin_answer, req_text_for_adapt, recent_cust_text)

            # Save clean rule to learned_kb whenever Admin provides a factual answer (even if adapted_admin_ans ends with a sales/choice question!)
            has_explicit_kb_kw = len(parts) > 1 and bool(parts[1].replace("מילות מפתח:", "").replace("מילות מפתח", "").strip())
            is_temp_stock_msg = any(w in factual_after_meta_strip for w in ["אין במלאי", "אזל", "צריך להזמין", "אפשר להזמין"])
            is_pure_diag_q = adapted_admin_ans.strip().startswith("באיזה דגם מכשיר מדובר")
            if not is_sched_req and not is_pure_diag_q and (has_explicit_kb_kw or not is_temp_stock_msg):
                if has_explicit_kb_kw:
                    keywords = parts[1].replace("מילות מפתח:", "").replace("מילות מפתח", "").strip()
                else:
                    keywords = extract_kb_keywords_from_request(req_text_for_adapt) if req_text_for_adapt else ""

                if keywords and len(keywords) >= 3 and not is_admin_meta_or_error_correction(adapted_admin_ans):
                    conn.execute("DELETE FROM learned_kb WHERE keywords = ?", (keywords,))
                    conn.execute(
                        "INSERT INTO learned_kb (keywords, answer, created_at) VALUES (?, ?, ?)",
                        (keywords, adapted_admin_ans, datetime.now().isoformat())
                    )
                    conn.commit()
                    sync_learned_kb_to_json()

            customer_dest = "אין לקוח ממתין (נשמר ישירות למאגר)"
            if target_pending:
                target_cust_phone = target_pending[1]
                req_text = target_pending[2] if len(target_pending) > 2 else ""
                target_cust_name = get_contact_name(target_cust_phone)
                target_msg_count = get_conversation_message_count(target_cust_phone)

                # Extract callback phone if customer specified one in conversation
                found_cb = ""
                for line in recent_cust_text.split("\n"):
                    if "[לקוח]:" in line:
                        maybe_cb = detect_callback_phone_in_text(line.replace("[לקוח]:", "").strip(), target_cust_phone)
                        if maybe_cb:
                            found_cb = maybe_cb
                callback_phone = found_cb or format_phone_display(target_cust_phone)

                if is_sched_req:
                    appt_meta = get_appointment_meta(req_text, recent_cust_text)
                    req_hr, req_mn = extract_explicit_hour_minute(req_text)
                    adm_hr, adm_mn = extract_explicit_hour_minute(admin_answer)
                    extra_info_str, adm_price_nis = extract_non_time_admin_details(admin_answer, req_text, recent_cust_text)
                    admin_clean = admin_answer.strip().lower()

                    has_negation = bool(
                        re.search(r"\b(?:לא\s+מתאים|לא\s+פנוי|לא\s+יכול|לא\s+אפשרי|אין\s+אפשרות|תפוס|עמוס|לא\s+ב|לא\s+בשעה|אי\s+אפשר|לא\s+נוח)\b", admin_clean)
                        or re.match(r"^לא\b", admin_clean)
                    )
                    admin_without_neg = re.sub(r"\b(?:לא|איננו|אין|אי)\s+(?:מתאים|פנוי|יכול|אפשרי|טוב|בסדר|נוח|אפשר)\b", " ", admin_clean)
                    is_admin_affirmative = any(sig in admin_without_neg for sig in ["כן", "מאשר", "מתאים", "סבבה", "תקבע", "קבענו", "בסדר", "מעולה", "אפשר", "פנוי"])

                    # CASE 1: Admin proposes a new/alternative hour (e.g. "14:00 לא מתאים ואפשר ב 16:00" or customer had no hour and Admin says "מסך עולה 400₪ אוכל להזמין ותבוא לתקן בשעה 16:00")
                    is_proposing_new_hour = (adm_hr is not None) and (has_negation or req_hr is None or (adm_hr, adm_mn) != (req_hr, req_mn))

                    if is_proposing_new_hour:
                        disp_time, s_iso, e_iso = parse_scheduling_datetime(req_text, override_text=admin_answer)
                        proposed_hm = f"{adm_hr:02d}:{adm_mn or 0:02d}"
                        name_str = f" {target_cust_name}" if (target_cust_name and target_cust_name not in COMMON_NON_NAMES) else ""
                        extra_line = f"{extra_info_str}.\n" if extra_info_str else ""
                        has_order_offer_in_extra = any(w in (extra_info_str or "") for w in ["להזמין", "נזמין"])

                        if req_hr is not None and (req_hr, req_mn) != (adm_hr, adm_mn):
                            old_hm = f"{req_hr:02d}:{req_mn or 0:02d}"
                            closing_ask = (
                                f"האם תרצה שנזמין עבורך את החלק ונקבע לשעה {proposed_hm}? 😃"
                                if has_order_offer_in_extra
                                else f"האם השעה {proposed_hm} מתאימה לך? 😃"
                            )
                            cust_reply_msg = (
                                f"שלום{name_str}, חזרתי אליך בנוגע לפנייתך:\n"
                                f"{extra_line}"
                                f"השעה {old_hm} אינה פנויה, אך אפשר לקבוע לך {appt_meta['short_label']} ל{disp_time}.\n"
                                f"{closing_ask}"
                            )
                        else:
                            closing_ask = (
                                f"האם תרצה שנזמין עבורך את החלק ונקבע לשעה {proposed_hm}? 😃"
                                if has_order_offer_in_extra
                                else f"האם השעה {proposed_hm} מתאימה לך? 😃"
                            )
                            cust_reply_msg = (
                                f"שלום{name_str}, חזרתי אליך בנוגע לפנייתך:\n"
                                f"{extra_line}"
                                f"אפשר לקבוע לך {appt_meta['short_label']} ל{disp_time}.\n"
                                f"{closing_ask}"
                            )

                        send_whatsapp_message(target_cust_phone, cust_reply_msg)
                        save_chat_message(target_cust_phone, "agent", cust_reply_msg)

                        # Keep request active awaiting customer confirmation of the proposed hour (16:00) AND store any quoted price!
                        updated_req_text = re.sub(r"\s*\[(?:PROPOSED_TIME|PRICE):[^\]]*\]", "", req_text).strip()
                        updated_req_text = f"{updated_req_text} [PROPOSED_TIME: בשעה {proposed_hm}]"
                        if adm_price_nis:
                            updated_req_text = f"{updated_req_text} [PRICE:{adm_price_nis}]"
                        action_summary = f"הוצע ללקוח מועד: {disp_time}"
                        if extra_info_str:
                            action_summary += f" | פרטים ומחיר: {extra_info_str}"
                        if adm_price_nis:
                            action_summary += f" [PRICE:{adm_price_nis}]"
                        conn.execute(
                            "UPDATE customer_requests SET status='awaiting_customer_time', request_text=?, action_taken=? WHERE id=?",
                            (updated_req_text, action_summary, target_pending[0])
                        )

                        price_note = f" (כולל מחיר: {adm_price_nis} ₪)" if adm_price_nis else ""
                        confirm_msg = (
                            f"✅ עדכנתי את הלקוח ({target_cust_name or callback_phone}) לגבי כלל הפרטים{price_note} ושהשעה {proposed_hm} פנויה ({disp_time}), וביקשתי את אישורו!\n"
                            f"📞 טלפון לחזרה: {callback_phone}\n"
                            f"📅 אשלח לך את הקישור להוספה ליומן גוגל ברגע שהלקוח יאשר."
                        )
                        send_whatsapp_message(sender_phone, confirm_msg, raw_chat_id)
                        conn.commit()
                        conn.close()
                        return {"ok": True, "admin_action": "alternative_time_proposed", "customer": target_cust_phone, "proposed_time": disp_time, "price": adm_price_nis}

                    # CASE 2: Admin approves the requested hour (and an explicit hour exists)
                    elif not has_negation and is_admin_affirmative and (req_hr is not None or adm_hr is not None):
                        disp_time, s_iso, e_iso = parse_scheduling_datetime(req_text, override_text=admin_answer)
                        name_str = f" {target_cust_name}" if (target_cust_name and target_cust_name not in COMMON_NON_NAMES) else ""
                        extra_line = f"{extra_info_str}.\n" if extra_info_str else ""
                        if appt_meta["is_remote"]:
                            cust_reply_msg = (
                                f"שלום{name_str}, חזרתי אליך בנוגע לפנייתך:\n"
                                f"{extra_line}"
                                f"מועד ההתקנה אושר בהצלחה! קבענו ל{disp_time}.\n"
                                f"ניצור איתך קשר במספר {callback_phone} להתחברות והתקנה מרחוק במחשב. 😃"
                            )
                        else:
                            cust_reply_msg = (
                                f"שלום{name_str}, חזרתי אליך בנוגע לפנייתך:\n"
                                f"{extra_line}"
                                f"התור שלך אושר בהצלחה! קבענו {appt_meta['short_label']} ל{disp_time} {appt_meta['venue_phrase']}.\n"
                                f"מספר הטלפון לחזרה אליך: {callback_phone}. נשמח לראותך! 😃"
                            )
                        send_whatsapp_message(target_cust_phone, cust_reply_msg)
                        save_chat_message(target_cust_phone, "agent", cust_reply_msg)

                        conn.execute(
                            "UPDATE customer_requests SET status='handled', action_taken=? WHERE id=?",
                            (f"נקבע ואושר ל{disp_time}", target_pending[0])
                        )
                        try:
                            conn.execute(
                                "INSERT INTO installations_schedule (phone, customer_name, callback_phone, details, scheduled_time, status, created_at) "
                                "VALUES (?, ?, ?, ?, ?, ?, ?)",
                                (target_cust_phone, target_cust_name, callback_phone, req_text, disp_time, "confirmed", datetime.now().isoformat())
                            )
                        except Exception:
                            pass

                        cal_details = (
                            f"לקוח: {target_cust_name or 'לקוח'}\n"
                            f"טלפון לחזרה: {callback_phone}\n"
                            f"מועד: {disp_time}\n"
                            f"שירות: {appt_meta['type_label']}\n"
                            f"⏰ תזכורת מוגדרת: רבע שעה (15 דקות) לפני הפגישה"
                        )
                        gcal_url = generate_google_calendar_link(
                            title=f"{appt_meta['cal_title_prefix']} - {target_cust_name or callback_phone} ({callback_phone}) (נעם שיח)",
                            start_iso=s_iso,
                            end_iso=e_iso,
                            details=cal_details,
                            location=appt_meta["location"]
                        )
                        confirm_msg = (
                            f"✅ המועד אושר מול הלקוח ({target_cust_name or callback_phone}) ל{disp_time}!\n"
                            f"📞 טלפון לחזרה: {callback_phone}\n\n"
                            f"⏰ תזכורת: רבע שעה (15 דקות) לפני הפגישה.\n"
                            f"📅 לחץ כאן להוספת תזכורת ביומן גוגל בלחיצה אחת:\n{gcal_url}"
                        )
                        send_whatsapp_message(sender_phone, confirm_msg, raw_chat_id)
                        conn.commit()
                        conn.close()
                        return {"ok": True, "admin_action": "appointment_confirmed", "customer": target_cust_phone, "callback_phone": callback_phone, "gcal_url": gcal_url}

                    # CASE 3: Admin said 'כן' when no hour was specified yet by either side
                    elif not has_negation and is_admin_affirmative and req_hr is None and adm_hr is None:
                        disp_day, _, _ = parse_scheduling_datetime(req_text)
                        name_str = f" {target_cust_name}" if (target_cust_name and target_cust_name not in COMMON_NON_NAMES) else ""
                        cust_reply_msg = (
                            f"שלום{name_str}, חזרתי אליך בנוגע לפנייתך:\n"
                            f"בשמחה! ניתן לקבוע לך {appt_meta['short_label']} ל{disp_day}.\n"
                            f"באיזו שעה יהיה לך הכי נוח להגיע (בשעות הפעילות 12:00-20:00)? 😃"
                        )
                        send_whatsapp_message(target_cust_phone, cust_reply_msg)
                        save_chat_message(target_cust_phone, "agent", cust_reply_msg)
                        send_whatsapp_message(sender_phone, f"✅ שאלתי את הלקוח ({target_cust_name or callback_phone}) באיזו שעה נוח לו להגיע ב{disp_day}. אעדכן אותך כשיענה!", raw_chat_id)
                        conn.commit()
                        conn.close()
                        return {"ok": True, "admin_action": "asked_customer_for_hour", "customer": target_cust_phone}

                    # CASE 4: Admin rejected without specifying a new hour (e.g. "מחר עמוס, רק ביום שני")
                    else:
                        name_str = f" {target_cust_name}" if (target_cust_name and target_cust_name not in COMMON_NON_NAMES) else ""
                        adapted_case4, _ = adapt_admin_answer(admin_answer, req_text, recent_cust_text)
                        adapted_case4_clean = re.sub(r"\s*(?:איזה\s+יום\s+ושעה[^?]*\?|האם\s+זה\s+מתאים\s+לך\?)\s*😃?\s*$", "", adapted_case4).rstrip(".!, ")
                        cust_reply_msg = f"שלום{name_str}, חזרתי אליך בנוגע לפנייתך:\n{adapted_case4_clean}. איזה יום ושעה יתאימו לך? 😃"
                        send_whatsapp_message(target_cust_phone, cust_reply_msg)
                        save_chat_message(target_cust_phone, "agent", cust_reply_msg)
                        send_whatsapp_message(sender_phone, f"✅ העברתי ללקוח ({target_cust_name or callback_phone}) את הודעתך בשפה ישירה וממתין שייבחר מועד חלופי.", raw_chat_id)
                        conn.commit()
                        conn.close()
                        return {"ok": True, "admin_action": "alternative_day_requested", "customer": target_cust_phone}
                else:
                    adm_price = extract_price_nis(adapted_admin_ans) or extract_price_nis(admin_answer)
                    # Check if customer had ALREADY agreed to order and was just waiting for Eran's exact price
                    prev_action = conn.execute("SELECT action_taken FROM customer_requests WHERE id=?", (target_pending[0],)).fetchone()
                    prev_action_str = (prev_action[0] if prev_action else "") or ""
                    kosher_tracks_adm = extract_kosher_device_track_prices(f"{req_text} {adapted_admin_ans} {prev_action_str}", recent_cust_text)
                    if adm_price and "ממתין למחיר מערן לשליחת ביט" in prev_action_str:
                        name_str = f" {target_cust_name}" if (target_cust_name and target_cust_name not in COMMON_NON_NAMES and target_msg_count <= 1) else ""
                        cust_reply_msg = (
                            f"שלום{name_str}, חזרתי אליך בנוגע לפנייתך:\n"
                            f"המחיר המדויק להזמנת החלק הוא *{adm_price} ₪*. 🛠️\n"
                            f"כדי שנזמין עבורך את החלק מיד, ניתן להעביר כעת *{adm_price} ₪* בביט (Bit) למספר:\n"
                            f"📱 *{BIT_PAYMENT_PHONE}* (ערן נקר - נעם שיח)\n\n"
                            f"לאחר ההעברה, שלח לנו כאן עדכון או צילום מסך ונדאג להזמין לך את החלק באופן מיידי! 😃"
                        )
                        conn.execute(
                            "UPDATE customer_requests SET status='awaiting_bit_payment', action_taken=? WHERE id=?",
                            (f"נשלחו פרטי תשלום בביט ({adm_price} ₪ ל-{BIT_PAYMENT_PHONE})", target_pending[0])
                        )
                        send_whatsapp_message(target_cust_phone, cust_reply_msg)
                        save_chat_message(target_cust_phone, "agent", cust_reply_msg)
                    else:
                        # Persist any learned item prices permanently!
                        conn.commit()
                        m_t_items = re.findall(r"\[TARGET_ITEM:([^\]]+)\]", req_text) or re.findall(r"\[TARGET_ITEM:([^\]]+)\]", prev_action_str)
                        spec_target_opt = (
                            (m_t_items[-1].strip() if m_t_items else "")
                            or detect_specific_option_name(extract_latest_customer_question(req_text))
                            or detect_specific_option_name(admin_answer)
                        )
                        for _opt_pair in extract_options_and_prices_from_text(adapted_admin_ans):
                            if _opt_pair.get("name") and _opt_pair.get("price"):
                                save_learned_item_price(_opt_pair["name"], _opt_pair["price"])
                        if spec_target_opt and adm_price and len(extract_options_and_prices_from_text(adapted_admin_ans)) < 2:
                            save_learned_item_price(spec_target_opt, adm_price)

                        # Also persist multi-track prices (גלות / ימות המשיח / גאולה) or single product price into pos_inventory!
                        adm_multi_tr = extract_multi_track_prices_from_text(f"{admin_answer} {adapted_admin_ans}")
                        latest_cust_q_for_pos = extract_latest_customer_question(req_text)
                        pos_q_tokens = _normalize_pos_tokens(latest_cust_q_for_pos, strip_stopwords=True)
                        pos_prod_label = " ".join(pos_q_tokens) if pos_q_tokens else ""
                        if pos_prod_label and not is_scheduling_request(req_text):
                            if any(adm_multi_tr.values()):
                                save_learned_pos_product_prices(
                                    pos_prod_label,
                                    single_price=adm_multi_tr.get("galut") or adm_multi_tr.get("yemot") or (int(adm_price) if adm_price else None),
                                    galut_price=adm_multi_tr.get("galut"),
                                    yemot_price=adm_multi_tr.get("yemot"),
                                    geula_price=adm_multi_tr.get("geula"),
                                )
                            elif adm_price and not is_temp_stock_msg and len(extract_options_and_prices_from_text(adapted_admin_ans)) < 2:
                                save_learned_pos_product_prices(pos_prod_label, single_price=int(adm_price))

                        prev_meta_tags = " ".join(re.findall(r"\[(?:LAST_QUOTED_ITEM|LAST_QUOTED_PRICE|TARGET_ITEM|PRICE|GALUT_PRICE|YEMOT_PRICE|GEULA_PRICE):[^\]]+\]", prev_action_str))
                        cust_reply_msg = format_admin_answer_for_customer(target_cust_phone, admin_answer, f"{req_text} {prev_meta_tags}".strip(), target_cust_name, target_msg_count, recent_cust_text)
                        action_with_price = adapted_admin_ans
                        extracted_adm_opts = extract_options_and_prices_from_text(adapted_admin_ans)
                        prev_opts = extract_options_and_prices_from_text(prev_action_str + "\n" + recent_cust_text)
                        # Merge prev_opts and extracted_adm_opts so newly learned prices enrich the existing options list!
                        opts_by_name = {o["name"]: o for o in prev_opts}
                        for o in extracted_adm_opts:
                            if o["name"] not in opts_by_name or o.get("price"):
                                opts_by_name[o["name"]] = o
                        if spec_target_opt and adm_price:
                            opts_by_name[spec_target_opt] = {"name": spec_target_opt, "price": adm_price, "keywords": [spec_target_opt]}
                        merged_adm_opts = list(opts_by_name.values())
                        if merged_adm_opts:
                            action_with_price += f" [OPTIONS_JSON:{json.dumps(merged_adm_opts, ensure_ascii=False)}]"
                        # Preserve previous LAST_QUOTED_ITEM tags so multi-turn price comparisons work seamlessly
                        prev_lq_tags = " ".join(re.findall(r"\[LAST_QUOTED_ITEM:[^\]]+\]\s*\[LAST_QUOTED_PRICE:\d{2,4}\]", prev_action_str))
                        if prev_lq_tags:
                            action_with_price += f" {prev_lq_tags}"
                        if spec_target_opt and adm_price and len(extracted_adm_opts) < 2:
                            action_with_price += f" [LAST_QUOTED_ITEM:{spec_target_opt}] [LAST_QUOTED_PRICE:{adm_price}]"
                        if kosher_tracks_adm.get("matched"):
                            action_with_price += f" [GALUT_PRICE:{kosher_tracks_adm['galut_price']}] [YEMOT_PRICE:{kosher_tracks_adm['yemot_price']}]"
                            if kosher_tracks_adm.get("geula_price"):
                                action_with_price += f" [GEULA_PRICE:{kosher_tracks_adm['geula_price']}]"
                        elif adm_price and len(extracted_adm_opts) < 2:
                            action_with_price += f" [PRICE:{adm_price}]"
                        elif not adm_price and not merged_adm_opts:
                            m_prev_p = re.search(r"\[PRICE:(\d{2,4})\]", prev_action_str)
                            if m_prev_p:
                                action_with_price += f" [PRICE:{m_prev_p.group(1)}]"
                        if is_admin_ans_in_prog or is_in_progress_or_question(cust_reply_msg):
                            conn.execute(
                                "UPDATE customer_requests SET status='awaiting_customer_reply', action_taken=? WHERE id=?",
                                (action_with_price, target_pending[0])
                            )
                        else:
                            conn.execute(
                                "UPDATE customer_requests SET status='handled', action_taken=? WHERE id=?",
                                ("נענה על ידי מנהל", target_pending[0])
                            )
                        send_whatsapp_message(target_cust_phone, cust_reply_msg)
                        save_chat_message(target_cust_phone, "agent", cust_reply_msg)
                
                # Start 35s timer for satisfaction closing check ONLY if not an in-progress question/step
                if ("האם הצלחתי לעזור לך ולתת לך מענה לפנייתך" in cust_reply_msg or "האם אוכל לעזור לך במשהו נוסף" in cust_reply_msg) and not is_in_progress_or_question(cust_reply_msg):
                    ts = std_time.time()
                    PENDING_SATISFACTION_CHECKS[target_cust_phone] = ts
                    asyncio.create_task(inactivity_closing_timer(target_cust_phone, ts, "", target_cust_name))
                
                customer_dest = f"{target_cust_phone} (#{target_pending[0]})"
            conn.commit()
            conn.close()
            if is_admin_ans_in_prog:
                confirm_msg = f"✅ ההודעה נוסחה בשפה ישירה ונשלחה ללקוח ({customer_dest}). השיחה נשארה פתוחה להמתנה לתשובת הלקוח!"
            else:
                confirm_msg = f"✅ התשובה נשלחה ללקוח ({customer_dest})!"
            send_whatsapp_message(sender_phone, confirm_msg, raw_chat_id)
            return {"ok": True, "admin_action": "admin_reply_sent", "customer": customer_dest, "in_progress": is_admin_ans_in_prog}
        except Exception as exc:
            print(f"[Admin Learning Error]: {exc}")
            send_whatsapp_message(sender_phone, f"⚠️ שגיאה בשמירת התשובה: {exc}", raw_chat_id)
            return {"ok": False, "error": str(exc)}

    customer_name = get_contact_name(sender_phone)
    extracted_name = extract_name_from_text(message_text)

    # Permanent contacts are immutable - Eran is ALWAYS Eran and can never be overwritten
    if normalize_phone(sender_phone) in PERMANENT_CONTACTS:
        customer_name = PERMANENT_CONTACTS[normalize_phone(sender_phone)].split()[0]
    elif extracted_name:
        if not customer_name or any(sig in message_text for sig in ["שמי", "קוראים לי", "השם שלי"]):
            customer_name = extracted_name
            save_contact_name(sender_phone, extracted_name)

    recent_history = get_recent_chat_history(sender_phone, limit=6)
    already_greeted = has_already_greeted_customer(sender_phone) or ("[סוכן]:" in recent_history)
    store_status = get_store_status_now()
    msg_count = get_conversation_message_count(sender_phone)

    # Cancel any pending inactivity timer as customer has sent a message
    if sender_phone in PENDING_SATISFACTION_CHECKS:
        PENDING_SATISFACTION_CHECKS[sender_phone] = None

    # 0.5 CHECK IF CUSTOMER HAS AN ACTIVE SCHEDULING REQUEST (awaiting_customer_time OR pending)
    try:
        conn = sqlite3.connect(DB_PATH)
        active_sched_row = conn.execute(
            "SELECT id, request_text, status, action_taken FROM customer_requests WHERE (phone = ? OR phone LIKE ?) AND status IN ('awaiting_customer_time', 'pending') ORDER BY id DESC LIMIT 1",
            (sender_phone, f"%{sender_phone[-9:]}%")
        ).fetchone()
        conn.close()
    except Exception:
        active_sched_row = None

    if active_sched_row and is_scheduling_request(active_sched_row[1] or ""):
        sched_req_id, sched_req_text, sched_req_status, sched_action_taken = active_sched_row
        appt_meta = get_appointment_meta(sched_req_text, recent_history)
        cust_clean = message_text.strip().lower()
        cust_has_neg = bool(re.search(r"\b(?:לא|אי\s+אפשר|תפוס|עמוס)\b", cust_clean))
        cust_hr, cust_mn = extract_explicit_hour_minute(message_text)
        cb_detected = detect_callback_phone_in_text(message_text, sender_phone)

        # Extract any saved price from sched_req_text or sched_action_taken
        m_sched_pr = re.search(r"\[PRICE:(\d{2,4})\]", (sched_req_text or "") + " " + (sched_action_taken or ""))
        saved_sched_price = m_sched_pr.group(1) if m_sched_pr else ""
        has_order_in_sched = any(w in (sched_action_taken or "") for w in ["להזמין", "נזמין"])

        # (A) If status is 'awaiting_customer_time' (Admin proposed an hour like 16:00 and we asked customer if it suits them)
        if sched_req_status == "awaiting_customer_time":
            proposed_hr, proposed_mn = extract_explicit_hour_minute(sched_req_text)
            is_asking_price_now = any(q in cust_clean for q in ["כמה זה עולה", "כמה עולה", "מה המחיר", "מה העלות", "כמה זה"])
            if is_asking_price_now and saved_sched_price:
                proposed_hm_str = f"{proposed_hr:02d}:{proposed_mn or 0:02d}" if proposed_hr is not None else "16:00"
                reply_pr = (
                    f"המחיר שערן עדכן עבורך הוא *{saved_sched_price} ₪*. 🛠️\n"
                    f"האם תרצה שנקבע לך את התור לשעה {proposed_hm_str} ונזמין עבורך את החלק? 😃"
                )
                send_whatsapp_message(sender_phone, reply_pr, raw_chat_id)
                save_chat_message(sender_phone, "customer", message_text)
                save_chat_message(sender_phone, "agent", reply_pr)
                return {"ok": True, "reply": reply_pr, "type": "answered_saved_admin_price", "price": saved_sched_price}

            is_cust_confirming_time = (
                not cust_has_neg and not is_asking_price_now and (
                    is_satisfaction_yes(message_text)
                    or any(w in cust_clean for w in ["כן", "מתאים", "סבבה", "מעולה", "בסדר", "אחלה", "מצוין", "בטח", "ודאי", "סגור", "קבענו", "נקבע", "תזמין", "להזמין"])
                    or (cust_hr is not None and (cust_hr, cust_mn) == (proposed_hr, proposed_mn))
                )
            )
            if is_cust_confirming_time:
                disp_time, s_iso, e_iso = parse_scheduling_datetime(sched_req_text)
                callback_phone = cb_detected or format_phone_display(sender_phone)
                bit_block = ""
                new_status_after_confirm = "handled"
                if saved_sched_price and has_order_in_sched:
                    bit_block = (
                        f"\n\n💳 *תשלום להזמנת החלק:* אנא העבר כעת *{saved_sched_price} ₪* בביט (Bit) למספר *{BIT_PAYMENT_PHONE}* (ערן נקר - נעם שיח) ושלח לנו כאן עדכון לאחר ההעברה."
                    )
                    new_status_after_confirm = "awaiting_bit_payment"
                elif saved_sched_price:
                    bit_block = f"\n💰 עלות הטיפול שנקבעה: *{saved_sched_price} ₪*."

                if appt_meta["is_remote"]:
                    reply_final = (
                        f"מעולה! מועד ההתקנה נקבע סופית ל{disp_time}.\n"
                        f"ניצור איתך קשר במספר {callback_phone} להתחברות והתקנה מרחוק במחשב.{bit_block} 😃"
                    )
                else:
                    reply_final = (
                        f"מעולה! קבענו סופית {appt_meta['short_label']} ל{disp_time} {appt_meta['venue_phrase']}.\n"
                        f"מספר הטלפון לחזרה אליך: {callback_phone}.{bit_block} נשמח לראותך! 😃"
                    )
                send_whatsapp_message(sender_phone, reply_final, raw_chat_id)
                save_chat_message(sender_phone, "customer", message_text)
                save_chat_message(sender_phone, "agent", reply_final)

                try:
                    conn = sqlite3.connect(DB_PATH)
                    action_done_str = f"אושר סופית ע״י לקוח ל{disp_time}" + (f" ({saved_sched_price} ₪)" if saved_sched_price else "")
                    conn.execute("UPDATE customer_requests SET status=?, action_taken=? WHERE id=?", (new_status_after_confirm, action_done_str, sched_req_id))
                    conn.execute(
                        "INSERT INTO installations_schedule (phone, customer_name, callback_phone, details, scheduled_time, status, created_at) "
                        "VALUES (?, ?, ?, ?, ?, ?, ?)",
                        (sender_phone, customer_name, callback_phone, sched_req_text, disp_time, "confirmed", datetime.now().isoformat())
                    )
                    conn.commit()
                    conn.close()
                except Exception:
                    pass

                clean_req_for_cal = re.sub(r"\s*\[(?:PROPOSED_TIME|PRICE):[^\]]*\]", "", sched_req_text).strip()
                cal_details = (
                    f"לקוח: {customer_name or 'לקוח'}\n"
                    f"טלפון לחזרה: {callback_phone}\n"
                    f"מועד: {disp_time}\n"
                    f"שירות: {appt_meta['type_label']}\n"
                    + (f"מחיר שסוכם: {saved_sched_price} ₪\n" if saved_sched_price else "")
                    + f"פרטים: {clean_req_for_cal}\n"
                    f"⏰ תזכורת מוגדרת: רבע שעה (15 דקות) לפני הפגישה"
                )
                gcal_url = generate_google_calendar_link(
                    title=f"{appt_meta['cal_title_prefix']} - {customer_name or callback_phone} ({callback_phone}) (נעם שיח)",
                    start_iso=s_iso,
                    end_iso=e_iso,
                    details=cal_details,
                    location=appt_meta["location"]
                )
                order_alert_line = f"🛠️ *נא להזמין עבורו את החלק! (נשלחו ללקוח פרטי העברה בביט על סך {saved_sched_price} ₪ ל-{BIT_PAYMENT_PHONE})*\n" if (saved_sched_price and has_order_in_sched) else ""
                target_admins = [adm for adm in admin_numbers_set if adm != sender_phone and adm != "972500000000"]
                for adm in target_admins:
                    send_whatsapp_message(
                        adm,
                        f"✅ *הלקוח ({customer_name or callback_phone}) אישר סופית את המועד ל{disp_time}!*\n"
                        f"{order_alert_line}"
                        f"📞 טלפון לחזרה: {callback_phone}\n\n"
                        f"⏰ תזכורת: רבע שעה (15 דקות) לפני הפגישה.\n"
                        f"📅 לחץ כאן להוספת תזכורת ביומן גוגל בלחיצה אחת:\n{gcal_url}"
                    )
                return {"ok": True, "reply": reply_final, "type": "customer_confirmed_proposed_time", "scheduled_time": disp_time, "gcal_url": gcal_url}

        # (B) If customer is providing a preferred hour for a pending scheduling request (where no hour was set or customer suggests another hour)
        if cust_hr is not None and not is_scheduling_request(message_text):
            base_req_clean = re.sub(r"\s*\[PROPOSED_TIME:[^\]]*\]", "", sched_req_text).strip()
            updated_req_text = f"{base_req_clean} בשעה {cust_hr:02d}:{cust_mn or 0:02d}"
            disp_time, _, _ = parse_scheduling_datetime(updated_req_text)
            callback_phone = cb_detected or format_phone_display(sender_phone)
            try:
                conn = sqlite3.connect(DB_PATH)
                conn.execute("UPDATE customer_requests SET status='pending', request_text=?, action_taken=? WHERE id=?", (updated_req_text, f"לקוח ביקש שעה {disp_time}", sched_req_id))
                conn.close()
            except Exception:
                pass
            reply_hr = (
                f"תודה! רשמתי לפניי את הבקשה ל{disp_time} (טלפון לחזרה: {callback_phone}).\n"
                f"אני בודק כעת מול ערן אם השעה פנויה ביומן וכבר מעדכן אותך! 😃"
            )
            send_whatsapp_message(sender_phone, reply_hr, raw_chat_id)
            save_chat_message(sender_phone, "customer", message_text)
            save_chat_message(sender_phone, "agent", reply_hr)

            target_admins = [adm for adm in admin_numbers_set if adm != sender_phone and adm != "972500000000"]
            for adm in target_admins:
                send_whatsapp_message(
                    adm,
                    f"🕒 *עדכון שעה מלקוח* [#REQ-{sched_req_id}] ({customer_name or callback_phone}):\n"
                    f"הלקוח מבקש לקבוע {appt_meta['type_label']} ל*{disp_time}* (טלפון לחזרה: {callback_phone}).\n"
                    f"האם המועד מתאים לך? (השב 'כן' לאישור ביומן, או ציין שעה חלופית)"
                )
            return {"ok": True, "reply": reply_hr, "type": "customer_provided_hour", "scheduled_time": disp_time}

        # (C) If customer is confirming/providing their callback phone while request is pending
        if cb_detected and not is_scheduling_request(message_text):
            reply_cb = (
                f"מצוין, רשמתי לפניי! 📞\n"
                f"נחזור אליך למספר {cb_detected} במועד שייקבע לאחר אישור של ערן. 😃"
            )
            send_whatsapp_message(sender_phone, reply_cb, raw_chat_id)
            save_chat_message(sender_phone, "customer", message_text)
            save_chat_message(sender_phone, "agent", reply_cb)

            target_admins = [adm for adm in admin_numbers_set if adm != sender_phone and adm != "972500000000"]
            for adm in target_admins:
                send_whatsapp_message(
                    adm,
                    f"📞 *עדכון טלפון לחזרה* [#REQ-{sched_req_id}]:\n"
                    f"הלקוח ({customer_name or sender_phone}) אישר מספר נוח לחזרה: *{cb_detected}*"
                )
            return {"ok": True, "reply": reply_cb, "type": "callback_phone_confirmed", "callback_phone": cb_detected}



    # =========================================================================
    # 0.54 KOSHERPLAY & NETSPARK FILTERING SECURITY, OTP & RENEWAL FLOW
    # =========================================================================
    # Check if customer has an active filtering state in `customer_requests`
    active_filter_req = None
    try:
        _conn_flt = sqlite3.connect(DB_PATH)
        active_filter_req = _conn_flt.execute(
            """
            SELECT id, system_name, request_text, action_taken, status
            FROM customer_requests
            WHERE phone = ?
              AND status IN (
                  'awaiting_filter_system_and_name',
                  'awaiting_filter_otp',
                  'awaiting_admin_filter_verification',
                  'awaiting_filter_renewal_payment'
              )
            ORDER BY id DESC LIMIT 1
            """,
            (sender_phone,),
        ).fetchone()
        _conn_flt.close()
    except Exception as _e_flt:
        print(f"[Filtering State Check Error]: {_e_flt}")

    flt_det = detect_filtering_service_request(message_text)

    # Helper to execute or route a verified, active subscriber's request
    def _process_verified_filtering_request(req_id_val: int, sub_rec: dict, req_text_val: str):
        sys_nm = sub_rec.get("system_name") or "כשר פליי"
        exp_dt = sub_rec.get("service_expiry_date") or ""
        cust_nm = sub_rec.get("customer_name") or customer_name or "לקוח"

        # Rule C: Check if the annual free-service period has expired!
        if FilteringBillingAdapter.is_subscription_expired(exp_dt):
            ren_offer = FilteringBillingAdapter.build_renewal_message_for_customer(sys_nm, exp_dt, sender_phone)
            upsert_filtering_subscriber(
                sender_phone,
                payment_status="expired_pending_renewal",
                renewal_price_nis=ren_offer["price_nis"],
                last_request_text=req_text_val,
            )
            conn_e = sqlite3.connect(DB_PATH)
            conn_e.execute(
                "UPDATE customer_requests SET status='awaiting_filter_renewal_payment', system_name=?, request_text=?, action_taken=? WHERE id=?",
                (
                    sys_nm,
                    req_text_val,
                    f"תוקף שירות חינם פג ב-{exp_dt} — נשלחה דרישת חידוש שנתי ({ren_offer['price_nis']} ₪)",
                    req_id_val,
                ),
            )
            conn_e.commit()
            conn_e.close()

            send_whatsapp_message(sender_phone, ren_offer["customer_message"], raw_chat_id)
            save_chat_message(sender_phone, "customer", message_text)
            save_chat_message(sender_phone, "agent", ren_offer["customer_message"])

            # Notify Admin that an expired subscriber requested service and was prompted to renew
            exp_fmt = FilteringBillingAdapter.format_date_il(exp_dt)
            adm_ren_alert = (
                f"📅 *התראת חידוש מנוי סינון שנתי ({sys_nm})* [#REQ-{req_id_val}]\n"
                f"👤 *לקוח:* {cust_nm} (`{_format_local_il_phone(sender_phone)}`)\n"
                f"💬 *בקשת הלקוח:* \"{req_text_val}\"\n"
                f"⏰ *תום שנת השירות ללא עלות:* {exp_fmt}\n"
                f"💳 *מחיר חידוש שנתי שנשלח ללקוח (מטבלת המחירים):* *{ren_offer['price_nis']} ₪*\n\n"
                f"💡 *ברגע שהלקוח מסדיר תשלום, השב להודעה זו `שולם` (או `חידש`) והסוכן יאריך לו אוטומטית לשנה נוספת ויבצע את הבקשה!*"
            )
            for adm in [a for a in admin_numbers_set if a != sender_phone and a != "972500000000"]:
                send_whatsapp_message(adm, adm_ren_alert)
            return {
                "ok": True,
                "reply": ren_offer["customer_message"],
                "type": "filtering_subscription_expired_renewal_sent",
                "system": sys_nm,
                "expiry_date": exp_dt,
                "renewal_price": ren_offer["price_nis"],
            }

        # Active & Adult-Approved subscriber!
        exp_fmt = FilteringBillingAdapter.format_date_il(exp_dt)
        crm_link = KOSHERPLAY_CRM_MODULES_URL_TEMPLATE.format(
            query=urllib.parse.quote(_format_local_il_phone(sender_phone).replace("-", ""))
        )
        conn_ok = sqlite3.connect(DB_PATH)
        conn_ok.execute(
            "UPDATE customer_requests SET status='pending', system_name=?, request_text=?, action_taken=? WHERE id=?",
            (
                sys_nm,
                req_text_val,
                f"מנוי מאומת ומאושר (בתוקף עד {exp_dt}) — בביצוע מול מערכת {sys_nm}",
                req_id_val,
            ),
        )
        conn_ok.commit()
        conn_ok.close()

        cust_reply = (
            f"זיהיתי את המנוי המאושר שלך ב*{sys_nm}* (זכאות לשירות שנתי בתוקף עד *{exp_fmt}*). 🛡️✅\n"
            f"אני מעדכן כעת במערכת ההגנה את בקשתך: *\"{req_text_val}\"* ומיד אעדכן אותך כאן ברגע שהשינוי הושלם!"
        )
        send_whatsapp_message(sender_phone, cust_reply, raw_chat_id)
        save_chat_message(sender_phone, "customer", message_text)
        save_chat_message(sender_phone, "agent", cust_reply)

        adm_exec_alert = (
            f"🛡️ *בקשת שירות סינון מלקוח מאומת ומאושר ({sys_nm})* [#REQ-{req_id_val}]\n"
            f"👤 *לקוח:* {cust_nm} (`{_format_local_il_phone(sender_phone)}`) — מבוגר מאושר ✅\n"
            f"📅 *תוקף שירות ללא עלות:* עד {exp_fmt}\n"
            f"💬 *בקשת הפתיחה/סגירה:* \"{req_text_val}\"\n"
            + (f"🔗 *קישור מהיר לכרטיס בכשר פליי:* {crm_link}\n\n" if "כשר" in sys_nm else "\n")
            + "💡 *לאחר הלחיצה בחלון ניהול ההגנה, השב כאן (למשל: `בוצע, תרענן הגנה במכשיר`) והסוכן יעדכן את הלקוח מיד!*"
        )
        for adm in [a for a in admin_numbers_set if a != sender_phone and a != "972500000000"]:
            send_whatsapp_message(adm, adm_exec_alert)

        return {
            "ok": True,
            "reply": cust_reply,
            "type": "filtering_verified_active_request_dispatched",
            "system": sys_nm,
            "expiry_date": exp_dt,
        }

    # -------------------------------------------------------------------------
    # CASE 1: Customer is replying to an active filtering workflow state
    # -------------------------------------------------------------------------
    if active_filter_req:
        f_req_id, f_sys, f_orig_req_text, f_action_taken, f_status = active_filter_req
        sub_rec = get_filtering_subscriber(sender_phone)

        # STATE 1A: Customer was asked 'איזו הגנה יש לך ומה השם שמופיע בה?'
        if f_status == "awaiting_filter_system_and_name":
            parsed_info = parse_customer_protection_system_and_name_reply(message_text)
            sys_chosen = parsed_info["system_name"] or (f_sys if f_sys in ("כשר פליי", "נטספרק") else "")
            name_chosen = parsed_info["subscriber_name"] or customer_name or ""

            if not sys_chosen:
                ask_again = (
                    "כדי שאוכל לאתר את המנוי שלך במערכת, אנא ציין איזו הגנה מותקנת אצלך במכשיר "
                    "(*כשר פליי* או *נטספרק*) ומה *השם המלא* שמופיע במנוי? 🛡️"
                )
                send_whatsapp_message(sender_phone, ask_again, raw_chat_id)
                save_chat_message(sender_phone, "customer", message_text)
                save_chat_message(sender_phone, "agent", ask_again)
                return {"ok": True, "reply": ask_again, "type": "clarify_filter_system_and_name"}

            # Try searching KosherPlay / NetSpark by the name they provided
            if name_chosen:
                lk_by_name = (
                    search_kosherplay_subscriber(name_chosen)
                    if sys_chosen == "כשר פליי"
                    else search_netspark_subscriber(name_chosen)
                )
                if lk_by_name.get("found"):
                    sub_rec = lk_by_name.get("subscriber_record") or sub_rec

            if name_chosen and not customer_name:
                customer_name = name_chosen
                save_contact_name(sender_phone, name_chosen)

            sub_rec = upsert_filtering_subscriber(
                sender_phone,
                customer_name=name_chosen or sub_rec.get("customer_name") or "",
                system_name=sys_chosen,
                last_request_text=f_orig_req_text,
            )

            # Now move to Rule A: Send 6-digit OTP verification code to the phone!
            otp_code = generate_and_send_filtering_otp(sender_phone, raw_chat_id, system_name=sys_chosen)
            conn_u = sqlite3.connect(DB_PATH)
            conn_u.execute(
                "UPDATE customer_requests SET status='awaiting_filter_otp', system_name=?, action_taken=? WHERE id=?",
                (sys_chosen, f"נרשם מנוי {sys_chosen} ({name_chosen}) ונשלח קוד אימות OTP ({otp_code})", f_req_id),
            )
            conn_u.commit()
            conn_u.close()
            save_chat_message(sender_phone, "customer", message_text)
            return {
                "ok": True,
                "reply": f"נשלח קוד אימות למספר {_format_local_il_phone(sender_phone)}",
                "type": "filtering_otp_sent_after_system_identification",
                "system": sys_chosen,
                "otp_code": otp_code,
            }

        # STATE 1B: Customer is entering the 6-digit OTP verification code ('awaiting_filter_otp')
        if f_status == "awaiting_filter_otp":
            # Check if customer asked to resend code
            if any(w in message_text for w in ["שלח שוב", "לא קיבלתי", "קוד חדש"]):
                otp_code = generate_and_send_filtering_otp(sender_phone, raw_chat_id, system_name=sub_rec.get("system_name") or f_sys or "כשר פליי")
                save_chat_message(sender_phone, "customer", message_text)
                return {"ok": True, "type": "filtering_otp_resent", "otp_code": otp_code}

            m_code = re.search(r"\b(\d{6})\b", message_text.strip())
            entered_code = m_code.group(1) if m_code else ""
            expected_code = str(sub_rec.get("otp_code") or "").strip()
            exp_ts = int(sub_rec.get("otp_expires_at") or 0)

            if not entered_code or entered_code != expected_code:
                # If customer sent a brand new filtering instruction while awaiting OTP, remind them of the OTP
                err_otp = (
                    "קוד האימות שהוקש אינו תואם. 🔐\n"
                    "אנא הקש את *קוד האימות בן 6 הספרות* שנשלח אליך בהודעה הקודמת (או כתוב *\"קוד חדש\"* לשליחה חוזרת)."
                )
                send_whatsapp_message(sender_phone, err_otp, raw_chat_id)
                save_chat_message(sender_phone, "customer", message_text)
                save_chat_message(sender_phone, "agent", err_otp)
                return {"ok": True, "reply": err_otp, "type": "filtering_otp_invalid"}

            if exp_ts and int(std_time.time()) > exp_ts:
                otp_code = generate_and_send_filtering_otp(sender_phone, raw_chat_id, system_name=sub_rec.get("system_name") or f_sys or "כשר פליי")
                save_chat_message(sender_phone, "customer", message_text)
                return {"ok": True, "type": "filtering_otp_expired_resent", "otp_code": otp_code}

            # OTP Verified! Mark `otp_verified = 1`
            sub_rec = upsert_filtering_subscriber(
                sender_phone,
                otp_verified=1,
                otp_verified_at=datetime.now().isoformat(),
            )
            sys_nm = sub_rec.get("system_name") or f_sys or "כשר פליי"
            cust_nm = sub_rec.get("customer_name") or customer_name or "לקוח"

            # Check Rule B & Rule C: Is customer already approved as an adult by Eran with a saved `service_expiry_date`?
            if int(sub_rec.get("adult_approved_by_admin") or 0) == -1:
                reject_msg = f"שלום, על פי הגדרות המנוי ב*{sys_nm}*, לא ניתן לבצע שינויים בהגדרות הסינון ממספר זה."
                send_whatsapp_message(sender_phone, reject_msg, raw_chat_id)
                save_chat_message(sender_phone, "customer", message_text)
                save_chat_message(sender_phone, "agent", reject_msg)
                return {"ok": True, "reply": reject_msg, "type": "filtering_unauthorized_subscriber"}

            if int(sub_rec.get("adult_approved_by_admin") or 0) == 1 and sub_rec.get("service_expiry_date"):
                # Already approved in the past! Proceed directly to expiry check & fulfillment
                return _process_verified_filtering_request(f_req_id, sub_rec, f_orig_req_text)

            # First time ever! Escalate to Eran for ONE-TIME Adult + Free-Service Expiry Date check
            conn_u = sqlite3.connect(DB_PATH)
            conn_u.execute(
                "UPDATE customer_requests SET status='awaiting_admin_filter_verification', system_name=?, action_taken=? WHERE id=?",
                (sys_nm, "אומת בקוד OTP — ממתין לאישור חד-פעמי מערן (מבוגר + תאריך תום שנת שירות חינם)", f_req_id),
            )
            conn_u.commit()
            conn_u.close()

            wait_admin_msg = (
                f"✅ *תודה! מספר הטלפון שלך אומת בהצלחה.*\n"
                f"מאחר שזו פנייתך הראשונה למערכת השירות האוטומטית של *{sys_nm}*, אני מבצע כעת אימות זכאות חד-פעמי מול ערן (שיישמר בזיכרון הקבוע להמשך) ומיד חוזר אליך לביצוע הבקשה! 🛡️"
            )
            send_whatsapp_message(sender_phone, wait_admin_msg, raw_chat_id)
            save_chat_message(sender_phone, "customer", message_text)
            save_chat_message(sender_phone, "agent", wait_admin_msg)

            crm_link = KOSHERPLAY_CRM_MODULES_URL_TEMPLATE.format(
                query=urllib.parse.quote(_format_local_il_phone(sender_phone).replace("-", ""))
            )
            admin_verify_prompt = (
                f"🛡️ *אימות חד-פעמי למנוי סינון ({sys_nm})* [#REQ-{f_req_id}]\n"
                f"👤 *לקוח:* {cust_nm} (`{_format_local_il_phone(sender_phone)}`) — *אומת כעת בקוד אימות (OTP)* ✅\n"
                f"💬 *בקשת הלקוח:* \"{f_orig_req_text}\"\n"
                + (f"🔗 *חיפוש בכשר פליי:* {crm_link}\n\n" if "כשר" in sys_nm else "\n")
                + "אשמח לאישורך החד-פעמי (יישמר בזיכרון הקבוע ולא אשאל שוב בעתיד):\n"
                + "1️⃣ האם הלקוח *מבוגר ומורשה* לבצע שינויים במנוי שלו?\n"
                + "2️⃣ *עד איזה תאריך* מגיע לו שירות ללא עלות (מתי מסתיימת השנה שלו)?\n\n"
                + "💡 *למענה מהיר כתוב למשל:*\n"
                + "• `מאושר עד 15/11/2027` (או `מאושר לשנה`)\n"
                + "• `מאושר אבל פג תוקף` (אם השנה שלו כבר הסתיימה וצריך לחדש בתשלום)\n"
                + "• `לא מאושר - ילד` (אם אינו מורשה)"
            )
            for adm in [a for a in admin_numbers_set if a != sender_phone and a != "972500000000"]:
                send_whatsapp_message(adm, admin_verify_prompt)

            return {
                "ok": True,
                "reply": wait_admin_msg,
                "type": "filtering_otp_verified_awaiting_onetime_admin_check",
                "system": sys_nm,
            }

        # STATE 1C: Customer is awaiting renewal payment confirmation ('awaiting_filter_renewal_payment')
        if f_status == "awaiting_filter_renewal_payment":
            t_low_ren = message_text.lower()
            if any(w in t_low_ren for w in ["שילמתי", "העברתי", "שלחתי ביט", "שולם", "תחדש לי", "כן תחדש"]):
                wait_pay_msg = (
                    "תודה על העדכון! 🙏 העברתי כעת לערן לאישור קבלת התשלום. "
                    "מיד עם אישורו, המנוי שלך יתעדכן אוטומטית לשנה נוספת ונבצע את בקשתך! 😃"
                )
                send_whatsapp_message(sender_phone, wait_pay_msg, raw_chat_id)
                save_chat_message(sender_phone, "customer", message_text)
                save_chat_message(sender_phone, "agent", wait_pay_msg)

                sys_nm = sub_rec.get("system_name") or f_sys or "כשר פליי"
                ren_price = sub_rec.get("renewal_price_nis") or FilteringBillingAdapter.get_annual_renewal_price_from_pos(sys_nm)["price_nis"]
                adm_pay_alert = (
                    f"💳 *לקוח מדווח שהעביר תשלום לחידוש שנתי ({sys_nm})* [#REQ-{f_req_id}]\n"
                    f"👤 *לקוח:* {sub_rec.get('customer_name') or customer_name or 'לקוח'} (`{_format_local_il_phone(sender_phone)}`)\n"
                    f"💬 *הודעת הלקוח:* \"{message_text}\"\n"
                    f"💰 *סכום חידוש שנתי:* {ren_price} ₪\n\n"
                    f"💡 *השב `שולם` (או `חידש`) כדי להאריך את המנוי לשנה נוספת בזיכרון הקבוע ולבצע את בקשתו!*"
                )
                for adm in [a for a in admin_numbers_set if a != sender_phone and a != "972500000000"]:
                    send_whatsapp_message(adm, adm_pay_alert)
                return {"ok": True, "reply": wait_pay_msg, "type": "filtering_customer_reported_renewal_payment"}

    # -------------------------------------------------------------------------
    # CASE 2: New Filtering Service Request ('תפתח לי', 'תסגור לי', 'תחסום לי', 'תשחרר לי'...)
    # -------------------------------------------------------------------------
    if flt_det.get("matched"):
        req_clean_txt = flt_det["request_text"]

        # Rule A1: Strictly block modifying someone else's subscription or another phone number!
        mentioned_ph = flt_det.get("mentioned_phone") or ""
        if flt_det.get("mentions_other_person") or (mentioned_ph and mentioned_ph != sender_phone):
            target_for_otp = mentioned_ph if (mentioned_ph and mentioned_ph != sender_phone) else ""
            own_only_msg = (
                "🔒 *נוהל אבטחת מנויים (נעם שיח):*\n"
                "שינויים בהגדרות הסינון (פתיחה, סגירה או שחרור) מתבצעים אך ורק עבור בעל המנוי המבוגר ועל המספר שלו בלבד.\n"
                + (
                    f"כדי לבצע שינוי במנוי של `{_format_local_il_phone(target_for_otp)}`, יש לפנות אלינו ישירות מהמספר `{_format_local_il_phone(target_for_otp)}` עצמו או לאמת את הקוד שיישלח אליו."
                    if target_for_otp
                    else "לא ניתן לבצע שינויים במנוי של אדם אחר או של ילד ללא אימות בעל המנוי המורשה."
                )
            )
            send_whatsapp_message(sender_phone, own_only_msg, raw_chat_id)
            save_chat_message(sender_phone, "customer", message_text)
            save_chat_message(sender_phone, "agent", own_only_msg)
            return {
                "ok": True,
                "reply": own_only_msg,
                "type": "filtering_blocked_other_person_subscription",
            }

        # Step 0: Lookup customer protection system (1. KosherPlay -> 2. NetSpark -> 3. Ask Customer)
        sub_rec = get_filtering_subscriber(sender_phone)
        if not sub_rec or not sub_rec.get("system_name"):
            lk_sys = lookup_customer_protection_system(sender_phone, customer_name)
            if lk_sys.get("found"):
                sub_rec = lk_sys.get("subscriber_record") or upsert_filtering_subscriber(
                    sender_phone,
                    customer_name=lk_sys.get("customer_name") or customer_name or "",
                    system_name=lk_sys.get("system"),
                    crm_client_id=lk_sys.get("crm_client_id") or "",
                    current_level=lk_sys.get("current_level") or "",
                )
            elif flt_det.get("system_hint"):
                # Customer explicitly named their system in the message (e.g. 'תפתח לי וייז בכשר פליי')
                sub_rec = upsert_filtering_subscriber(
                    sender_phone,
                    customer_name=customer_name or "",
                    system_name=flt_det["system_hint"],
                    last_request_text=req_clean_txt,
                )

        # If not found in KosherPlay or NetSpark (and not specified), ask the customer!
        if not sub_rec or not sub_rec.get("system_name"):
            conn_new = sqlite3.connect(DB_PATH)
            cur_new = conn_new.cursor()
            cur_new.execute(
                "INSERT INTO customer_requests (phone, system_name, request_text, action_taken, upsell_offer, status, created_at) "
                "VALUES (?, ?, ?, ?, ?, ?, ?)",
                (
                    sender_phone,
                    "בירור מערכת הגנה",
                    req_clean_txt,
                    "לא נמצא בכשר פליי או בנטספרק — נשאל איזו הגנה יש לו ומה השם שמופיע בה",
                    "",
                    "awaiting_filter_system_and_name",
                    datetime.now().isoformat(),
                ),
            )
            conn_new.commit()
            conn_new.close()

            ask_sys_msg = (
                "חיפשתי את המספר שלך במערכות *כשר פליי* ו*נטספרק* ולא איתרתי מנוי משויך למספר זה. 🔍\n"
                "כדי שאוכל לבדוק ולטפל בבקשתך, *איזו הגנה קיימת לך היום במכשיר* (כשר פליי או נטספרק), ומה *השם המלא* שמופיע במנוי? 🛡️"
            )
            send_whatsapp_message(sender_phone, ask_sys_msg, raw_chat_id)
            save_chat_message(sender_phone, "customer", message_text)
            save_chat_message(sender_phone, "agent", ask_sys_msg)
            return {
                "ok": True,
                "reply": ask_sys_msg,
                "type": "asked_customer_protection_system_and_name",
            }

        sys_nm = sub_rec.get("system_name")
        upsert_filtering_subscriber(sender_phone, last_request_text=req_clean_txt)

        # Check if Eran previously marked this subscriber as unauthorized / child (-1)
        if int(sub_rec.get("adult_approved_by_admin") or 0) == -1:
            reject_msg = f"שלום, על פי הגדרות המנוי ב*{sys_nm}*, לא ניתן לבצע שינויים בהגדרות הסינון ממספר זה."
            send_whatsapp_message(sender_phone, reject_msg, raw_chat_id)
            save_chat_message(sender_phone, "customer", message_text)
            save_chat_message(sender_phone, "agent", reject_msg)
            return {"ok": True, "reply": reject_msg, "type": "filtering_unauthorized_subscriber"}

        # Create request record
        conn_f_new = sqlite3.connect(DB_PATH)
        cur_f_new = conn_f_new.cursor()
        cur_f_new.execute(
            "INSERT INTO customer_requests (phone, system_name, request_text, action_taken, upsell_offer, status, created_at) "
            "VALUES (?, ?, ?, ?, ?, ?, ?)",
            (
                sender_phone,
                sys_nm,
                req_clean_txt,
                f"זוהתה הגנת {sys_nm}",
                "",
                "awaiting_filter_otp",
                datetime.now().isoformat(),
            ),
        )
        new_f_req_id = cur_f_new.lastrowid
        conn_f_new.commit()
        conn_f_new.close()

        # Rule A2: If phone ownership OTP has not been verified yet, send 6-digit OTP first!
        if int(sub_rec.get("otp_verified") or 0) != 1:
            otp_code = generate_and_send_filtering_otp(sender_phone, raw_chat_id, system_name=sys_nm)
            conn_u = sqlite3.connect(DB_PATH)
            conn_u.execute(
                "UPDATE customer_requests SET status='awaiting_filter_otp', action_taken=? WHERE id=?",
                (f"נשלח קוד אימות OTP ({otp_code}) למנוי {sys_nm}", new_f_req_id),
            )
            conn_u.commit()
            conn_u.close()
            save_chat_message(sender_phone, "customer", message_text)
            return {
                "ok": True,
                "reply": f"נשלח קוד אימות למספר {_format_local_il_phone(sender_phone)}",
                "type": "filtering_otp_sent",
                "system": sys_nm,
                "otp_code": otp_code,
            }

        # Rule B & C: If OTP was already verified, check if one-time Admin Adult & Expiry approval is saved!
        if int(sub_rec.get("adult_approved_by_admin") or 0) == 1 and sub_rec.get("service_expiry_date"):
            return _process_verified_filtering_request(new_f_req_id, sub_rec, req_clean_txt)

        # Otherwise ask Admin for one-time Adult + Free-Service Expiry Date approval
        conn_u = sqlite3.connect(DB_PATH)
        conn_u.execute(
            "UPDATE customer_requests SET status='awaiting_admin_filter_verification', action_taken=? WHERE id=?",
            ("אומת ב-OTP — ממתין לאישור חד-פעמי מערן (מבוגר + תאריך תום שנת שירות חינם)", new_f_req_id),
        )
        conn_u.commit()
        conn_u.close()

        wait_admin_msg = (
            f"זיהיתי את המנוי שלך ב*{sys_nm}*. 🛡️\n"
            f"מאחר שזו פנייתך הראשונה למערכת השירות האוטומטית, אני מבצע כעת אימות זכאות חד-פעמי מול ערן (שיישמר בזיכרון הקבוע להמשך) ומיד חוזר אליך לביצוע הבקשה!"
        )
        send_whatsapp_message(sender_phone, wait_admin_msg, raw_chat_id)
        save_chat_message(sender_phone, "customer", message_text)
        save_chat_message(sender_phone, "agent", wait_admin_msg)

        cust_nm = sub_rec.get("customer_name") or customer_name or "לקוח"
        crm_link = KOSHERPLAY_CRM_MODULES_URL_TEMPLATE.format(
            query=urllib.parse.quote(_format_local_il_phone(sender_phone).replace("-", ""))
        )
        admin_verify_prompt = (
            f"🛡️ *אימות חד-פעמי למנוי סינון ({sys_nm})* [#REQ-{new_f_req_id}]\n"
            f"👤 *לקוח:* {cust_nm} (`{_format_local_il_phone(sender_phone)}`) — *מאומת ב-OTP* ✅\n"
            f"💬 *בקשת הלקוח:* \"{req_clean_txt}\"\n"
            + (f"🔗 *חיפוש בכשר פליי:* {crm_link}\n\n" if "כשר" in sys_nm else "\n")
            + "אשמח לאישורך החד-פעמי (יישמר בזיכרון הקבוע ולא אשאל שוב בעתיד):\n"
            + "1️⃣ האם הלקוח *מבוגר ומורשה* לבצע שינויים במנוי שלו?\n"
            + "2️⃣ *עד איזה תאריך* מגיע לו שירות ללא עלות (מתי מסתיימת השנה שלו)?\n\n"
            + "💡 *למענה מהיר כתוב למשל:*\n"
            + "• `מאושר עד 15/11/2027` (או `מאושר לשנה`)\n"
            + "• `מאושר אבל פג תוקף` (אם השנה שלו כבר הסתיימה וצריך לחדש בתשלום)\n"
            + "• `לא מאושר - ילד` (אם אינו מורשה)"
        )
        for adm in [a for a in admin_numbers_set if a != sender_phone and a != "972500000000"]:
            send_whatsapp_message(adm, admin_verify_prompt)

        return {
            "ok": True,
            "reply": wait_admin_msg,
            "type": "filtering_awaiting_onetime_admin_check",
            "system": sys_nm,
        }


    # 0.58 TIBER.CO.IL CELLULAR RECEPTION, ANTENNAS & PACKAGE PORTING FLOW (CONCISE STEP-BY-STEP FUNNEL)
    # States:
    # - 'awaiting_cellular_address': Customer was asked for their address
    # - 'awaiting_cellular_device_type': Customer received concise antenna summary and was asked: Regular or Kosher device?
    # - 'awaiting_cellular_regular_filter': Customer chose Regular device and was asked: Cheapest price, Fastest 5G browsing, or See all offers?
    # - 'awaiting_cellular_plan_selection': Customer received filtered packages and can ask to expand OR choose a package for porting callback
    # - 'awaiting_cellular_callback_info': Customer wants callback and is providing chosen package / name / phone
    try:
        conn = sqlite3.connect(DB_PATH)
        active_cell_row = conn.execute(
            "SELECT id, request_text, action_taken, status FROM customer_requests "
            "WHERE (phone = ? OR phone LIKE ?) AND status IN ("
            "'awaiting_net_troubleshoot_info', 'awaiting_net_troubleshoot_step1', 'awaiting_net_troubleshoot_step2', "
            "'awaiting_cellular_address', 'awaiting_cellular_device_type', "
            "'awaiting_cellular_regular_filter', 'awaiting_cellular_plan_selection', 'awaiting_cellular_callback_info'"
            ") ORDER BY id DESC LIMIT 1",
            (sender_phone, f"%{sender_phone[-9:]}%")
        ).fetchone()
        conn.close()
    except Exception:
        active_cell_row = None

    if active_cell_row and not is_scheduling_request(message_text):
        cell_req_id, cell_req_text, cell_action_taken, cell_status = active_cell_row
        cust_clean_cell = auto_fix_common_hebrew_typos(message_text.strip().lower())
        cust_phone_fmt = format_phone_display(sender_phone)
        cust_has_neg_cell = bool(re.search(r"\b(?:לא\s+תודה|לא\s+צריך|לא\s+רוצה|לא\s+מעוניין|מוותר|אסתדר|עזוב)\b", cust_clean_cell)) and not any(
            ts_w in cust_clean_cell for ts_w in ["לא עזר", "לא עובד", "לא הסתדר", "לא פתר", "עדיין"]
        )

        # Allow customer to exit cleanly if they decline
        if cust_has_neg_cell:
            try:
                conn = sqlite3.connect(DB_PATH)
                conn.execute("UPDATE customer_requests SET status='handled', action_taken=? WHERE id=?", (f"הלקוח סיים את בדיקת הסלולר: {message_text}", cell_req_id))
                conn.commit()
                conn.close()
            except Exception:
                pass
            reply_cell_no = "בסדר גמור, בשמחה! אני כאן לכל שאלה נוספת. 😃"
            send_whatsapp_message(sender_phone, reply_cell_no, raw_chat_id)
            save_chat_message(sender_phone, "customer", message_text)
            save_chat_message(sender_phone, "agent", reply_cell_no)
            return {"ok": True, "reply": reply_cell_no, "type": "cellular_flow_declined"}

        # If customer switches to an unrelated store question (e.g. F21/F22/Q8 price or store hours), close cellular state and let normal handler answer
        if any(k in cust_clean_cell for k in ["כמה עולה f21", "כמה עולה f22", "כמה עולה q8", "שעות פעילות"]):
            try:
                conn = sqlite3.connect(DB_PATH)
                conn.execute("UPDATE customer_requests SET status='handled' WHERE id=?", (cell_req_id,))
                conn.commit()
                conn.close()
            except Exception:
                pass
            active_cell_row = None

    if active_cell_row and not is_scheduling_request(message_text):
        cell_req_id, cell_req_text, cell_action_taken, cell_status = active_cell_row
        cust_clean_cell = auto_fix_common_hebrew_typos(message_text.strip().lower())
        cust_phone_fmt = format_phone_display(sender_phone)

        m_saved_addr = re.search(r"\[TIBER_ADDR:([^\]]+)\]", cell_action_taken or "")
        saved_addr = m_saved_addr.group(1).strip() if m_saved_addr else "לא צוינה"
        m_saved_net = re.search(r"\[TIBER_TOP_NET:([^\]]+)\]", cell_action_taken or "")
        saved_top_net = m_saved_net.group(1).strip() if m_saved_net else ""
        m_saved_dev = re.search(r"\[DEVICE_TYPE:([^\]]+)\]", cell_action_taken or "")
        saved_dev_type = m_saved_dev.group(1).strip() if m_saved_dev else ""

        m_ts_issue = re.search(r"\[TS_ISSUE:([^\]]*)\]", cell_action_taken or "")
        saved_ts_issue = m_ts_issue.group(1).strip() if m_ts_issue else ""
        m_ts_dev_name = re.search(r"\[TS_DEV_NAME:([^\]]*)\]", cell_action_taken or "")
        saved_ts_dev_name = m_ts_dev_name.group(1).strip() if m_ts_dev_name else ""
        m_ts_dev_fam = re.search(r"\[TS_DEV_FAM:([^\]]*)\]", cell_action_taken or "")
        saved_ts_dev_fam = m_ts_dev_fam.group(1).strip() if m_ts_dev_fam else ""

        # STAGE T0: Customer was asked for exact problem + device model ('awaiting_net_troubleshoot_info')
        if cell_status == "awaiting_net_troubleshoot_info":
            ts_ext = extract_troubleshoot_issue_and_device(message_text)
            merged_issue = ts_ext["issue_category"] or saved_ts_issue or "both"
            merged_dev_name = ts_ext["device_name"] or saved_ts_dev_name
            merged_dev_fam = ts_ext["device_family"] or saved_ts_dev_fam or ("kosher" if detect_cellular_device_type_choice(message_text) == "kosher" else "android")
            also_addr = extract_israeli_address_from_text(message_text) or (saved_addr if saved_addr != "לא צוינה" else "")

            # If customer explicitly asked to skip troubleshooting and check carrier/packages
            if detect_troubleshoot_outcome(message_text) == "skip_to_porting":
                cell_status = "awaiting_cellular_address"
            else:
                reply_s1 = build_troubleshoot_step1_reply(merged_issue, merged_dev_name, merged_dev_fam)
                dev_type_tag = "kosher" if merged_dev_fam == "kosher" else ("regular" if merged_dev_fam in ("iphone", "android") else "")
                new_action_s1 = (
                    f"שלב 1 בבדיקת מכשיר ({merged_dev_name or 'מכשיר הלקוח'}) "
                    f"[TS_ISSUE:{merged_issue}] [TS_DEV_NAME:{merged_dev_name}] [TS_DEV_FAM:{merged_dev_fam}]"
                    + (f" [DEVICE_TYPE:{dev_type_tag}]" if dev_type_tag else "")
                    + (f" [TIBER_ADDR:{also_addr}]" if also_addr else "")
                )
                try:
                    conn = sqlite3.connect(DB_PATH)
                    conn.execute(
                        "UPDATE customer_requests SET status='awaiting_net_troubleshoot_step1', request_text=?, action_taken=? WHERE id=?",
                        (f"{cell_req_text} | {message_text}", new_action_s1, cell_req_id)
                    )
                    conn.commit()
                    conn.close()
                except Exception:
                    pass
                send_whatsapp_message(sender_phone, reply_s1, raw_chat_id)
                save_chat_message(sender_phone, "customer", message_text)
                save_chat_message(sender_phone, "agent", reply_s1)
                return {
                    "ok": True,
                    "reply": reply_s1,
                    "type": "net_troubleshoot_step1",
                    "issue_category": merged_issue,
                    "device_name": merged_dev_name,
                    "escalated": False,
                }

        # STAGE T1: Customer is responding to Step 1 of device troubleshooting ('awaiting_net_troubleshoot_step1')
        if cell_status == "awaiting_net_troubleshoot_step1":
            outcome_s1 = detect_troubleshoot_outcome(message_text)
            ts_ext = extract_troubleshoot_issue_and_device(message_text)
            merged_issue = saved_ts_issue or ts_ext["issue_category"] or "both"
            merged_dev_name = saved_ts_dev_name or ts_ext["device_name"]
            merged_dev_fam = saved_ts_dev_fam or ts_ext["device_family"] or "android"
            also_addr = extract_israeli_address_from_text(message_text) or (saved_addr if saved_addr != "לא צוינה" else "")

            if outcome_s1 == "solved":
                reply_solved = (
                    "איזה כיף לשמוע שהבעיה הסתדרה! 🙌📱 שמחתי מאוד לעזור.\n"
                    "אנחנו כאן לכל שאלה נוספת — ואם תרצה בהזדמנות גם לבדוק הוזלה של חבילת הסלולר שלך, רק תכתוב לי! 😃"
                )
                try:
                    conn = sqlite3.connect(DB_PATH)
                    conn.execute(
                        "UPDATE customer_requests SET status='handled', action_taken=? WHERE id=?",
                        (f"התקלה במכשיר נפתרה בשלב 1: {message_text}", cell_req_id)
                    )
                    conn.commit()
                    conn.close()
                except Exception:
                    pass
                send_whatsapp_message(sender_phone, reply_solved, raw_chat_id)
                save_chat_message(sender_phone, "customer", message_text)
                save_chat_message(sender_phone, "agent", reply_solved)
                return {"ok": True, "reply": reply_solved, "type": "net_troubleshoot_solved_step1", "escalated": False}

            # Otherwise advance to Step 2 of device troubleshooting!
            reply_s2 = build_troubleshoot_step2_reply(merged_issue, merged_dev_name, merged_dev_fam)
            dev_type_tag = "kosher" if merged_dev_fam == "kosher" else ("regular" if merged_dev_fam in ("iphone", "android") else "")
            new_action_s2 = (
                f"שלב 2 בבדיקת מכשיר ({merged_dev_name or 'מכשיר הלקוח'}) "
                f"[TS_ISSUE:{merged_issue}] [TS_DEV_NAME:{merged_dev_name}] [TS_DEV_FAM:{merged_dev_fam}]"
                + (f" [DEVICE_TYPE:{dev_type_tag}]" if dev_type_tag else "")
                + (f" [TIBER_ADDR:{also_addr}]" if also_addr else "")
            )
            try:
                conn = sqlite3.connect(DB_PATH)
                conn.execute(
                    "UPDATE customer_requests SET status='awaiting_net_troubleshoot_step2', request_text=?, action_taken=? WHERE id=?",
                    (f"{cell_req_text} | {message_text}", new_action_s2, cell_req_id)
                )
                conn.commit()
                conn.close()
            except Exception:
                pass
            send_whatsapp_message(sender_phone, reply_s2, raw_chat_id)
            save_chat_message(sender_phone, "customer", message_text)
            save_chat_message(sender_phone, "agent", reply_s2)
            return {
                "ok": True,
                "reply": reply_s2,
                "type": "net_troubleshoot_step2",
                "issue_category": merged_issue,
                "device_name": merged_dev_name,
                "escalated": False,
            }

        # STAGE T2: Customer is responding to Step 2 of device troubleshooting ('awaiting_net_troubleshoot_step2')
        if cell_status == "awaiting_net_troubleshoot_step2":
            outcome_s2 = detect_troubleshoot_outcome(message_text)
            also_addr = extract_israeli_address_from_text(message_text) or (saved_addr if saved_addr != "לא צוינה" else "")

            if outcome_s2 == "solved":
                reply_solved2 = (
                    "מעולה! שמח מאוד לשמוע שהפעולות פתרו את הבעיה והכל עובד כשורה! 🙌📱\n"
                    "אני כאן בשבילך לכל שאלה נוספת. 😃"
                )
                try:
                    conn = sqlite3.connect(DB_PATH)
                    conn.execute(
                        "UPDATE customer_requests SET status='handled', action_taken=? WHERE id=?",
                        (f"התקלה במכשיר נפתרה בשלב 2: {message_text}", cell_req_id)
                    )
                    conn.commit()
                    conn.close()
                except Exception:
                    pass
                send_whatsapp_message(sender_phone, reply_solved2, raw_chat_id)
                save_chat_message(sender_phone, "customer", message_text)
                save_chat_message(sender_phone, "agent", reply_solved2)
                return {"ok": True, "reply": reply_solved2, "type": "net_troubleshoot_solved_step2", "escalated": False}

            # All device settings were checked and appear OK, but the issue persists!
            # Recommend considering switching cellular carrier by checking antenna coverage at their address via Tiber.co.il!
            if also_addr:
                tiber_res_ts = lookup_tiber_antennas_and_packages(also_addr, mode="summary_ask_device_type", device_type=saved_dev_type)
                top_n_ts = tiber_res_ts["top_network"]
                reply_recommend_switch = (
                    f"מאחר שעברנו יחד על כל ההגדרות במכשיר והכל מופיע תקין, נראה שהבעיה נובעת מכיסוי אנטנות חלש של חברת הסלולר הנוכחית באזורך — "
                    f"ובמצב כזה מומלץ לשקול החלפת חברת סלולר לרשת החזקה ביותר בכתובת שלך! 📡\n\n"
                    f"{tiber_res_ts['reply']}"
                )
                try:
                    conn = sqlite3.connect(DB_PATH)
                    conn.execute(
                        "UPDATE customer_requests SET status='awaiting_cellular_device_type', request_text=?, action_taken=? WHERE id=?",
                        (
                            f"{cell_req_text} | כתובת: {also_addr}",
                            f"הגדרות מכשיר תקינות - בוצעה בדיקת Tiber.co.il לכתובת '{also_addr}' [TIBER_ADDR:{also_addr}] [TIBER_TOP_NET:{top_n_ts['network']} ({top_n_ts['antennas_count']} אנטנות, כ-{top_n_ts['nearest_m']} מטר)]"
                            + (f" [DEVICE_TYPE:{saved_dev_type}]" if saved_dev_type else ""),
                            cell_req_id,
                        )
                    )
                    conn.commit()
                    conn.close()
                except Exception:
                    pass
                send_whatsapp_message(sender_phone, reply_recommend_switch, raw_chat_id)
                save_chat_message(sender_phone, "customer", message_text)
                save_chat_message(sender_phone, "agent", reply_recommend_switch)
                return {
                    "ok": True,
                    "reply": reply_recommend_switch,
                    "type": "troubleshoot_done_tiber_summary",
                    "address": also_addr,
                    "top_network": top_n_ts,
                    "escalated": False,
                }
            else:
                reply_ask_addr_after_ts = (
                    "מאחר שעברנו על כל ההגדרות במכשיר והכל מופיע תקין, סביר מאוד שהבעיה נובעת מכיסוי אנטנות חלש של חברת הסלולר הנוכחית באזור שלך. 📡\n"
                    "במצב כזה אני ממליץ לשקול החלפת חברת סלולר לרשת עם האנטנות הכי קרובות וחזקות אליך!\n\n"
                    "כדי שאבדוק עבורך כעת באתר *Tiber.co.il* איזו חברה נותנת את הקליטה הכי טובה אצלך — *מה הכתובת שלך (עיר, רחוב ומספר בית)?* 📍📶"
                )
                try:
                    conn = sqlite3.connect(DB_PATH)
                    conn.execute(
                        "UPDATE customer_requests SET status='awaiting_cellular_address', request_text=?, action_taken=? WHERE id=?",
                        (
                            f"{cell_req_text} | {message_text}",
                            f"הגדרות המכשיר תקינות - הומלץ לבדוק החלפת חברה ב-Tiber.co.il ונשאלה כתובת הלקוח"
                            + (f" [DEVICE_TYPE:{saved_dev_type}]" if saved_dev_type else ""),
                            cell_req_id,
                        )
                    )
                    conn.commit()
                    conn.close()
                except Exception:
                    pass
                send_whatsapp_message(sender_phone, reply_ask_addr_after_ts, raw_chat_id)
                save_chat_message(sender_phone, "customer", message_text)
                save_chat_message(sender_phone, "agent", reply_ask_addr_after_ts)
                return {
                    "ok": True,
                    "reply": reply_ask_addr_after_ts,
                    "type": "troubleshoot_done_recommend_carrier_switch_ask_address",
                    "escalated": False,
                }

        # STAGE A: Customer was asked for their address ('awaiting_cellular_address')
        if cell_status == "awaiting_cellular_address":
            addr_cand = extract_israeli_address_from_text(message_text) or message_text.strip()
            dev_choice_in_msg = detect_cellular_device_type_choice(message_text)
            reg_filter_in_msg = detect_cellular_regular_filter_choice(message_text)

            if dev_choice_in_msg == "kosher":
                init_mode = "kosher"
                next_status = "awaiting_cellular_plan_selection"
                resp_type = "tiber_kosher_packages"
            elif dev_choice_in_msg == "regular" and reg_filter_in_msg == "cheapest":
                init_mode = "regular_cheapest"
                next_status = "awaiting_cellular_plan_selection"
                resp_type = "tiber_regular_cheapest_packages"
            elif dev_choice_in_msg == "regular" and reg_filter_in_msg == "fastest":
                init_mode = "regular_fastest"
                next_status = "awaiting_cellular_plan_selection"
                resp_type = "tiber_regular_fastest_packages"
            elif reg_filter_in_msg == "all":
                init_mode = "all"
                next_status = "awaiting_cellular_plan_selection"
                resp_type = "tiber_antenna_and_packages_results"
            else:
                init_mode = "summary_ask_device_type"
                next_status = "awaiting_cellular_device_type"
                resp_type = "tiber_summary_asked_device_type"

            tiber_res = lookup_tiber_antennas_and_packages(addr_cand, mode=init_mode, device_type=dev_choice_in_msg)
            reply_tiber = tiber_res["reply"]
            top_net_name = tiber_res["top_network"]["network"]
            top_net_dist = tiber_res["top_network"]["nearest_m"]
            top_net_cnt = tiber_res["top_network"]["antennas_count"]

            try:
                conn = sqlite3.connect(DB_PATH)
                conn.execute(
                    "UPDATE customer_requests SET status=?, request_text=?, action_taken=? WHERE id=?",
                    (
                        next_status,
                        f"{cell_req_text} | כתובת: {addr_cand}",
                        f"בוצעה בדיקת Tiber.co.il לכתובת '{addr_cand}' [TIBER_ADDR:{addr_cand}] [TIBER_TOP_NET:{top_net_name} ({top_net_cnt} אנטנות, כ-{top_net_dist} מטר)]"
                        + (f" [DEVICE_TYPE:{dev_choice_in_msg}]" if dev_choice_in_msg else ""),
                        cell_req_id,
                    )
                )
                conn.commit()
                conn.close()
            except Exception:
                pass

            send_whatsapp_message(sender_phone, reply_tiber, raw_chat_id)
            save_chat_message(sender_phone, "customer", message_text)
            save_chat_message(sender_phone, "agent", reply_tiber)
            return {
                "ok": True,
                "reply": reply_tiber,
                "type": resp_type,
                "address": addr_cand,
                "top_network": tiber_res["top_network"],
                "networks": tiber_res["networks"],
                "escalated": False,
            }

        # Check if customer at any post-address stage asks to EXPAND ("תפרט", "תרחיב", "כל ההצעות", "לראות את כל ההצעות")
        # or if they directly select a specific carrier/package to port to!
        pkg_det_any = detect_selected_cellular_package_from_text(message_text)
        has_callback_intent = any(w in cust_clean_cell for w in [
            "תחזרו", "תחזור", "לחזור", "תתקשר", "להתקשר", "לנייד", "ניוד", "להתנייד",
            "קוראים לי", "שמי", "מעוניין בחבילה", "רוצה להתנייד"
        ]) or bool(detect_callback_phone_in_text(message_text, ""))

        # PRE-CHECK FOR NEW ADDRESS AT ANY POST-ADDRESS STAGE:
        # If the customer/admin sends a NEW Israeli address while in awaiting_cellular_device_type,
        # awaiting_cellular_regular_filter, awaiting_cellular_plan_selection, or awaiting_cellular_callback_info,
        # immediately run a fresh Tiber lookup for the new address instead of staying locked on the previous address!
        if cell_status in ("awaiting_cellular_device_type", "awaiting_cellular_regular_filter", "awaiting_cellular_plan_selection", "awaiting_cellular_callback_info"):
            new_addr_override = extract_israeli_address_from_text(message_text)
            if (
                new_addr_override
                and not detect_cellular_device_type_choice(message_text)
                and not is_cellular_expand_request(message_text)
                and not pkg_det_any.get("matched")
                and not any(w in cust_clean_cell for w in ["קוראים לי", "שמי", "תחזור", "תחזרו", "להתנייד", "לנייד"])
            ):
                tiber_override = lookup_tiber_antennas_and_packages(new_addr_override, mode="summary_ask_device_type")
                top_no = tiber_override["top_network"]
                try:
                    conn = sqlite3.connect(DB_PATH)
                    conn.execute(
                        "UPDATE customer_requests SET status='awaiting_cellular_device_type', request_text=?, action_taken=? WHERE id=?",
                        (
                            f"{cell_req_text} | כתובת: {new_addr_override}",
                            f"בוצעה בדיקת Tiber.co.il לכתובת '{new_addr_override}' [TIBER_ADDR:{new_addr_override}] [TIBER_TOP_NET:{top_no['network']} ({top_no['antennas_count']} אנטנות, כ-{top_no['nearest_m']} מטר)]",
                            cell_req_id,
                        ),
                    )
                    conn.commit()
                    conn.close()
                except Exception:
                    pass
                send_whatsapp_message(sender_phone, tiber_override["reply"], raw_chat_id)
                save_chat_message(sender_phone, "customer", message_text)
                save_chat_message(sender_phone, "agent", tiber_override["reply"])
                return {
                    "ok": True,
                    "reply": tiber_override["reply"],
                    "type": "tiber_summary_asked_device_type",
                    "address": new_addr_override,
                    "top_network": tiber_override["top_network"],
                    "networks": tiber_override["networks"],
                    "data_source": tiber_override.get("data_source"),
                    "escalated": False,
                }

        # STAGE B1: Customer is answering "מכשיר רגיל או מכשיר כשר?" ('awaiting_cellular_device_type')
        if cell_status == "awaiting_cellular_device_type" and not (pkg_det_any.get("matched") and has_callback_intent):
            dev_choice = detect_cellular_device_type_choice(message_text)
            reg_filter = detect_cellular_regular_filter_choice(message_text)

            if is_cellular_expand_request(message_text) and not dev_choice:
                tiber_exp = lookup_tiber_antennas_and_packages(saved_addr, mode="all", device_type=saved_dev_type)
                reply_exp = tiber_exp["reply"]
                try:
                    conn = sqlite3.connect(DB_PATH)
                    conn.execute("UPDATE customer_requests SET status='awaiting_cellular_plan_selection' WHERE id=?", (cell_req_id,))
                    conn.commit()
                    conn.close()
                except Exception:
                    pass
                send_whatsapp_message(sender_phone, reply_exp, raw_chat_id)
                save_chat_message(sender_phone, "customer", message_text)
                save_chat_message(sender_phone, "agent", reply_exp)
                return {"ok": True, "reply": reply_exp, "type": "tiber_expanded_all_results", "address": saved_addr, "escalated": False}

            if dev_choice == "kosher":
                tiber_k = lookup_tiber_antennas_and_packages(saved_addr, mode="kosher", device_type="kosher")
                reply_k = tiber_k["reply"]
                try:
                    conn = sqlite3.connect(DB_PATH)
                    conn.execute(
                        "UPDATE customer_requests SET status='awaiting_cellular_plan_selection', action_taken=? WHERE id=?",
                        (f"{cell_action_taken} [DEVICE_TYPE:kosher]", cell_req_id)
                    )
                    conn.commit()
                    conn.close()
                except Exception:
                    pass
                send_whatsapp_message(sender_phone, reply_k, raw_chat_id)
                save_chat_message(sender_phone, "customer", message_text)
                save_chat_message(sender_phone, "agent", reply_k)
                return {"ok": True, "reply": reply_k, "type": "tiber_kosher_packages", "address": saved_addr, "escalated": False}

            if dev_choice == "regular" or reg_filter in ("cheapest", "fastest", "all"):
                # If customer already included their filter choice in the same message (e.g. "רגיל הכי זול" or "רגיל גלישה מהירה")
                if reg_filter in ("cheapest", "fastest", "all"):
                    mode_map = {"cheapest": "regular_cheapest", "fastest": "regular_fastest", "all": "all"}
                    tiber_rf = lookup_tiber_antennas_and_packages(saved_addr, mode=mode_map[reg_filter], device_type="regular")
                    reply_rf = tiber_rf["reply"]
                    try:
                        conn = sqlite3.connect(DB_PATH)
                        conn.execute(
                            "UPDATE customer_requests SET status='awaiting_cellular_plan_selection', action_taken=? WHERE id=?",
                            (f"{cell_action_taken} [DEVICE_TYPE:regular] [FILTER:{reg_filter}]", cell_req_id)
                        )
                        conn.commit()
                        conn.close()
                    except Exception:
                        pass
                    send_whatsapp_message(sender_phone, reply_rf, raw_chat_id)
                    save_chat_message(sender_phone, "customer", message_text)
                    save_chat_message(sender_phone, "agent", reply_rf)
                    return {"ok": True, "reply": reply_rf, "type": f"tiber_regular_{reg_filter}_packages", "address": saved_addr, "escalated": False}

                # Otherwise ask how they want to filter regular packages (cheapest, fastest 5G, or see all)
                top_net_short = saved_top_net.split("(")[0].strip() if saved_top_net else ""
                reply_ask_filter = format_regular_filter_question(saved_addr, top_net_short)
                try:
                    conn = sqlite3.connect(DB_PATH)
                    conn.execute(
                        "UPDATE customer_requests SET status='awaiting_cellular_regular_filter', action_taken=? WHERE id=?",
                        (f"{cell_action_taken} [DEVICE_TYPE:regular]", cell_req_id)
                    )
                    conn.commit()
                    conn.close()
                except Exception:
                    pass
                send_whatsapp_message(sender_phone, reply_ask_filter, raw_chat_id)
                save_chat_message(sender_phone, "customer", message_text)
                save_chat_message(sender_phone, "agent", reply_ask_filter)
                return {
                    "ok": True,
                    "reply": reply_ask_filter,
                    "type": "asked_customer_regular_filter",
                    "address": saved_addr,
                    "escalated": False,
                }

            # If customer sent another address while in awaiting_cellular_device_type
            new_addr_in_dt = extract_israeli_address_from_text(message_text)
            if new_addr_in_dt:
                tiber_new = lookup_tiber_antennas_and_packages(new_addr_in_dt, mode="summary_ask_device_type")
                top_n = tiber_new["top_network"]
                try:
                    conn = sqlite3.connect(DB_PATH)
                    conn.execute(
                        "UPDATE customer_requests SET status='awaiting_cellular_device_type', action_taken=? WHERE id=?",
                        (f"בוצעה בדיקת Tiber.co.il לכתובת '{new_addr_in_dt}' [TIBER_ADDR:{new_addr_in_dt}] [TIBER_TOP_NET:{top_n['network']} ({top_n['antennas_count']} אנטנות, כ-{top_n['nearest_m']} מטר)]", cell_req_id)
                    )
                    conn.commit()
                    conn.close()
                except Exception:
                    pass
                send_whatsapp_message(sender_phone, tiber_new["reply"], raw_chat_id)
                save_chat_message(sender_phone, "customer", message_text)
                save_chat_message(sender_phone, "agent", tiber_new["reply"])
                return {"ok": True, "reply": tiber_new["reply"], "type": "tiber_summary_asked_device_type", "address": new_addr_in_dt, "escalated": False}

            # Clarify politely if they didn't say regular or kosher
            reply_clarify_dt = "כדי שאציג לך את החבילות המתאימות ביותר — האם מדובר ב*מכשיר רגיל* או ב*מכשיר כשר*? 📱"
            send_whatsapp_message(sender_phone, reply_clarify_dt, raw_chat_id)
            save_chat_message(sender_phone, "customer", message_text)
            save_chat_message(sender_phone, "agent", reply_clarify_dt)
            return {"ok": True, "reply": reply_clarify_dt, "type": "clarify_cellular_device_type", "escalated": False}

        # STAGE B2: Customer chose Regular device and is now choosing a filter ('awaiting_cellular_regular_filter')
        if cell_status == "awaiting_cellular_regular_filter" and not (pkg_det_any.get("matched") and has_callback_intent):
            reg_filter = detect_cellular_regular_filter_choice(message_text)
            dev_switch = detect_cellular_device_type_choice(message_text)

            if dev_switch == "kosher" and not reg_filter:
                tiber_k = lookup_tiber_antennas_and_packages(saved_addr, mode="kosher", device_type="kosher")
                reply_k = tiber_k["reply"]
                try:
                    conn = sqlite3.connect(DB_PATH)
                    conn.execute(
                        "UPDATE customer_requests SET status='awaiting_cellular_plan_selection', action_taken=? WHERE id=?",
                        (f"{cell_action_taken} [DEVICE_TYPE:kosher]", cell_req_id)
                    )
                    conn.commit()
                    conn.close()
                except Exception:
                    pass
                send_whatsapp_message(sender_phone, reply_k, raw_chat_id)
                save_chat_message(sender_phone, "customer", message_text)
                save_chat_message(sender_phone, "agent", reply_k)
                return {"ok": True, "reply": reply_k, "type": "tiber_kosher_packages", "address": saved_addr, "escalated": False}

            if reg_filter in ("cheapest", "fastest", "all") or is_cellular_expand_request(message_text):
                eff_filter = reg_filter or "all"
                mode_map = {"cheapest": "regular_cheapest", "fastest": "regular_fastest", "all": "all"}
                tiber_rf = lookup_tiber_antennas_and_packages(saved_addr, mode=mode_map[eff_filter], device_type="regular")
                reply_rf = tiber_rf["reply"]
                try:
                    conn = sqlite3.connect(DB_PATH)
                    conn.execute(
                        "UPDATE customer_requests SET status='awaiting_cellular_plan_selection', action_taken=? WHERE id=?",
                        (f"{cell_action_taken} [FILTER:{eff_filter}]", cell_req_id)
                    )
                    conn.commit()
                    conn.close()
                except Exception:
                    pass
                send_whatsapp_message(sender_phone, reply_rf, raw_chat_id)
                save_chat_message(sender_phone, "customer", message_text)
                save_chat_message(sender_phone, "agent", reply_rf)
                return {
                    "ok": True,
                    "reply": reply_rf,
                    "type": f"tiber_regular_{eff_filter}_packages",
                    "address": saved_addr,
                    "escalated": False,
                }

            # If customer didn't pick a filter or package yet, remind them of the 3 options
            top_net_short = saved_top_net.split("(")[0].strip() if saved_top_net else ""
            reply_remind_filter = format_regular_filter_question(saved_addr, top_net_short)
            send_whatsapp_message(sender_phone, reply_remind_filter, raw_chat_id)
            save_chat_message(sender_phone, "customer", message_text)
            save_chat_message(sender_phone, "agent", reply_remind_filter)
            return {"ok": True, "reply": reply_remind_filter, "type": "asked_customer_regular_filter", "escalated": False}

        # STAGE C: Customer received packages (or jumped directly to selecting a package) ('awaiting_cellular_plan_selection', 'awaiting_cellular_callback_info', or direct match)
        if cell_status in ("awaiting_cellular_plan_selection", "awaiting_cellular_callback_info", "awaiting_cellular_device_type", "awaiting_cellular_regular_filter"):
            # 1. Check if customer is asking to expand / see all offers / switch filter
            if is_cellular_expand_request(message_text) and not pkg_det_any.get("matched"):
                tiber_exp = lookup_tiber_antennas_and_packages(saved_addr, mode="all", device_type=saved_dev_type)
                send_whatsapp_message(sender_phone, tiber_exp["reply"], raw_chat_id)
                save_chat_message(sender_phone, "customer", message_text)
                save_chat_message(sender_phone, "agent", tiber_exp["reply"])
                return {"ok": True, "reply": tiber_exp["reply"], "type": "tiber_expanded_all_results", "address": saved_addr, "escalated": False}

            switch_filter = detect_cellular_regular_filter_choice(message_text)
            if switch_filter in ("cheapest", "fastest") and not pkg_det_any.get("matched") and not has_callback_intent:
                mode_map = {"cheapest": "regular_cheapest", "fastest": "regular_fastest"}
                tiber_sf = lookup_tiber_antennas_and_packages(saved_addr, mode=mode_map[switch_filter], device_type="regular")
                send_whatsapp_message(sender_phone, tiber_sf["reply"], raw_chat_id)
                save_chat_message(sender_phone, "customer", message_text)
                save_chat_message(sender_phone, "agent", tiber_sf["reply"])
                return {"ok": True, "reply": tiber_sf["reply"], "type": f"tiber_regular_{switch_filter}_packages", "address": saved_addr, "escalated": False}

            # 2. Check if customer wants to check a DIFFERENT address
            addr_pre = extract_israeli_address_from_text(message_text) if not pkg_det_any.get("matched") else ""
            if addr_pre and not any(w in cust_clean_cell for w in ["קוראים לי", "שמי", "תחזור", "תחזרו"]):
                tiber_res2 = lookup_tiber_antennas_and_packages(addr_pre, mode="summary_ask_device_type")
                top_n2 = tiber_res2["top_network"]
                try:
                    conn = sqlite3.connect(DB_PATH)
                    conn.execute(
                        "UPDATE customer_requests SET status='awaiting_cellular_device_type', action_taken=? WHERE id=?",
                        (f"בוצעה בדיקת Tiber.co.il לכתובת '{addr_pre}' [TIBER_ADDR:{addr_pre}] [TIBER_TOP_NET:{top_n2['network']} ({top_n2['antennas_count']} אנטנות, כ-{top_n2['nearest_m']} מטר)]", cell_req_id)
                    )
                    conn.commit()
                    conn.close()
                except Exception:
                    pass
                send_whatsapp_message(sender_phone, tiber_res2["reply"], raw_chat_id)
                save_chat_message(sender_phone, "customer", message_text)
                save_chat_message(sender_phone, "agent", tiber_res2["reply"])
                return {
                    "ok": True,
                    "reply": tiber_res2["reply"],
                    "type": "tiber_summary_asked_device_type",
                    "address": addr_pre,
                    "top_network": tiber_res2["top_network"],
                    "networks": tiber_res2["networks"],
                    "escalated": False,
                }

            m_saved_pkg = re.search(r"\[CHOSEN_PKG:([^\]]+)\]", cell_action_taken or "")
            prev_chosen_pkg = m_saved_pkg.group(1).strip() if m_saved_pkg else ""

            chosen_pkg_str = pkg_det_any["package_summary"] if pkg_det_any.get("matched") else prev_chosen_pkg
            chosen_comp_str = pkg_det_any["company"] if pkg_det_any.get("matched") else ""

            cb_phone = detect_callback_phone_in_text(message_text, sender_phone) or cust_phone_fmt
            extracted_nm = extract_name_from_text(message_text)
            if extracted_nm and extracted_nm not in COMMON_NON_NAMES and normalize_phone(sender_phone) not in PERMANENT_CONTACTS:
                customer_name = extracted_nm
                save_contact_name(sender_phone, extracted_nm)

            wants_callback = (
                bool(pkg_det_any.get("matched"))
                or bool(prev_chosen_pkg)
                or is_satisfaction_yes(message_text)
                or any(w in cust_clean_cell for w in [
                    "תחזרו", "תחזור", "לחזור", "תתקשר", "להתקשר", "לנייד", "ניוד", "להתנייד",
                    "רוצה", "מעוניין", "אשמח", "כן", "בטח", "סגור", "מתאים"
                ])
            )

            if wants_callback:
                if not chosen_pkg_str:
                    try:
                        conn = sqlite3.connect(DB_PATH)
                        conn.execute(
                            "UPDATE customer_requests SET status='awaiting_cellular_callback_info' WHERE id=?",
                            (cell_req_id,)
                        )
                        conn.commit()
                        conn.close()
                    except Exception:
                        pass
                    reply_ask_pkg = (
                        "בשמחה! כדי שערן יחזור אליך מוכן לניוד — *לאיזו חברה וחבילה מהרשימה תרצה להתנייד?* "
                        "ומה *שמך ומספר הטלפון הנוח לחזרה*? 😃📲"
                    )
                    send_whatsapp_message(sender_phone, reply_ask_pkg, raw_chat_id)
                    save_chat_message(sender_phone, "customer", message_text)
                    save_chat_message(sender_phone, "agent", reply_ask_pkg)
                    return {
                        "ok": True,
                        "reply": reply_ask_pkg,
                        "type": "asked_customer_for_chosen_cellular_package",
                        "escalated": False,
                    }

                lead_name_display = customer_name or "לקוח בווצאפ"
                try:
                    conn = sqlite3.connect(DB_PATH)
                    conn.execute(
                        "UPDATE customer_requests SET status='handled', action_taken=? WHERE id=?",
                        (f"נשלח לערן ליד לניוד לקוח ({lead_name_display}, {cb_phone}) לחבילה: {chosen_pkg_str} (כתובת: {saved_addr})", cell_req_id)
                    )
                    conn.commit()
                    conn.close()
                except Exception:
                    pass

                name_sal = f" {customer_name}" if (customer_name and customer_name not in COMMON_NON_NAMES) else ""
                reply_port_confirmed = (
                    f"מעולה{name_sal}! העברתי כעת לערן את הבקשה לחזור אליך למספר *{cb_phone}* לצורך ניוד לחבילת *{chosen_pkg_str}*. 📲🙌\n"
                    f"ערן יחזור אליך בהקדם להשלמת הניוד!\n\n"
                    f"האם אוכל לעזור לך במשהו נוסף? 😃"
                )
                send_whatsapp_message(sender_phone, reply_port_confirmed, raw_chat_id)
                save_chat_message(sender_phone, "customer", message_text)
                save_chat_message(sender_phone, "agent", reply_port_confirmed)

                ts = std_time.time()
                PENDING_SATISFACTION_CHECKS[sender_phone] = ts
                asyncio.create_task(inactivity_closing_timer(sender_phone, ts, raw_chat_id, customer_name))

                target_admins = [adm for adm in admin_numbers_set if adm != sender_phone and adm != "972500000000"]
                if not target_admins:
                    target_admins = [adm for adm in ["972524043644", "972553164770"] if adm != sender_phone] or [sender_phone]

                admin_port_alert = (
                    f"📲 *בקשת חזרה ללקוח לצורך ניוד סלולר (בדיקת Tiber.co.il)!* [#REQ-{cell_req_id}]\n"
                    f"👤 *שם הלקוח:* {lead_name_display}\n"
                    f"📞 *מספר טלפון לחזרה:* *{cb_phone}* (ווצאפ פונה: {cust_phone_fmt})\n"
                    f"📍 *כתובת שנבדקה ב-Tiber:* {saved_addr}\n"
                    + (f"📡 *הרשת המומלצת בכתובת:* {saved_top_net}\n" if saved_top_net else "")
                    + f"🎯 *חבילת הסלולר אליה הלקוח מעוניין להתנייד:* *{chosen_pkg_str}*\n"
                    f"💬 *הודעת הלקוח:* \"{message_text}\"\n\n"
                    f"☎️ *נא לחזור ללקוח במספר {cb_phone} לצורך השלמת הניוד לחבילה המבוקשת!*"
                )
                for adm in target_admins:
                    send_whatsapp_message(adm, admin_port_alert)

                return {
                    "ok": True,
                    "reply": reply_port_confirmed,
                    "type": "cellular_porting_lead_sent_to_admin",
                    "customer_name": lead_name_display,
                    "callback_phone": cb_phone,
                    "address": saved_addr,
                    "chosen_package": chosen_pkg_str,
                    "chosen_company": chosen_comp_str,
                    "escalated": True,
                }

    # 0.6 CHECK IF CUSTOMER HAS AN ACTIVE OPEN DIALOGUE / ORDER OFFER / BIT PAYMENT (status IN ('awaiting_customer_reply', 'awaiting_price_check_consent', 'awaiting_bit_payment'))
    try:
        conn = sqlite3.connect(DB_PATH)
        active_open_row = conn.execute(
            "SELECT id, request_text, action_taken, status FROM customer_requests WHERE (phone = ? OR phone LIKE ?) AND status IN ('awaiting_customer_reply', 'awaiting_price_check_consent', 'awaiting_bit_payment') ORDER BY id DESC LIMIT 1",
            (sender_phone, f"%{sender_phone[-9:]}%")
        ).fetchone()
        conn.close()
    except Exception:
        active_open_row = None

    if active_open_row and not is_scheduling_request(message_text):
        open_req_id, open_req_text, open_action_taken, open_status = active_open_row
        cust_clean = message_text.strip().lower()
